window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0227", [{"word":"due to","ipa_uk":"/ˈdjuː tuː/","ipa_us":"/ˈduː tuː/","definition_zh":"由于；因为；归因于；应付给；预定于","definition_en":"because of, caused by; owed to a person or account; expected or scheduled to do something","core_image":"雾封住跑道，登机屏上一条条航班被划掉，旅客拖着箱子围在柜台前改签","scene":"清晨大雾封住机场，广播通知当天航班全部取消，旅客只能排队改签。All departures were cancelled due to thick fog.","sceneCN":"这里把结果回指到天气原因（第 1 个义项：由于、因为）；句意为所有出港航班因浓雾取消。图中可辨识物件：跑道灯、雾墙、登机屏、行李箱。","pos":[{"tag":"prep. phr.","zh":"介词短语：由于；因为（可作表语、后置定语，也可置于句首）"}],"collocations":[{"phrase":"due to bad weather","zh":"由于恶劣天气"},{"phrase":"due to illness","zh":"因病"},{"phrase":"be due to","zh":"归因于；预定于"},{"phrase":"due to the fact that","zh":"由于……这一事实（累赘式）"},{"phrase":"amounts due to suppliers","zh":"应付给供应商的款项"},{"phrase":"be due to arrive","zh":"预定到达"},{"phrase":"due to unforeseen circumstances","zh":"由于意外情况"}],"forms":[{"label":"固定短语","form":"due to"},{"label":"表语用法","form":"be due to + 名词"},{"label":"后置定语","form":"名词 + due to + 名词"},{"label":"句首用法","form":"Due to + 名词，主句"},{"label":"引出从句","form":"due to the fact that + 从句"},{"label":"时刻表用法","form":"be due to + 动词原形"},{"label":"财务用法","form":"amounts due to + 收款方"}],"derivatives":[{"word":"due","pos":"adj.","zh":"由同一词根直接作形容词，义为「到期的；应支付的；预定的」"},{"word":"duly","pos":"adv.","zh":"由形容词加副词词尾构成，义为「按时地；适当地」"},{"word":"undue","pos":"adj.","zh":"由否定前缀加形容词构成，义为「过度的；不当的」"},{"word":"overdue","pos":"adj.","zh":"由表示「超过」的前缀加形容词构成，义为「逾期的；早该发生的」"},{"word":"dues","pos":"n.","zh":"由形容词转作名词并加复数词尾，义为「会费；应缴费用」"}],"senses":[{"no":"01","title":"Because of a stated cause","titleCN":"由于某个原因","definition":"as a result of a cause that is named after the result","definitionCN":"由于句中已说明的原因而出现某种结果","example":"The match was abandoned due to rain.","exampleCN":"比赛因雨取消。","why":"The adjective behind the phrase meant owed, so the phrase points from a result back to what it owes its existence to.","whyCN":"短语背后的形容词本义是「被欠的」，因此整条短语从结果回指它所亏欠的原因。"},{"no":"02","title":"After the verb be: attributable to","titleCN":"作表语：归因于","definition":"used after be to say that a result can be attributed to something","definitionCN":"跟在系动词之后，说明结果可归因于某事","example":"The delay was due to a fault in the signal system.","exampleCN":"延误是由于信号系统故障造成的。","why":"Traditional grammar treats the phrase as adjectival, so it sits after be and explains the subject.","whyCN":"传统语法把它当作形容词性成分，因此跟在系动词后解释主语。"},{"no":"03","title":"Placed after a noun as a modifier","titleCN":"作后置定语","definition":"following a noun to identify the cause of that noun","definitionCN":"跟在名词之后，指出该名词的原因","example":"Accidents due to fatigue fell sharply after the new rota.","exampleCN":"因疲劳导致的事故在新排班后大幅下降。","why":"Modifying a noun directly, the phrase works like a shortened relative clause.","whyCN":"直接修饰名词时，这条短语相当于压缩后的关系从句。"},{"no":"04","title":"Opening a sentence in formal writing","titleCN":"正式写作中置于句首","definition":"introducing the cause at the start of a clause, common in reports and academic prose","definitionCN":"在句首引出原因，多见于报告与学术文体","example":"Due to limited storage, samples were processed within a week.","exampleCN":"由于存储条件有限，样品在一周内处理完毕。","why":"Sentence-initial use spread through scientific and administrative writing while the old adjectival rule loosened.","whyCN":"句首用法在科技与行政写作中扩散，同时旧的形容词性规则被放宽。"},{"no":"05","title":"Money owed to someone","titleCN":"应付给某方的款项","definition":"in accounting, an amount that is owed and payable to a person or supplier","definitionCN":"会计中应付给个人或供应商的款项","example":"The ledger lists amounts due to contractors.","exampleCN":"账簿列出应付给承包商的款项。","why":"The older sense of owed survives in finance, where the phrase keeps the creditor as its object.","whyCN":"「应支付」的旧义在财务中保留，短语后面接的正是收款方。"},{"no":"06","title":"Expected at a fixed time","titleCN":"预定于某时发生","definition":"with a verb of arrival or departure, expected or scheduled at a stated time","definitionCN":"与表示到达或出发的动词连用，指预定在某时发生","example":"The train is due to arrive at six.","exampleCN":"列车定于六点到达。","why":"Here owed refers to an obligation written into a timetable, and the infinitive names the scheduled event.","whyCN":"此处「应」指写进时刻表的义务，后面的不定式说明预定动作。"},{"no":"07","title":"The padded connector due to the fact that","titleCN":"累赘连接语「由于……这一事实」","definition":"a wordy way of introducing a clause, often criticised in editing guides","definitionCN":"引出从句的冗长说法，编辑指南常批评其累赘","example":"Sales rose due to the fact that the currency weakened.","exampleCN":"销售上升是由于货币走弱这一事实。","why":"When the cause is a full clause rather than a noun, writers pad the phrase instead of using because.","whyCN":"当原因是一个完整从句而非名词时，写作者便把这个短语撑长，而不用「因为」。"},{"no":"08","title":"Blame placed on a named factor","titleCN":"把责任归到某个因素","definition":"used to attribute an unwanted outcome to a single factor, often in official statements","definitionCN":"把不好的结果归到某一因素，常见于官方说明","example":"The outage was due to a single misconfigured server.","exampleCN":"这次服务中断是由于一台服务器配置错误。","why":"Attribution language lets an institution name a factor without naming the person responsible.","whyCN":"归因说法让机构能点出因素而不点出责任人。"},{"no":"09","title":"Interchangeable with the other causal phrase","titleCN":"与其他因果短语可互换","definition":"used as a plain causal preposition in modern speech, where the older placement rule is ignored","definitionCN":"现代口语中当作普通因果介词使用，旧的语法位置规则被忽略","example":"Due to a shortage of nurses, the ward closed early.","exampleCN":"由于护士不足，病房提前关闭。","why":"Both causal phrases descend from the language of debt, and speakers now treat them alike.","whyCN":"两个因果短语都出自「欠」的说法，说话人如今把它们同样对待。"}],"etymology":{"intro":{"en":"Due to joins the adjective due, meaning owed, with the preposition to. Due entered English through Old French deu, the past participle of devoir, to owe, from Latin debere, to owe, built from de-, away, and habere, to hold. The causal phrase grew out of the idea of something being owed to a cause.","cn":"这个短语由义为「应支付、应归」的形容词与介词合成。形容词经古法语进入英语，是表示「欠」的动词的过去分词，源头为拉丁语中同样表示「欠」的动词，由表示「离开」的前缀与表示「持有」的词根构成。因果义正是从「应归到某个原因」这一想法长出来的。"},"items":[{"era":"LATIN HABERE","en":"Habere meant to hold or have; with the prefix of removal it produced the verb meaning to owe, literally to hold something away from someone.","cn":"这个词意为持有、拥有；加上表示「拿走」的前缀后，构成表示「欠」的动词，字面是「把东西拿离某人」。"},{"era":"LATIN DEBERE","en":"Debere meant to owe, and its participle described a sum that is owed.","cn":"这个动词意为「欠」，其分词用来形容一笔应付款项。"},{"era":"OLD FRENCH DEU","en":"The Old French past participle carried the sense of owed into English, where it became the adjective due.","cn":"古法语的过去分词把「被欠的」这一意思带进英语，成为形容词。"},{"era":"ENGLISH DUE, 14TH CENTURY","en":"English due first described what is owed, then what is owed by a timetable, as in a train due at six.","cn":"英语中这个词先指「应支付的」，再指「按时刻表应到的」，例如六点应到的列车。"},{"era":"THE CAUSAL PHRASE, 19TH CENTURY","en":"The combination began to serve as a preposition of cause in the nineteenth century; its first attestation in that role is not precisely dated.","cn":"这一组合在十九世纪开始充当表示原因的介词；它进入这一角色的确切首见年代不确定。"},{"era":"MODERN USAGE DISPUTE","en":"Traditional guides insisted that the phrase follow the verb be, while modern usage allows it at the start of a sentence.","cn":"传统指南坚持它必须跟在系动词之后，现代用法则允许它出现在句首。"}]},"similar":{"note":{"en":"The first group shares the phrase frame or the same root; the second group names other ways of stating a cause.","cn":"第一组与本短语共享短语框架或同一词根；第二组是其他表示原因的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"due for","ipa":"/ˈdjuː fɔː/","tag":"near form","definition":"Scheduled to receive or undergo something soon.","definitionCN":"指预定不久将得到或经历某事。"},{"word":"due from","ipa":"/ˈdjuː frɒm/","tag":"accounting pair","definition":"In accounting, an amount owed by a debtor to the firm.","definitionCN":"会计中指债务人欠本企业的款项，方向与「应付」相反。"},{"word":"due date","ipa":"/ˈdjuː deɪt/","tag":"same root","definition":"The date by which a payment or task must be finished.","definitionCN":"指付款或任务必须完成的日期。"},{"word":"dues","ipa":"/djuːz/","tag":"same root","definition":"Regular payments required for membership.","definitionCN":"指会员须定期缴纳的费用。"},{"word":"do to","ipa":"/ˈduː tə/","tag":"different phrase","definition":"A verb phrase meaning to perform an action on something, which sounds almost the same.","definitionCN":"指对某物施加动作的动词短语，读音几乎相同，结构却完全不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"owing to","ipa":"/ˈəʊɪŋ tə/","tag":"near meaning","definition":"Because of; the phrase moves more freely in a sentence.","definitionCN":"由于；在句中的位置更自由。"},{"word":"because of","ipa":"/bɪˈkɒz əv/","tag":"near meaning","definition":"The most neutral causal preposition, followed by a noun or pronoun.","definitionCN":"最中性的因果介词，后接名词或代词。"},{"word":"on account of","ipa":"/ɒn əˈkaʊnt əv/","tag":"near meaning","definition":"Because of, often in formal or explanatory writing.","definitionCN":"由于，多用于正式或解释性文字。"},{"word":"as a result of","ipa":"/əz ə rɪˈzʌlt əv/","tag":"near meaning","definition":"Following from a cause, with the result brought into focus.","definitionCN":"由于……的结果，把结果放在焦点上。"},{"word":"thanks to","ipa":"/ˈθæŋks tə/","tag":"near meaning","definition":"Because of, usually with a fortunate or welcome result.","definitionCN":"多亏，通常引出积极结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the debt word behind the phrase and its two grammar positions.","cn":"正常联想沿着短语背后的「欠」义，串起固定搭配与两种语法位置。"},"normal":[{"en":"The adjective came from a word meaning owed, so the phrase points to what a result owes its existence to.","cn":"这个形容词本义是「欠」，所以短语指出结果欠了谁才得以发生。"},{"en":"After the verb be is the safe position; at the start of a sentence is the looser modern move.","cn":"跟在系动词之后最稳妥；放在句首则是较宽松的现代用法。"},{"en":"Amounts owed to suppliers is the accounting sense, where the phrase still means owed.","cn":"「应付给供应商的款项」是会计用法，短语仍保留「欠」的意思。"},{"en":"A train due at six keeps the timetable sense of a scheduled obligation.","cn":"六点应到的列车保留的是时刻表上的「应到」义务。"},{"en":"The padded connector is the version editors tell writers to replace with a single conjunction.","cn":"「由于……这一事实」是被编辑要求改写成单个连词的累赘版本。"}],"abstract":[{"en":"Debt and cause have the same shape: something is owed, and the cause is the creditor.","cn":"债务与因果是同一个形状：有东西被欠着，而原因就是债主。"},{"en":"A sentence may move the cause to the front, but the grammar of attribution stays behind.","cn":"句子可以把原因挪到最前面，但归因的语法始终留在原处。"},{"en":"Every explanatory phrase is a small accounting of why things happened.","cn":"每个解释性短语都是对「事情为何发生」所做的一笔小账。"}]},"examples":[{"en":"The flight was cancelled due to a technical fault.","cn":"航班因技术故障取消。"},{"en":"Due to heavy snow, the pass remained closed for three days.","cn":"由于大雪，山口封闭了三天。"},{"en":"She is due to present the findings next Friday.","cn":"她预定下周五报告研究结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「丢图」——图纸丢了，工期延误，追查原因就是「由于」：由于、因为","word":"due to"},"root":"形容词经古法语的过去分词形式来自拉丁语 debere「欠」，由表示「离开、向下」的前缀与表示「持有」的词根构成；这条短语的介词用法自十九世纪起流行，确切首见年代不确定。","sensesIntro":{"en":"Nine senses fall into four places: the cause itself, three grammatical positions, the money owed, and the timetable obligation.","cn":"九个义项落在四处：原因本身、三种语法位置、应付的款项、时刻表上的应到。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fog-bound airport board, every cancelled flight tied back to the weather.","cn":"核心意象：雾锁机场的航班屏，每条被划掉的航班都系回天气。"},"chain":["RESULT NAMED","CAUSE POINTED","ATTRIBUTION AFTER BE","NOUN MODIFIER","SUM OWED","TIME DUE"],"branches":[{"senses":"01 · 04","en":"THE PLAIN CAUSE: the phrase opens or closes a clause and names why something happened.","cn":"单纯原因：短语在句首或句末点明事情为何发生。"},{"senses":"02 · 03","en":"THE ATTRIBUTIVE POSITION: after the verb be or after a noun, the phrase explains the subject.","cn":"归属性位置：跟在系动词或名词之后，解释主语。"},{"senses":"05","en":"THE SUM OWED: in accounts the phrase still points to a creditor.","cn":"应付之款：在账目里，短语仍指向收款方。"},{"senses":"06","en":"THE TIMETABLE: the same adjective marks what is expected at a fixed hour.","cn":"时刻表：同一个形容词标记按固定时刻应到之事。"},{"senses":"07 · 08 · 09","en":"THE PADDED AND ATTRIBUTED CAUSE: the heavy connector, the official excuse, and the stylistic variant.","cn":"累赘与归因：冗长连接语、机构式交代、以及文体变体。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin verb of owing, so its parts are small pieces of a debt.","cn":"这条短语立在一个表示「欠」的拉丁动词上，各部件都是债务的一小块。"},"latinIntro":{"en":"Latin supplies the verb of owing, the verb of holding and the prefix of removal; Old French supplied the participle that became the adjective.","cn":"拉丁语提供了「欠」的动词、「持有」的词根与表示「拿走」的前缀；古法语提供了变成形容词的分词。"},"items":[{"word":"debere","structure":"Latin verb","meaning":"to owe","meaningCN":"欠","example":"A debt is literally what is held away from a person.","exampleCN":"债务字面上就是被拿离某人的东西。"},{"word":"de-","structure":"Latin prefix","meaning":"away from, down","meaningCN":"离开；向下","example":"It turns holding into owing.","exampleCN":"它把「持有」变成「欠」。"},{"word":"habere","structure":"Latin verb","meaning":"to hold, to have","meaningCN":"持有；拥有","example":"The root carries the idea of having something in hand.","exampleCN":"这个词根带着「手中有物」的意思。"},{"word":"deu","structure":"Old French participle","meaning":"owed","meaningCN":"被欠的","example":"It entered English as the adjective due.","exampleCN":"它作为形容词进入英语。"},{"word":"due","structure":"English adjective","meaning":"owed; expected","meaningCN":"应支付的；预定的","example":"The adjective carries both the debt and the timetable sense.","exampleCN":"这个形容词同时背着债务与时刻表两种意思。"},{"word":"to","structure":"English preposition","meaning":"towards; with respect to","meaningCN":"朝向；对于","example":"It links the adjective to the cause or the creditor.","exampleCN":"它把形容词挂到原因或收款方上。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb meaning on time or properly.","exampleCN":"它构成表示按时或适当的副词。"},{"word":"un-","structure":"English negative prefix","meaning":"not","meaningCN":"不","example":"It forms the adjective meaning excessive or improper.","exampleCN":"它构成表示过度或不当的形容词。"},{"word":"over-","structure":"English prefix","meaning":"beyond, too much","meaningCN":"超过；过度","example":"It forms the adjective meaning past the due date.","exampleCN":"它构成表示逾期的形容词。"},{"word":"due to","structure":"English prepositional phrase","meaning":"because of","meaningCN":"由于","example":"The whole phrase works as a causal preposition.","exampleCN":"整条短语充当因果介词。"}],"latinEntries":[{"word":"debere","structure":"Latin verb","meaning":"to owe","meaningCN":"欠"},{"word":"de-","structure":"Latin prefix","meaning":"away, down","meaningCN":"离开；向下"},{"word":"habere","structure":"Latin verb","meaning":"to hold, to have","meaningCN":"持有；拥有"},{"word":"debitus","structure":"Latin participle","meaning":"owed","meaningCN":"被欠的"}],"derivatives":[{"word":"due","pos":"adj.","zh":"由拉丁分词经古法语演变而来，义为「应支付的；预定的」"},{"word":"duly","pos":"adv.","zh":"由形容词加副词词尾构成，义为「按时地；适当地」"},{"word":"undue","pos":"adj.","zh":"由否定前缀加形容词构成，义为「过度的；不当的」"},{"word":"overdue","pos":"adj.","zh":"由表示「超过」的前缀加形容词构成，义为「逾期的」"},{"word":"dues","pos":"n.","zh":"由形容词转作名词并加复数词尾，义为「会费；应缴费用」"}]}},{"word":"owing to","ipa_uk":"/ˈəʊɪŋ tuː/","ipa_us":"/ˈoʊɪŋ tuː/","definition_zh":"由于；因为；应付给（某人）的","definition_en":"because of; on account of; (of a sum) owed and payable to someone","core_image":"渡轮停航，码头候船室里挤满滞留旅客，白浪一层层压向岸壁","scene":"暴雨冲断进山的公路，渡轮也停了，岛上游客在候船室过了一夜。Ferry services were suspended owing to the storm.","sceneCN":"这里点明停航的原因（第 1 个义项：由于、因为）；句意为渡轮服务因风暴暂停。图中可辨识物件：白浪、码头、候船室、行李。","pos":[{"tag":"prep. phr.","zh":"介词短语：由于；因为（多作状语，可置于句首或句末）"}],"collocations":[{"phrase":"owing to bad weather","zh":"由于恶劣天气"},{"phrase":"owing to illness","zh":"因病"},{"phrase":"owing to the fact that","zh":"由于……这一事实"},{"phrase":"owing to circumstances beyond our control","zh":"由于无法控制的情况"},{"phrase":"owing to a lack of funds","zh":"由于资金不足"},{"phrase":"sums owing to the estate","zh":"应付给遗产的款项"}],"forms":[{"label":"固定短语","form":"owing to"},{"label":"状语位置（句首）","form":"Owing to + 名词，主句"},{"label":"状语位置（句末）","form":"主句 + owing to + 名词"},{"label":"后置定语","form":"名词 + owing to + 名词"},{"label":"引出从句","form":"owing to the fact that + 从句"},{"label":"分词用法","form":"owing（欠着的）"}],"derivatives":[{"word":"owe","pos":"v.","zh":"由古英语动词直接演变成现代动词，义为「欠；应把……归功于」"},{"word":"owing","pos":"adj.","zh":"由该动词加现在分词词尾构成，义为「欠着的；未付的」"},{"word":"owed","pos":"adj.","zh":"由该动词加过去分词词尾构成，义为「被欠的；未偿还的」"},{"word":"ought","pos":"modal v.","zh":"由该动词的旧过去式演变而来，义为「应当」"},{"word":"own","pos":"v./adj.","zh":"由同一古英语动词的另一支演变而来，义为「拥有；自己的」"},{"word":"owner","pos":"n.","zh":"由「拥有」义加表示施动者的名词词尾构成，义为「所有者」"}],"senses":[{"no":"01","title":"Because of a cause","titleCN":"由于某个原因","definition":"as a result of a cause that is named","definitionCN":"由于句中已说明的原因而发生","example":"The game was postponed owing to fog.","exampleCN":"比赛因大雾延期。","why":"Owing began as the participle of owe, so the phrase names what a result owes itself to.","whyCN":"这个分词本是表示「欠」的动词的现在分词，因此短语说明结果欠了谁。"},{"no":"02","title":"Opening a clause with the cause","titleCN":"置于句首引出原因","definition":"leading the sentence with the cause, a position the phrase takes freely as an adverbial","definitionCN":"把原因放在句首，这是它作为状语可自由占据的位置","example":"Owing to the strike, buses stopped running.","exampleCN":"由于罢工，公交车停运。","why":"Grown from a participle phrase, it behaves like an adverbial and can lead the clause.","whyCN":"它由分词短语长成，像状语一样可以领起从句。"},{"no":"03","title":"Following a noun","titleCN":"跟在名词之后","definition":"placed after a noun in reports to explain that noun, like a shortened relative clause","definitionCN":"在报告中置于名词之后解释该名词，相当于压缩的关系从句","example":"Losses owing to exchange rates were reported separately.","exampleCN":"因汇率造成的损失另行报告。","why":"Financial writing packs the cause behind the noun it explains, keeping the sentence compact.","whyCN":"财务文本把原因压在它所解释的名词之后，使句子紧凑。"},{"no":"04","title":"The padded connector owing to the fact that","titleCN":"累赘连接语「由于……这一事实」","definition":"a wordy way of introducing a full clause as the cause","definitionCN":"以冗长方式引出一个完整从句作为原因","example":"Output fell owing to the fact that two lines were idle.","exampleCN":"产量下降是由于两条生产线停着。","why":"A full clause cannot follow the plain phrase, so writers pad it with a noun of fact.","whyCN":"完整从句不能直接跟在短语后面，于是写作者用「事实」这个名词来撑开。"},{"no":"05","title":"Money still owed to someone","titleCN":"仍应付给某方的款项","definition":"in accounts, an amount that is owed and payable to a person or estate","definitionCN":"在账目中应付给个人或遗产的款项","example":"The statement lists the sums owing to the estate.","exampleCN":"报表列出应付给遗产的款项。","why":"This is the oldest literal sense: the participle still means owed, and the phrase still takes a creditor.","whyCN":"这是最古老的字面义：分词本义仍是「被欠的」，短语后面仍接收款方。"},{"no":"06","title":"In legal and procedural writing","titleCN":"用于法律与程序文本","definition":"used in formal notices to explain a procedural default","definitionCN":"在正式通告中解释程序上的缺失","example":"Owing to the absence of a quorum, the vote was deferred.","exampleCN":"由于不足法定人数，表决被推迟。","why":"Legal drafting prefers the phrase for a neutral, impersonal statement of cause.","whyCN":"法律起草偏爱这个短语，因为它能中立而不带人称地交代原因。"},{"no":"07","title":"Standard excuse in business letters","titleCN":"商务信函中的标准托辞","definition":"a set phrase in commercial correspondence for delays outside the seller's control","definitionCN":"商务信函中说明卖方无法控制的延误的固定说法","example":"Owing to circumstances beyond our control, delivery is delayed.","exampleCN":"由于无法控制的情况，交货延迟。","why":"Commercial letters turned the causal phrase into a polite formula for bad news.","whyCN":"商务信函把这条因果短语变成了传达坏消息的礼貌套语。"},{"no":"08","title":"The traditional alternative to the other causal phrase","titleCN":"另一个因果短语的传统替代说法","definition":"used as a free adverbial where older guidebooks reserved the other phrase for the position after be","definitionCN":"作为自由状语使用，旧的语法书则把另一个因果短语留给系动词之后的位置","example":"Owing to staff shortages, the counter closed at noon.","exampleCN":"由于人手不足，柜台中午就关了。","why":"Guidebooks once divided the labour: this phrase for adverbial positions, the other one for the verb be.","whyCN":"旧语法书曾分工：这个短语用于状语位置，另一个用于系动词之后。"},{"no":"09","title":"Attribution in reporting style","titleCN":"报道文体中的归因","definition":"used after the verb be in British reporting to attribute a change to a cause","definitionCN":"英国报道文体中跟在系动词后，把变化归到某个原因","example":"The rise in cost was owing to higher freight charges.","exampleCN":"成本上升是由于运费上涨。","why":"British journalism kept the phrase after the verb be long after American usage moved on.","whyCN":"英国新闻写作在系动词后长期保留这一短语，美国用法则早已改换。"}],"etymology":{"intro":{"en":"Owing to joins the present participle of owe with the preposition to. Owe goes back to Old English agan, to own or have, whose past tense also produced ought. The participle meant what is owed, and from the eighteenth century the phrase came to mean because of.","cn":"这条短语由表示「欠」的动词的现在分词与介词合成。该动词可追溯到古英语中表示「拥有、持有」的词，其过去式还演变出表示「应当」的情态动词。分词本义是「被欠着的」，从十八世纪起，整条短语转指「由于」。"},"items":[{"era":"OLD ENGLISH AGAN","en":"The verb meant to own or possess, and its past tense also gave the modal of obligation.","cn":"这个动词意为拥有、持有，其过去式还演变出表示义务的情态动词。"},{"era":"OWING AS A PARTICIPLE","en":"By the fourteenth century the participle described a sum still owed to someone.","cn":"到十四世纪，这个分词已用来形容仍欠某人的款项。"},{"era":"THE PHRASE TURNS CAUSAL, 18TH CENTURY","en":"In the eighteenth century the phrase began to introduce a cause rather than a creditor; the exact first date is uncertain.","cn":"十八世纪起，这条短语引出的是原因而非债主；确切首见年代不确定。"},{"era":"ADVERBIAL FREEDOM","en":"Because it grew out of a participle phrase, it moves freely to the front of a clause.","cn":"由于它从分词短语长成，位置可以自由移到从句开头。"},{"era":"COMMERCE AND LAW","en":"Business letters and legal notices adopted the phrase for delays and procedural defaults.","cn":"商务信函与法律通告采用这条短语来说明延误与程序缺失。"},{"era":"BRITISH FAVOUR","en":"British writing kept the phrase for formal causes while American usage leaned towards the rival form.","cn":"英国写作在正式原因上保留这条短语，美国用法则偏向另一个竞争形式。"}]},"similar":{"note":{"en":"The first group shares the root or the participle; the second group lists other causal expressions.","cn":"第一组共享同一词根或同一分词；第二组是其他因果表达。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"owing","ipa":"/ˈəʊɪŋ/","tag":"same root","definition":"Still owed; also the participle behind the phrase.","definitionCN":"仍欠着的；也是这条短语背后的分词。"},{"word":"owe","ipa":"/əʊ/","tag":"same root","definition":"To be under an obligation to pay or to credit someone.","definitionCN":"指欠钱，或应把功劳归给某人。"},{"word":"ought","ipa":"/ɔːt/","tag":"same root","definition":"The modal of obligation that grew from the old past tense.","definitionCN":"由旧过去式演变来的表示义务的情态动词。"},{"word":"own","ipa":"/əʊn/","tag":"same root","definition":"To possess, from the same Old English verb.","definitionCN":"拥有，出自同一个古英语动词。"},{"word":"owner","ipa":"/ˈəʊnə/","tag":"same root","definition":"One who possesses something.","definitionCN":"指拥有某物的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"due to","ipa":"/ˈdjuː tuː/","tag":"near meaning","definition":"Because of; traditionally the attributive member of the pair.","definitionCN":"由于；传统上这一对短语中的表语成员。"},{"word":"because of","ipa":"/bɪˈkɒz əv/","tag":"near meaning","definition":"The plainest causal preposition with a noun object.","definitionCN":"最朴素的因果介词，后接名词。"},{"word":"on account of","ipa":"/ɒn əˈkaʊnt əv/","tag":"near meaning","definition":"Because of, common in formal explanation.","definitionCN":"由于，常见于正式解释。"},{"word":"as a consequence of","ipa":"/əz ə ˈkɒnsɪkwəns əv/","tag":"near meaning","definition":"Following from an earlier cause, with the outcome in view.","definitionCN":"由于先前的原因，着眼于结果。"},{"word":"by reason of","ipa":"/baɪ ˈriːzn əv/","tag":"near meaning","definition":"A legal and official way of saying because of.","definitionCN":"法律与公文里表示「由于」的说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the participle of owing, its accounting sense and its freedom of position.","cn":"正常联想沿着「欠」的分词义，串起账目用法与位置自由。"},"normal":[{"en":"The participle means owed, so a result owing to a cause is a result in debt to it.","cn":"分词意为「被欠的」，所以因某原因而发生的结果，就是欠那个原因一笔。"},{"en":"This phrase may lead the sentence, which the rival causal phrase traditionally may not.","cn":"这条短语可以领起句子，而另一个因果短语传统上不行。"},{"en":"Sums owing to the estate is the literal accounting use, unchanged in meaning for centuries.","cn":"「应付给遗产的款项」是字面账目用法，几个世纪意思都没变。"},{"en":"Business letters use the phrase with circumstances beyond control, a polite formula for delay.","cn":"商务信函把它与「无法控制的情况」连用，成为说明延误的礼貌套语。"},{"en":"Legal notices use it for a missing quorum, where no person needs to be blamed.","cn":"法律通告用它说明人数不足，不必归咎于任何个人。"}],"abstract":[{"en":"A participle of debt turned into a preposition of cause: obligation became explanation.","cn":"「欠」的分词变成了因果介词：义务变成了解释。"},{"en":"To say owing to is to admit that the outcome was already owed to something else.","cn":"说「由于」，等于承认结果本来就该记在别的东西账上。"},{"en":"Freedom of position is freedom of blame: the cause can stand in front of the sentence.","cn":"位置自由就是归责自由：原因可以站到整句前面。"}]},"examples":[{"en":"Owing to a broken pump, the pool stayed closed all week.","cn":"由于水泵损坏，泳池整周关闭。"},{"en":"The order was delayed owing to a shortage of drivers.","cn":"订单因司机短缺而延误。"},{"en":"Owing to the chairman's illness, the meeting was moved online.","cn":"由于主席生病，会议改为线上举行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「欧应」——欧洲的货应到未到，追问缘由就是「由于」：由于、因为","word":"owing to"},"root":"这个现在分词出自古英语中意为「拥有、欠」的动词，其过去式演变为表「应当」的情态动词；这条短语自十八世纪起表示「由于」，确切首见年代不确定。纯英语本族来源，无拉丁同族词。","sensesIntro":{"en":"Nine senses follow the participle from a literal debt to a free adverbial, and then to legal and commercial formulas.","cn":"九个义项沿着这个分词从字面债务走到自由状语，再到法律与商务套语。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stranded ferry queue, every passenger kept ashore by the same storm.","cn":"核心意象：滞留的渡轮队伍，每个旅客都被同一场风暴困在岸上。"},"chain":["DEBT OWED","PARTICIPLE PHRASE","CAUSE NAMED","FRONT POSITION","LEGAL NOTICE","BUSINESS FORMULA"],"branches":[{"senses":"01 · 02","en":"THE FREE CAUSE: the phrase names a cause and may lead the clause.","cn":"自由原因：短语点明原因，并可领起从句。"},{"senses":"03 · 04","en":"THE PACKED CAUSE: behind a noun, or padded with a noun of fact before a clause.","cn":"压缩原因：压在名词之后，或用「事实」撑开再接从句。"},{"senses":"05","en":"THE LITERAL DEBT: the same participle still points at a creditor in accounts.","cn":"字面债务：同一个分词在账目里仍指向收款方。"},{"senses":"06 · 07","en":"THE INSTITUTIONAL EXCUSE: procedural defaults and delays beyond control.","cn":"机构式交代：程序缺失与无法控制的延误。"},{"senses":"08 · 09","en":"THE STYLE CHOICE: a traditional adverbial and a British reporting habit.","cn":"文体选择：传统状语用法与英国报道习惯。"}]},"affixes":{"intro":{"en":"The phrase is built from an Old English verb of possession, so its parts are native rather than borrowed.","cn":"这条短语由古英语的「拥有」动词构成，各部件都是本族成分而非借词。"},"latinIntro":{"en":"There is no Latin source for this family: it comes from Old English, so the Latin list stays empty.","cn":"这一族词没有拉丁语来源，出自古英语，因此拉丁词条留空。"},"items":[{"word":"agan","structure":"Old English verb","meaning":"to own, to have","meaningCN":"拥有；持有","example":"The verb held both possession and obligation.","exampleCN":"这个动词同时含「拥有」与「应还」两层。"},{"word":"ahte","structure":"Old English past tense","meaning":"owned; owed","meaningCN":"曾拥有；曾欠","example":"Its past tense later became the modal of obligation.","exampleCN":"它的过去式后来变成表义务的情态动词。"},{"word":"owe","structure":"English verb","meaning":"to be obliged to pay","meaningCN":"欠；应给予","example":"The modern verb keeps the debt sense.","exampleCN":"现代动词保留债务义。"},{"word":"-ing","structure":"English participle ending","meaning":"in the state of","meaningCN":"处于……状态","example":"It forms the participle meaning still owed.","exampleCN":"它构成表示「仍被欠着」的分词。"},{"word":"owed","structure":"English participle","meaning":"not yet paid","meaningCN":"未付的","example":"The past participle keeps the accounting sense.","exampleCN":"过去分词保留账目义。"},{"word":"ought","structure":"English modal verb","meaning":"should","meaningCN":"应当","example":"It descends from the old past tense.","exampleCN":"它由旧过去式演变而来。"},{"word":"own","structure":"English verb and adjective","meaning":"to possess; belonging to oneself","meaningCN":"拥有；自己的","example":"A second branch of the same old verb.","exampleCN":"同一个古动词的另一支。"},{"word":"owner","structure":"English noun","meaning":"the one who possesses","meaningCN":"所有者","example":"The agent noun of the possession branch.","exampleCN":"「拥有」这一支的施动名词。"},{"word":"to","structure":"English preposition","meaning":"towards; with respect to","meaningCN":"朝向；对于","example":"It carries the cause or the creditor after the participle.","exampleCN":"它在分词后接原因或收款方。"},{"word":"owing to","structure":"English prepositional phrase","meaning":"because of","meaningCN":"由于","example":"The whole phrase works as a causal adverbial.","exampleCN":"整条短语充当因果状语。"}],"latinEntries":[],"derivatives":[{"word":"owe","pos":"v.","zh":"由古英语动词直接演变，义为「欠；应归功于」"},{"word":"owing","pos":"adj.","zh":"加现在分词词尾构成，义为「欠着的」"},{"word":"owed","pos":"adj.","zh":"加过去分词词尾构成，义为「被欠的」"},{"word":"ought","pos":"modal v.","zh":"由旧过去式演变，义为「应当」"},{"word":"own","pos":"v./adj.","zh":"由同一动词的另一支演变，义为「拥有；自己的」"}]}},{"word":"regardless of","ipa_uk":"/rɪˈɡɑːdləs ɒv/","ipa_us":"/rɪˈɡɑːrdləs ɑːv/","definition_zh":"不管；不顾；无论；不理会","definition_en":"without being affected or stopped by; irrespective of","core_image":"巷道口的警铃连响，红灯旋转，送料车仍一辆接一辆往里开","scene":"警报连响三遍，红灯一直转，管理员仍让送料车往巷道里开。The operator kept loading the shaft regardless of the warning lights.","sceneCN":"这里指不因警示而停止（第 2 个义项：不顾、不理会）；句意为操作员无视警示灯，继续往井巷送料。图中可辨识物件：警铃、红灯、送料车、巷道口。","pos":[{"tag":"prep. phr.","zh":"介词短语：不管；不顾；无论"},{"tag":"adv.","zh":"相关副词用法（不带宾语）：无论如何；照样"}],"collocations":[{"phrase":"regardless of cost","zh":"不顾成本"},{"phrase":"regardless of age","zh":"不论年龄"},{"phrase":"regardless of whether","zh":"无论是否"},{"phrase":"regardless of the outcome","zh":"不管结果如何"},{"phrase":"regardless of the consequences","zh":"不顾后果"},{"phrase":"regardless of rank","zh":"不论级别"}],"forms":[{"label":"固定短语","form":"regardless of"},{"label":"引出选择问","form":"regardless of whether + 从句"},{"label":"引出条件","form":"regardless of + 名词"},{"label":"副词用法","form":"regardless（不带宾语，义为「照样」）"},{"label":"否定词尾形式","form":"regard + less（由「留意」加否定词尾构成）"}],"derivatives":[{"word":"regard","pos":"v./n.","zh":"同一词根的名词与动词，义为「注视；看待；尊重」"},{"word":"regardless","pos":"adv.","zh":"由该词根加否定词尾构成，义为「无论如何；照样」"},{"word":"regarding","pos":"prep.","zh":"由现在分词转作介词，义为「关于」"},{"word":"disregard","pos":"v./n.","zh":"由否定前缀加该词根构成，义为「无视；漠视」"},{"word":"regardful","pos":"adj.","zh":"由该词根加表示「充满」的形容词词尾构成，义为「留意的」"}],"senses":[{"no":"01","title":"Irrespective of a factor","titleCN":"不论某个因素","definition":"without that factor making any difference to the result","definitionCN":"某个因素对结果不产生任何影响","example":"Regardless of cost, the bridge must be rebuilt.","exampleCN":"不论成本多少，这座桥都必须重建。","why":"The phrase removes a factor from consideration, leaving the decision unchanged.","whyCN":"这条短语把某个因素从考虑中拿掉，决定因此不变。"},{"no":"02","title":"Despite a warning or obstacle","titleCN":"不顾警告或阻碍","definition":"continuing an action even though something warns against it","definitionCN":"即使有事物提出警告，仍继续行动","example":"He kept working regardless of the pain.","exampleCN":"他不顾疼痛继续干活。","why":"Attention is what the word root means; the negative ending says attention is withheld.","whyCN":"词根本义是「留意」，否定词尾表示「不留意」。"},{"no":"03","title":"Covering both alternatives","titleCN":"涵盖两种可能","definition":"followed by whether or if to state that both alternatives are included","definitionCN":"后接「是否」引出两种可能，表示两者都被包括","example":"The rule applies regardless of whether the firm is public.","exampleCN":"无论公司是否上市，这条规定都适用。","why":"A choice between two cases is folded into one statement by naming them as irrelevant.","whyCN":"把两种情形并列点出、再宣布其无关，就把选择折进了一句话。"},{"no":"04","title":"Without regard to a limit","titleCN":"不考虑限度","definition":"spending or acting with no reference to a stated limit","definitionCN":"花费或行动时不参照既定限度","example":"They spent regardless of the budget.","exampleCN":"他们不顾预算限制地花钱。","why":"The phrase can cancel a limit as easily as it cancels a warning.","whyCN":"这条短语取消警告，也同样可以取消限度。"},{"no":"05","title":"Ignoring a person's rank or feelings","titleCN":"不看身份、不顾感受","definition":"treating everyone the same, or ignoring how someone feels","definitionCN":"对所有人一视同仁，或无视某人的感受","example":"She spoke to everyone regardless of rank.","exampleCN":"她跟每个人说话都不看级别。","why":"Social equality and social indifference use the same phrase, separated only by context.","whyCN":"社会平等与社会冷漠用的是同一条短语，只靠语境区分。"},{"no":"06","title":"Universal rule in formal text","titleCN":"正式文本中的普遍规定","definition":"in regulations, stating that a rule covers all cases without exception","definitionCN":"在规章中说明某条规定无例外地覆盖所有情形","example":"Access is granted regardless of age.","exampleCN":"不论年龄，均可进入。","why":"Regulations need a phrase that switches off every distinguishing condition at once.","whyCN":"规章需要一条能把所有区分条件一次关掉的短语。"},{"no":"07","title":"Hedging a claim in academic writing","titleCN":"学术写作中的让步限定","definition":"used to say a pattern holds whatever method or sample is chosen","definitionCN":"用来说明无论采用哪种方法或样本，规律都成立","example":"The pattern holds regardless of the method used.","exampleCN":"无论采用哪种方法，这个规律都成立。","why":"A claim becomes more robust when it is said to survive every choice of method.","whyCN":"一旦声称结论经得起任何方法选择，论点就显得更稳固。"},{"no":"08","title":"The fixed phrase regardless of the outcome","titleCN":"固定说法「不管结果如何」","definition":"a set phrase stressing that effort will not depend on success","definitionCN":"固定说法，强调努力不取决于成败","example":"The team trained hard regardless of the outcome.","exampleCN":"无论结果如何，队伍都刻苦训练。","why":"Sporting and moral talk uses the phrase to separate effort from reward.","whyCN":"体育与道德话语用它把努力与回报分开。"},{"no":"09","title":"The fixed phrase regardless of the consequences","titleCN":"固定说法「不顾后果」","definition":"a set phrase stressing that no later harm will change the decision","definitionCN":"固定说法，强调后来的损害不会改变决定","example":"He approved the plan regardless of the consequences.","exampleCN":"他不顾后果批准了这项计划。","why":"Naming the consequences and dismissing them is the strongest form of the phrase.","whyCN":"把后果点出来再宣布不顾，是这条短语最强的形式。"}],"etymology":{"intro":{"en":"Regardless of joins regard and the negative ending -less. Regard came through Old French regarder, to look at, from a Germanic verb of watching or guarding. The ending -less descends from Old English leas, free from. The phrase became common in the nineteenth century.","cn":"这条短语由表示「注视、留意」的词根与否定词尾合成。该词根经古法语进入英语，源头是日耳曼语中表示看守、注视的动词；否定词尾来自古英语中表示「脱离、没有」的形容词。整条短语在十九世纪通行起来。"},"items":[{"era":"GERMANIC WARDON","en":"The deep source meant to watch or guard, and it also gave English ward and guard.","cn":"更早的词源意为看守、注视，还给出了英语中表示「看守」的两个词。"},{"era":"OLD FRENCH REGARDER","en":"The French verb meant to look at or look back at, built with a prefix of repetition.","cn":"这个法语动词意为注视、回望，由表示重复的前缀构成。"},{"era":"ENGLISH REGARD, 14TH CENTURY","en":"English regard first meant a look or attention, then esteem, and later a single point looked at.","cn":"英语中这个词先指目光或留意，再指尊重，后来又指所关注的一点。"},{"era":"THE ENDING -LESS","en":"The Old English adjective meant free from or without, and it forms privative adjectives such as countless and hopeless.","cn":"这个古英语形容词意为「没有、脱离」，构成表示「无」的形容词，如无数与无望。"},{"era":"REGARDLESS, 16TH CENTURY","en":"The adverb first meant without heed, and its earliest attested date is given only approximately.","cn":"这个副词最初意为「不留心」，其确切首见年代只能给约数。"},{"era":"THE PHRASE, 19TH CENTURY","en":"The prepositional phrase with of spread in the nineteenth century, first in careless speech and later in formal rules.","cn":"带介词宾语的短语在十九世纪扩散，先出现在随意的口语，后进入正式规章。"}]},"similar":{"note":{"en":"The first group shares the root or the negative ending; the second group names other ways of setting a condition aside.","cn":"第一组共享同一词根或否定词尾；第二组是其他把条件撇开的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"regard","ipa":"/rɪˈɡɑːd/","tag":"same root","definition":"To look at, to consider, or esteem as a noun.","definitionCN":"指注视、看待，作名词时指尊重。"},{"word":"regardless","ipa":"/rɪˈɡɑːdləs/","tag":"same root","definition":"The bare adverb meaning without heed, taking no object.","definitionCN":"不带宾语的副词，意为「照样、不顾」。"},{"word":"regarding","ipa":"/rɪˈɡɑːdɪŋ/","tag":"same root","definition":"A preposition meaning about or concerning.","definitionCN":"意为「关于」的介词。"},{"word":"disregard","ipa":"/ˌdɪsrɪˈɡɑːd/","tag":"same root","definition":"To ignore something deliberately, as verb or noun.","definitionCN":"指刻意无视，可作动词或名词。"},{"word":"regardful","ipa":"/rɪˈɡɑːdfəl/","tag":"same root","definition":"Attentive or mindful of something.","definitionCN":"指对某事留意的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"irrespective of","ipa":"/ˌɪrɪˈspektɪv əv/","tag":"near meaning","definition":"Without reference to a factor; the most formal twin.","definitionCN":"不论某因素；最正式的对应说法。"},{"word":"in spite of","ipa":"/ɪn ˈspaɪt əv/","tag":"near meaning","definition":"Despite an obstacle that is actually present.","definitionCN":"尽管存在实际阻碍。"},{"word":"despite","ipa":"/dɪˈspaɪt/","tag":"near meaning","definition":"A one-word preposition of concession.","definitionCN":"表示让步的单词介词。"},{"word":"heedless of","ipa":"/ˈhiːdləs əv/","tag":"near meaning","definition":"Paying no attention to a warning, with a note of blame.","definitionCN":"指不理会警告，带责备意味。"},{"word":"notwithstanding","ipa":"/ˌnɒtwɪθˈstændɪŋ/","tag":"near meaning","definition":"A formal preposition or adverb meaning in spite of.","definitionCN":"正式的介词或副词，意为「尽管」。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the literal meaning of the parts: looking, and without.","cn":"正常联想使用各部分的字面意思：注视，以及「没有」。"},"normal":[{"en":"Regard means to look at, and the negative ending means without, so the phrase says: without looking at it.","cn":"词根意为注视，否定词尾意为没有，所以整条短语就是「不去看它」。"},{"en":"The bare adverb takes no object; adding of lets a noun or a whether-clause follow.","cn":"不带宾语的副词不接名词；加上介词后才能接名词或「是否」从句。"},{"en":"Rules use the phrase to switch off exceptions, as in access regardless of age.","cn":"规章用这条短语关掉例外，例如不论年龄都可进入。"},{"en":"Sports talk uses regardless of the outcome to praise effort that does not depend on winning.","cn":"体育话语用「不管结果如何」来称赞不取决于胜负的努力。"},{"en":"The phrase regardless of the consequences is the strongest version, because the harm is named and then dismissed.","cn":"「不顾后果」是最强版本，因为损害被点出来之后又被撇开。"}],"abstract":[{"en":"The phrase is a switch that turns a whole category of facts off before the decision is made.","cn":"这条短语是一个开关，在做决定之前把一整类事实关掉。"},{"en":"Equality and recklessness speak with the same words, and only the context tells them apart.","cn":"平等与鲁莽用同一套说法，只有语境能把它们分开。"},{"en":"To ignore something you must first have seen it: attention is denied, not absent.","cn":"要「不顾」某物，得先看见它：被否定的是留意，而不是留意本身不存在。"}]},"examples":[{"en":"Regardless of the weather, the survey team went out at dawn.","cn":"无论天气如何，勘测队都在黎明出发。"},{"en":"The scholarship is open to all students regardless of nationality.","cn":"这项奖学金对所有学生开放，不论国籍。"},{"en":"She kept the schedule regardless of the complaints.","cn":"她不顾抱怨，坚持按日程执行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞嘎德莱斯」——眼睛都不往那边「看」，就是「不管、不顾」：不管、不顾、无论","word":"regardless of"},"root":"这个词根经古法语中意为「注视」的动词，源自日耳曼语中表示看守的动词；表示「没有、脱离」的形容词词尾来自古英语。这个词的确切首见年代不确定，带介词宾语的短语在十九世纪通行。无拉丁同族词。","sensesIntro":{"en":"Nine senses run from a factor set aside, to a warning ignored, to fixed phrases that name outcomes and consequences.","cn":"九个义项从一个被撇开的因素，走到被无视的警告，再到点明结果与后果的固定说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rotating red lamp at a shaft mouth, and a cart that keeps rolling past it.","cn":"核心意象：井口旋转的红灯，以及一辆照样开过去的送料车。"},"chain":["A LOOK","ATTENTION WITHHELD","FACTOR SET ASIDE","WARNING IGNORED","RULE WITHOUT EXCEPTION","CONSEQUENCE NAMED"],"branches":[{"senses":"01 · 04","en":"THE FACTOR REMOVED: cost or a limit makes no difference to the act.","cn":"被拿掉的因素：成本或限度对行动不起作用。"},{"senses":"02 · 05","en":"THE WARNING AND THE PERSON: pain is ignored, and rank or feeling is not consulted.","cn":"警告与人：疼痛被无视，身份与感受也不被顾看。"},{"senses":"03 · 06","en":"THE TWO CASES AND THE UNIVERSAL RULE: both alternatives are covered, and no exception remains.","cn":"两种情形与普遍规定：两种可能都被覆盖，例外不再存在。"},{"senses":"07","en":"THE ROBUST CLAIM: a pattern that survives every choice of method.","cn":"稳固的论点：经得起任何方法选择的规律。"},{"senses":"08 · 09","en":"THE FIXED PHRASES: outcome and consequences are named only to be dismissed.","cn":"固定说法：结果与后果被点出，随即被撇开。"}]},"affixes":{"intro":{"en":"The phrase is a Germanic root of watching plus an Old English negative ending, with no Latin layer.","cn":"这条短语是「注视」的日耳曼词根加古英语否定词尾，没有拉丁语层次。"},"latinIntro":{"en":"No Latin source is involved, so the Latin list is empty for this entry.","cn":"本词条不涉及拉丁语来源，因此拉丁词条留空。"},"items":[{"word":"wardon","structure":"Germanic verb","meaning":"to watch, to guard","meaningCN":"看守；注视","example":"It also gave the English words ward and guard.","exampleCN":"它还给出了英语中表示看守的两个词。"},{"word":"regarder","structure":"Old French verb","meaning":"to look at","meaningCN":"注视；看向","example":"The prefix added the idea of looking back.","exampleCN":"前缀加上了「回看」的意思。"},{"word":"regard","structure":"English verb and noun","meaning":"to look at; esteem","meaningCN":"注视；尊重","example":"The root carries attention in both uses.","exampleCN":"这个词根在两种用法里都带「留意」。"},{"word":"-less","structure":"Old English suffix","meaning":"without, free from","meaningCN":"没有；脱离","example":"It forms adjectives of absence.","exampleCN":"它构成表示「缺少」的形容词。"},{"word":"regardless","structure":"English adverb","meaning":"without heed","meaningCN":"不顾；照样","example":"The adverb takes no object of its own.","exampleCN":"这个副词本身不接宾语。"},{"word":"of","structure":"English preposition","meaning":"concerning, from","meaningCN":"关于；出自","example":"It lets a noun or a clause follow.","exampleCN":"它让名词或从句跟在后面。"},{"word":"dis-","structure":"Latin prefix through French","meaning":"apart, away","meaningCN":"分开；离开","example":"It forms the verb disregard, to ignore deliberately.","exampleCN":"它构成表示刻意无视的动词。"},{"word":"regarding","structure":"English participle as preposition","meaning":"about","meaningCN":"关于","example":"The participle turned into a preposition.","exampleCN":"这个现在分词转成了介词。"},{"word":"regardful","structure":"English adjective","meaning":"attentive","meaningCN":"留意的","example":"The positive counterpart of the negative form.","exampleCN":"它是否定形式的肯定对应词。"},{"word":"regardless of","structure":"English prepositional phrase","meaning":"irrespective of","meaningCN":"不论","example":"The phrase as a whole cancels a condition.","exampleCN":"整条短语取消一个条件。"}],"latinEntries":[],"derivatives":[{"word":"regard","pos":"v./n.","zh":"同一词根的名词与动词，义为「注视；尊重」"},{"word":"regardless","pos":"adv.","zh":"加否定词尾构成，义为「不顾；照样」"},{"word":"regarding","pos":"prep.","zh":"由现在分词转成介词，义为「关于」"},{"word":"disregard","pos":"v./n.","zh":"加表示「分开」的前缀构成，义为「无视」"},{"word":"regardful","pos":"adj.","zh":"加表示「充满」的词尾构成，义为「留意的」"}]}},{"word":"in the absence of","ipa_uk":"/ɪn ði ˈæbsəns ɒv/","ipa_us":"/ɪn ði ˈæbsəns ɑːv/","definition_zh":"在缺少……的情况下；在没有……时；在……不在场时","definition_en":"when something or someone is not present, available or provided","core_image":"断电的恒温箱里没有光照，培养皿一排排静置，温度计停在室温刻度","scene":"停电一夜，恒温箱里没有光照也没有恒温，培养皿中的反应完全停止。No reaction took place in the absence of light.","sceneCN":"这里指缺少某个必需条件（第 1 个义项：在缺少……的情况下）；句意为在没有光照的情况下没有发生反应。图中可辨识物件：恒温箱、培养皿、温度计、断电的指示灯。","pos":[{"tag":"prep. phr.","zh":"介词短语：在缺少……的情况下；在……不在场时"}],"collocations":[{"phrase":"in the absence of evidence","zh":"在缺少证据的情况下"},{"phrase":"in the absence of a chair","zh":"在主席不在场时"},{"phrase":"in the absence of oxygen","zh":"在没有氧气的情况下"},{"phrase":"in the absence of alternatives","zh":"在没有其他选择的情况下"},{"phrase":"in the absence of data","zh":"在缺少数据的情况下"},{"phrase":"in the absence of a formal rule","zh":"在没有正式规定的情况下"}],"forms":[{"label":"固定短语","form":"in the absence of"},{"label":"人物变体","form":"in somebody's absence（某人不在时）"},{"label":"条件从句改写","form":"when + 名词 + is absent"},{"label":"名词形式","form":"absence（缺席；缺失）"},{"label":"形容词形式","form":"absent（缺席的；心不在焉的）"}],"derivatives":[{"word":"absence","pos":"n.","zh":"由同一拉丁分词加名词词尾构成，义为「缺席；缺乏」"},{"word":"absent","pos":"adj.","zh":"由该拉丁分词直接进入英语，义为「缺席的；不在的」"},{"word":"absentee","pos":"n.","zh":"由形容词加表示人的名词词尾构成，义为「缺席者」"},{"word":"absently","pos":"adv.","zh":"由形容词加副词词尾构成，义为「心不在焉地」"}],"senses":[{"no":"01","title":"Lacking a thing or condition","titleCN":"缺少某物或某条件","definition":"when a needed thing or condition is not there","definitionCN":"当某种必需的事物或条件不存在时","example":"In the absence of evidence, the claim cannot be tested.","exampleCN":"在缺少证据的情况下，这一说法无法检验。","why":"The phrase turns a missing noun into a condition for the main clause.","whyCN":"这条短语把缺席的名词变成主句成立的条件。"},{"no":"02","title":"A person not being present","titleCN":"某人不在场","definition":"when a person who would normally act or decide is not present","definitionCN":"当通常应当行动或作决定的人不在场时","example":"In the absence of the chair, the deputy signed the order.","exampleCN":"在主席不在场时，副手签署了命令。","why":"The noun of absence first named a person being away, and this sense remains the most literal.","whyCN":"这个名词最初指人不在场，这一义项仍是最字面的。"},{"no":"03","title":"A procedural default","titleCN":"程序上的缺失","definition":"in formal rules, when a required body or number is missing","definitionCN":"在正式规则中，当必需的机构或人数缺失时","example":"In the absence of a quorum, no vote may be taken.","exampleCN":"在不足法定人数时，不得进行表决。","why":"Legal drafting turns absence into a trigger for a fallback procedure.","whyCN":"法律起草把「缺席」变成启动备用程序的触发条件。"},{"no":"04","title":"No alternative available","titleCN":"没有其他选择","definition":"when no other option exists and the remaining one is accepted","definitionCN":"当不存在其他选择，只好接受剩下的方案","example":"In the absence of alternatives, the council accepted the plan.","exampleCN":"在没有其他选择的情况下，委员会接受了该方案。","why":"A missing option is treated as a condition that justifies the decision.","whyCN":"缺失的选项被当作替这一决定辩护的条件。"},{"no":"05","title":"A quality that is missing","titleCN":"某种品质缺失","definition":"when a shared quality such as trust or goodwill is not present","definitionCN":"当信任、善意等共同品质不存在时","example":"In the absence of trust, the talks collapsed.","exampleCN":"在缺乏信任的情况下，谈判破裂。","why":"Abstract qualities can be absent like people, and the same phrase covers them.","whyCN":"抽象品质也能像人一样缺席，同一条短语照样管用。"},{"no":"06","title":"An experimental condition","titleCN":"实验条件缺失","definition":"in science, describing a trial run with one factor removed","definitionCN":"在科学中，描述抽掉某一因素的试验","example":"The enzyme stays inactive in the absence of a cofactor.","exampleCN":"在没有辅因子时，这种酶保持失活。","why":"Laboratory writing needs a precise way to say which factor was withheld.","whyCN":"实验写作需要一种精确说法，指明抽掉了哪个因素。"},{"no":"07","title":"When no written rule exists","titleCN":"没有成文规定时","definition":"when a rule is missing and practice or custom fills the gap","definitionCN":"当规则缺失，由惯例或习俗补上空缺","example":"In the absence of a written rule, local practice governs.","exampleCN":"在没有成文规定时，按当地惯例处理。","why":"Legal theory uses the phrase for the gap that custom is allowed to fill.","whyCN":"法学理论用这条短语指允许惯例填补的空缺。"},{"no":"08","title":"A caveat in academic writing","titleCN":"学术写作中的限定","definition":"a formula warning that a conclusion depends on missing data","definitionCN":"提醒结论受缺失数据限制的固定说法","example":"In the absence of long-term data, the forecast remains uncertain.","exampleCN":"在缺少长期数据的情况下，预测仍不确定。","why":"The phrase lets a writer state a limitation without abandoning the claim.","whyCN":"这条短语让写作者交代局限，而不放弃论点。"},{"no":"09","title":"A default state in engineering","titleCN":"工程中的缺省状态","definition":"in technical writing, the state of a system when an expected input is missing","definitionCN":"在技术文本中，指系统缺少预期输入时所处的状态","example":"In the absence of a signal, the controller switches to safe mode.","exampleCN":"在没有信号时，控制器切换到安全模式。","why":"Control systems name the missing input as the trigger for a safe fallback.","whyCN":"控制系统把缺失的输入命名为安全回退的触发条件。"}],"etymology":{"intro":{"en":"The phrase joins in, the, absence and of. Absence came through Old French from Latin absentia, the state of being away, from abesse, to be away, built from ab-, away, and esse, to be. The phrase extended from people to conditions in the eighteenth and nineteenth centuries.","cn":"这条短语由介词、冠词与表示「缺席」的名词组成。该名词经古法语来自拉丁语 absentia「不在的状态」，源头是动词 abesse「不在场」，由表示「离开」的前缀与表示「存在」的动词构成。十八、十九世纪，短语从指人不在场扩展到指条件缺失。"},"items":[{"era":"LATIN ESSE","en":"Esse meant to be or to exist, and it stands behind many English words of presence and absence.","cn":"这个词意为存在，是英语中许多表示「在场」与「不在场」词汇的共同源头。"},{"era":"LATIN ABESSE","en":"Abesse meant to be away, formed with the prefix of separation and the verb of being.","cn":"这个动词意为「不在场」，由表示分离的前缀与表示存在的动词构成。"},{"era":"LATIN ABSENTIA","en":"The noun named the state of being away, and it was used in legal and everyday Latin alike.","cn":"这个名词指「不在的状态」，在法律拉丁语与日常拉丁语中都用。"},{"era":"OLD FRENCH ABSENCE","en":"French carried the noun into English in the fourteenth century, first for a person who is not there.","cn":"法语在十四世纪把这个名词带进英语，最初指不在场的人。"},{"era":"THE PHRASE EXTENDS, 18TH AND 19TH CENTURIES","en":"The phrase moved from people to evidence, resources and conditions; the exact date of each extension is uncertain.","cn":"这条短语从人扩展到证据、资源与条件；每一次扩展的确切年代都不确定。"},{"era":"LEGAL AND SCIENTIFIC USE","en":"Law adopted it for missing quorums, and science adopted it for factors withheld from a trial.","cn":"法律用它说明人数不足，科学用它说明试验中抽掉的因素。"}]},"similar":{"note":{"en":"The first group shares the same root or the opposite frame; the second group names other ways of saying that something is missing.","cn":"第一组共享词根或构成相反的框架；第二组是其他表示「缺少」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"absence","ipa":"/ˈæbsəns/","tag":"same root","definition":"The noun for being away or for a lack.","definitionCN":"指不在场或缺失的名词。"},{"word":"absent","ipa":"/ˈæbsənt/","tag":"same root","definition":"Adjective for not present; also meaning inattentive.","definitionCN":"指不在场的形容词，也表示心不在焉。"},{"word":"absentee","ipa":"/ˌæbsənˈtiː/","tag":"same root","definition":"A person who is not where they should be.","definitionCN":"指该到而没到的人。"},{"word":"in the presence of","ipa":"/ɪn ðə ˈprezns əv/","tag":"opposite frame","definition":"The mirror phrase, naming what is there rather than what is missing.","definitionCN":"镜像短语，点明存在的东西而非缺失的东西。"},{"word":"absently","ipa":"/ˈæbsəntli/","tag":"same root","definition":"In an inattentive manner.","definitionCN":"指心不在焉地。"}]},{"heading":"NEAR MEANING","entries":[{"word":"for want of","ipa":"/fə wɒnt əv/","tag":"near meaning","definition":"Because of the lack of something needed.","definitionCN":"因缺少某必需品。"},{"word":"in default of","ipa":"/ɪn dɪˈfɔːlt əv/","tag":"near meaning","definition":"A legal phrase for what happens when something required is missing.","definitionCN":"法律用语，指缺少必需之物时的处理。"},{"word":"without","ipa":"/wɪˈðaʊt/","tag":"near meaning","definition":"A one-word preposition of absence.","definitionCN":"单词介词，表示「没有」。"},{"word":"lacking","ipa":"/ˈlækɪŋ/","tag":"near meaning","definition":"Not having something, often in formal description.","definitionCN":"指缺少某物，多用于正式描述。"},{"word":"short of","ipa":"/ʃɔːt əv/","tag":"near meaning","definition":"Not having enough of something.","definitionCN":"指某物不够。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the literal sense of the noun: a person or thing that is not there.","cn":"正常联想使用这个名词的字面义：不在场的人或不存在的东西。"},"normal":[{"en":"The noun once meant only a person being away, which is why the phrase still works for an absent chairman.","cn":"这个名词最初只指人不在场，所以短语至今能用在缺席的主席身上。"},{"en":"Latin gave the verb to be plus a prefix of separation, so absence is literally being away.","cn":"拉丁语用「存在」动词加分离前缀，因此「缺席」字面上就是「离开存在」。"},{"en":"Law uses the phrase for a missing quorum, and science uses it for a withheld factor.","cn":"法律用它说明人数不足，科学用它说明被抽掉的因素。"},{"en":"The mirror phrase in the presence of shows how the same frame can point the other way.","cn":"镜像短语「在……在场时」说明同一框架可以指向相反方向。"},{"en":"Academic writing uses the phrase as a caveat, stating a limitation before the conclusion.","cn":"学术写作把它当限定语，在结论之前先交代局限。"}],"abstract":[{"en":"A missing thing can be as decisive as a present one: the empty slot shapes the sentence.","cn":"缺失之物能像在场之物一样起决定作用：空槽塑造了整个句子。"},{"en":"Absence is a condition, not a failure; the phrase makes the gap into a premise.","cn":"缺席是一种条件而非失败；这条短语把空缺变成前提。"},{"en":"Every rule has a shadow rule for the case when nothing is there.","cn":"每条规则都有一个影子规则，处理「什么都没有」的情形。"}]},"examples":[{"en":"In the absence of a licence, the works were halted.","cn":"在缺少许可证的情况下，工程被叫停。"},{"en":"In the absence of the director, the deputy chaired the meeting.","cn":"在主任不在场时，由副手主持会议。"},{"en":"Seeds can stay dormant in the absence of water.","cn":"在没有水的情况下，种子可以保持休眠。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因阿布森斯」——座位空着、人不「在」，就是「缺席、缺少」：在缺少……的情况下","word":"in the absence of"},"root":"这个名词经古法语来自拉丁语 absentia「不在的状态」，源头是 abesse「不在场」，由表示「离开」的前缀与表示「存在」的动词构成；短语在十八、十九世纪从指人扩展到指条件，各步扩展的确切年代不确定。","sensesIntro":{"en":"Nine senses move from a missing thing, to a missing person, to missing procedure, alternative, quality, factor, rule, data and signal.","cn":"九个义项从缺失之物，走到缺席之人，再到缺失的程序、替代方案、品质、因素、规则、数据与信号。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dark incubator, dishes lined up, and the thermometer fallen back to room heat.","cn":"核心意象：黑暗的恒温箱、成排的培养皿，以及回落到室温的温度计。"},"chain":["BEING AWAY","EMPTY SLOT","MISSING FACTOR","NO ALTERNATIVE","NO WRITTEN RULE","DEFAULT STATE"],"branches":[{"senses":"01 · 06","en":"THE MISSING CONDITION: an absent thing or factor stops the expected event.","cn":"缺失的条件：缺席之物或因素使预期事件无法发生。"},{"senses":"02","en":"THE MISSING PERSON: the one who would decide is not in the room.","cn":"缺席的人：本该作决定的人不在场。"},{"senses":"03 · 07","en":"THE MISSING PROCEDURE AND RULE: a required body or written rule is absent.","cn":"缺失的程序与规则：必需的机构或成文规定不在。"},{"senses":"04 · 05","en":"THE MISSING OPTION AND QUALITY: no alternative remains, and trust is gone.","cn":"缺失的选项与品质：已无替代方案，信任也已消失。"},{"senses":"08 · 09","en":"THE CAVEAT AND THE DEFAULT: missing data limits a claim, and a missing signal triggers a fallback.","cn":"限定与缺省：数据缺失限制结论，信号缺失触发回退。"}]},"affixes":{"intro":{"en":"The phrase is built on a Latin verb of being with a prefix of separation, so its core is existence plus distance.","cn":"这条短语建在表示「存在」的拉丁动词上，并加分离前缀，核心就是「存在」加「离开」。"},"latinIntro":{"en":"Latin supplies the verb of being, the prefix of separation, the noun of absence and its participle.","cn":"拉丁语提供了表示存在的动词、表示分离的前缀、表示缺席的名词及其分词。"},"items":[{"word":"esse","structure":"Latin verb","meaning":"to be, to exist","meaningCN":"存在","example":"Presence and absence both start here.","exampleCN":"「在场」与「不在场」都从这里出发。"},{"word":"ab-","structure":"Latin prefix","meaning":"away from","meaningCN":"离开","example":"It turns being into being away.","exampleCN":"它把「存在」变成「离开存在」。"},{"word":"abesse","structure":"Latin verb","meaning":"to be away","meaningCN":"不在场","example":"The verb describes the missing person.","exampleCN":"这个动词描述缺席的人。"},{"word":"absens","structure":"Latin participle","meaning":"being away","meaningCN":"不在场的","example":"Its participle became the English adjective.","exampleCN":"其分词成为英语形容词。"},{"word":"absentia","structure":"Latin noun","meaning":"a state of being away","meaningCN":"不在的状态","example":"The noun supplied the English word for absence.","exampleCN":"这个名词提供了英语中表示缺席的词。"},{"word":"absence","structure":"English noun","meaning":"the state of being away or lacking","meaningCN":"缺席；缺失","example":"The noun widened from people to things.","exampleCN":"这个名词从人扩展到事物。"},{"word":"absent","structure":"English adjective","meaning":"not present","meaningCN":"缺席的","example":"It also describes an inattentive mind.","exampleCN":"它也形容心不在焉的状态。"},{"word":"-ee","structure":"English noun ending","meaning":"the person affected","meaningCN":"受影响的人","example":"It forms the word for a person who is away.","exampleCN":"它构成指缺席者的名词。"},{"word":"in","structure":"English preposition","meaning":"inside, within a condition","meaningCN":"处于某种情况之中","example":"It opens the conditional phrase.","exampleCN":"它引出这个条件短语。"},{"word":"in the absence of","structure":"English prepositional phrase","meaning":"with something missing","meaningCN":"在缺少……时","example":"The phrase sets a condition for the main clause.","exampleCN":"整条短语为主句设定条件。"}],"latinEntries":[{"word":"esse","structure":"Latin verb","meaning":"to be","meaningCN":"存在"},{"word":"ab-","structure":"Latin prefix","meaning":"away","meaningCN":"离开"},{"word":"abesse","structure":"Latin verb","meaning":"to be away","meaningCN":"不在场"},{"word":"absentia","structure":"Latin noun","meaning":"absence","meaningCN":"缺席；不在"}],"derivatives":[{"word":"absence","pos":"n.","zh":"由拉丁名词直接进入英语，义为「缺席；缺乏」"},{"word":"absent","pos":"adj.","zh":"由拉丁分词进入英语，义为「缺席的」"},{"word":"absentee","pos":"n.","zh":"加表示人的词尾构成，义为「缺席者」"},{"word":"absently","pos":"adv.","zh":"加副词词尾构成，义为「心不在焉地」"}]}},{"word":"on the contrary","ipa_uk":"/ɒn ðə kənˈtreəri/","ipa_us":"/ɑːn ðə kənˈtreri/","definition_zh":"恰恰相反；相反地；反之","definition_en":"used to state that the opposite of something just said is true","core_image":"检测员把报告摊在桌上，指着梁上的裂缝，当场推翻「旧桥结实」的说法","scene":"有人断言旧桥还能承重，工程师翻开检测报告，指着裂缝否定了这个说法。On the contrary, the inspection found cracks in three girders.","sceneCN":"这里用来直接否定刚提出的说法（第 1 个义项：恰恰相反）；句意为恰恰相反，检查发现三根主梁有裂缝。图中可辨识物件：检测报告、裂缝、钢梁、手电筒。","pos":[{"tag":"adv. phr.","zh":"副词性短语：恰恰相反；反之（用于否定刚提出的说法）"}],"collocations":[{"phrase":"on the contrary, ...","zh":"恰恰相反，……"},{"phrase":"quite the contrary","zh":"恰恰相反（加强式）"},{"phrase":"say the contrary","zh":"说相反的话"},{"phrase":"evidence to the contrary","zh":"相反的证据"},{"phrase":"on the contrary, the opposite is true","zh":"恰恰相反，情况正相反"}],"forms":[{"label":"固定短语","form":"on the contrary"},{"label":"句首位置","form":"On the contrary, + 主句"},{"label":"加强变体","form":"quite the contrary（恰恰相反）"},{"label":"相关短语","form":"to the contrary（相反的）"},{"label":"词根形式","form":"contrary（相反的；固执的）"}],"derivatives":[{"word":"contrary","pos":"adj./n.","zh":"同一词根直接作形容词或名词，义为「相反的；反面」"},{"word":"contrarily","pos":"adv.","zh":"由形容词加副词词尾构成，义为「相反地；固执地」"},{"word":"contrariwise","pos":"adv.","zh":"由形容词加方式词尾构成，义为「反之；相反地」"},{"word":"contrariness","pos":"n.","zh":"由形容词加名词词尾构成，义为「相反性；执拗」"},{"word":"contrarian","pos":"n./adj.","zh":"由词根加表示人的词尾构成，义为「逆向行事者；唱反调的」"}],"senses":[{"no":"01","title":"Denying a statement just made","titleCN":"否定刚提出的说法","definition":"used to declare that the statement just made is false and the opposite is true","definitionCN":"用来宣布刚提出的说法不成立，真实情况正相反","example":"The material is not brittle; on the contrary, it bends without cracking.","exampleCN":"这种材料并不脆；恰恰相反，它能弯曲而不裂。","why":"The phrase does not add a difference, it cancels a claim and puts the opposite in its place.","whyCN":"这条短语不是补充差异，而是取消一个说法，再把相反的说法放进去。"},{"no":"02","title":"Correcting a misconception","titleCN":"纠正误解","definition":"used to replace a widely held but mistaken belief with the opposite fact","definitionCN":"用一个相反的事实替换普遍但错误的看法","example":"Most people think the desert is lifeless; on the contrary, it teems with insects after rain.","exampleCN":"多数人以为沙漠没有生命；恰恰相反，雨后虫类成群。","why":"Correction works by naming the belief first, so the reversal has something to overturn.","whyCN":"纠正先把错误看法说出来，反转才有东西可推翻。"},{"no":"03","title":"Strong disagreement in debate","titleCN":"辩论中的强烈反对","definition":"used to reject an opponent's claim firmly and immediately","definitionCN":"用来坚决而立即地否定对方的说法","example":"On the contrary, the witness gave a very different account.","exampleCN":"恰恰相反，那名证人给出的说法完全不同。","why":"In debate the phrase carries emphasis, because it refuses the premise rather than arguing within it.","whyCN":"辩论中这条短语带强调色彩，因为它拒绝前提，而不是在前提内争辩。"},{"no":"04","title":"After a negative clause","titleCN":"跟在否定小句之后","definition":"following not X, to supply Y as the true state of affairs","definitionCN":"跟在「并非甲」之后，给出「实为乙」的真实情况","example":"The bridge was not strengthened; on the contrary, two lanes were removed.","exampleCN":"这座桥并未加固；恰恰相反，还拆掉了两条车道。","why":"The pattern not X but Y is the phrase's most common grammatical home.","whyCN":"「并非甲，而是乙」是这条短语最常见的语法位置。"},{"no":"05","title":"A marker of formal argument","titleCN":"正式论证的标记","definition":"used in essays and reports to signal a reversal in the argument","definitionCN":"在论文与报告中标记论证方向的翻转","example":"On the contrary, the figures show a steady decline.","exampleCN":"恰恰相反，这些数字显示持续下降。","why":"Academic prose uses the phrase to steer the reader through a reversal, not to insult an opponent.","whyCN":"学术文本用它引导读者穿过一次反转，而非攻击对手。"},{"no":"06","title":"Refuting an implied assumption","titleCN":"反驳暗含的假设","definition":"used when the claim being rejected was only implied or assumed","definitionCN":"用在被否定的说法只是暗含或假定时","example":"On the contrary, the team had prepared for the delay.","exampleCN":"恰恰相反，团队早已为延误做了准备。","why":"An assumption can be reversed without being quoted, which makes the phrase feel sharper.","whyCN":"假设不必被引用也能被反转，这使短语显得更锋利。"},{"no":"07","title":"Opening a paragraph","titleCN":"开启段落","definition":"placed at the head of a paragraph to answer the previous one","definitionCN":"放在段首，用来回应上一段","example":"On the contrary, later studies confirmed the earlier result.","exampleCN":"恰恰相反，后来的研究证实了早先的结果。","why":"Paragraph-initial use turns the phrase into a hinge between two blocks of argument.","whyCN":"放在段首时，这条短语成为两块论证之间的铰链。"},{"no":"08","title":"Asserting opposition, not mere difference","titleCN":"主张相反，而非仅仅不同","definition":"used to insist on opposition, where a plain contrast marker would only note a difference","definitionCN":"用来强调对立，而单纯的对比词只指出差异","example":"The old and new methods seem similar; on the contrary, they rely on opposite assumptions.","exampleCN":"新旧方法看似相近；恰恰相反，它们依据的假设正好相反。","why":"Contrast notes two things side by side, while this phrase says one cancels the other.","whyCN":"对比词把两物并排，这条短语则说一方取消另一方。"}],"etymology":{"intro":{"en":"The phrase joins on and the noun contrary, from Latin contrarius, opposite, from contra, against. English took the word through Old French in the thirteenth century, and the phrase settled as a marker of reversal soon after.","cn":"这条短语由介词与表示「相反」的名词组成。该名词来自拉丁语 contrarius「相反的」，源头是 contra「对着、反对」。英语在十三世纪经古法语引入这个词，整条短语随后定型为表示反转的标记。"},"items":[{"era":"LATIN CONTRA","en":"Contra meant against or opposite, and it survives in English prefixes and legal phrases.","cn":"这个词意为「对着、反对」，在英语前缀与法律短语中仍有留存。"},{"era":"LATIN CONTRARIUS","en":"The adjective meant opposite or opposed, describing things that face each other.","cn":"这个形容词意为相反的、对立的，形容彼此相对之物。"},{"era":"OLD FRENCH CONTRARIE","en":"French carried the adjective and noun into English, where contrary named the opposite of a thing.","cn":"法语把这个形容词与名词带进英语，其中名词指某物的反面。"},{"era":"ENGLISH CONTRARY, 13TH CENTURY","en":"English used the word for a opposed fact as well as for a stubborn person.","cn":"英语用这个词指相反的事实，也用来形容固执的人。"},{"era":"THE PHRASE TAKES SHAPE, 14TH TO 16TH CENTURY","en":"The prepositional phrase became a standard marker of reversal; the exact first date is uncertain.","cn":"这个介词短语成为标准的反转标记；确切首见年代不确定。"},{"era":"THE FIXED CONTRAST MARKER","en":"Later handbooks paired the phrase with its cousin to the contrary, which sits after a noun instead.","cn":"后来的手册把这条短语与近亲说法「相反的」并列，后者放在名词之后。"}]},"similar":{"note":{"en":"The first group shares the same root or the same frame; the second group names other ways of marking contrast.","cn":"第一组共享同一词根或同一框架；第二组是其他标记对比的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"to the contrary","ipa":"/tə ðə kənˈtreəri/","tag":"same frame","definition":"A phrase that follows a noun, as in evidence to the contrary.","definitionCN":"跟在名词之后的短语，如「相反的证据」。"},{"word":"contrary","ipa":"/ˈkɒntrəri/","tag":"same root","definition":"Adjective or noun meaning opposite; also describing a stubborn person.","definitionCN":"形容词或名词，意为相反的；也形容固执的人。"},{"word":"contrarily","ipa":"/ˈkɒntrərəli/","tag":"same root","definition":"In an opposite or perverse manner.","definitionCN":"指相反地或执拗地。"},{"word":"contrariwise","ipa":"/ˈkɒntrəriwaɪz/","tag":"same root","definition":"An older adverb meaning on the other hand or in the opposite way.","definitionCN":"较早的副词，意为反之或相反地。"},{"word":"contrarian","ipa":"/kənˈtreəriən/","tag":"same root","definition":"A person who deliberately takes the opposite view.","definitionCN":"指刻意持相反观点的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"in contrast","ipa":"/ɪn ˈkɒntrɑːst/","tag":"near meaning","definition":"A marker that sets two things side by side without denying either.","definitionCN":"把两物并置的标记，并不否定任何一方。"},{"word":"conversely","ipa":"/ˈkɒnvɜːsli/","tag":"near meaning","definition":"Introducing the reverse of a relation already stated.","definitionCN":"引出已述关系的反向情况。"},{"word":"on the other hand","ipa":"/ɒn ði ˈʌðə hænd/","tag":"near meaning","definition":"A balanced second view, not a denial of the first.","definitionCN":"平衡地给出第二种看法，并不否定第一种。"},{"word":"instead","ipa":"/ɪnˈsted/","tag":"near meaning","definition":"In place of what was expected or proposed.","definitionCN":"代替预期或提议的事物。"},{"word":"rather","ipa":"/ˈrɑːðə/","tag":"near meaning","definition":"More precisely, introducing a corrected statement.","definitionCN":"更准确地说，引出修正后的说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the root meaning of facing against, and the phrase's habit of cancelling a claim.","cn":"正常联想使用词根「对着」的意思，以及这条短语取消说法的习惯。"},"normal":[{"en":"The root meant against, so the phrase puts a fact face to face with the claim it cancels.","cn":"词根意为「对着」，所以这条短语让事实与它所取消的说法面对面。"},{"en":"It usually follows a negative clause: not this, on the contrary that.","cn":"它通常跟在否定小句之后：并非这个，恰恰相反，是那个。"},{"en":"In debate it refuses the premise rather than arguing inside it.","cn":"在辩论中它拒绝前提，而不是在前提里争辩。"},{"en":"The cousin phrase to the contrary sits after a noun, as in evidence to the contrary.","cn":"近亲短语表示「反之」，放在名词之后，例如「相反的证据」。"},{"en":"A plain contrast marker only notes a difference; this phrase asserts an opposite.","cn":"单纯的对比词只指出差异，这条短语则主张相反。"}],"abstract":[{"en":"A denial that supplies a replacement is stronger than a denial that leaves a gap.","cn":"否定之后补上替代物的说法，比留下空缺的否定更有力。"},{"en":"The phrase works like a hinge: one paragraph turns on it and the next swings the other way.","cn":"这条短语像铰链：上一段绕着它转，下一段就转向另一边。"},{"en":"Opposition needs a shared subject: two claims must face each other before one can be reversed.","cn":"对立需要共同的主语：两个说法先面对面，其中一个才谈得上被反转。"}]},"examples":[{"en":"The soil is not poor; on the contrary, it is unusually rich in minerals.","cn":"土壤并不贫瘠；恰恰相反，它富含矿物质。"},{"en":"On the contrary, the second trial produced better results than the first.","cn":"恰恰相反，第二次试验的结果比第一次更好。"},{"en":"Critics expected a decline; on the contrary, demand rose sharply.","cn":"批评者预料会下滑；恰恰相反，需求大幅上升。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康雀瑞」——两个人面对面站着，各说反话，就是「恰恰相反」：恰恰相反、反之","word":"on the contrary"},"root":"这个词经古法语来自拉丁语 contrarius「相反的」，源头是 contra「对着、反对」；这条短语在十四至十六世纪定型为反转标记，确切首见年代不确定。","sensesIntro":{"en":"Eight senses range from denying a statement, through correcting a belief and winning a debate, to opening a paragraph and asserting true opposition.","cn":"八个义项从否定一句话，经过纠正误解、赢下辩论，走到开启段落与主张真正的对立。"},"semanticMap":{"core":{"en":"CORE IMAGE: an inspection report opened on a table, a crack circled in red, and a confident claim left in ruins.","cn":"核心意象：桌上摊开的检测报告、圈红的裂缝，以及被推翻的自信说法。"},"chain":["FACING AGAINST","CLAIM STATED","CLAIM CANCELLED","OPPOSITE SUPPLIED","ARGUMENT REVERSED","PARAGRAPH HINGE"],"branches":[{"senses":"01 · 04","en":"THE CANCELLED CLAIM: after a negative clause, the phrase supplies the true opposite.","cn":"被取消的说法：跟在否定小句之后，给出真正的相反情况。"},{"senses":"02 · 06","en":"THE CORRECTED BELIEF: a misconception or an unspoken assumption is reversed.","cn":"被纠正的看法：误解或未说出的假设被反转。"},{"senses":"03 · 05","en":"THE DEBATE AND THE ESSAY: firm rejection in argument, formal reversal in writing.","cn":"辩论与论文：论证中的坚决否定，写作中的正式反转。"},{"senses":"07","en":"THE PARAGRAPH HINGE: the phrase opens a paragraph that answers the last one.","cn":"段落铰链：短语开启一段，回应上一段。"},{"senses":"08","en":"THE TRUE OPPOSITE: not a difference noted, but an opposition asserted.","cn":"真正的相反：不是指出差异，而是主张对立。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin word for facing against, so its force is opposition rather than comparison.","cn":"这条短语立在一个表示「对着」的拉丁词上，力量来自对立而非比较。"},"latinIntro":{"en":"Latin supplies contra and its adjective; Old French carried both into English.","cn":"拉丁语提供了表示「对着」的词及其形容词；古法语把两者带进英语。"},"items":[{"word":"contra","structure":"Latin preposition","meaning":"against, opposite","meaningCN":"对着；反对","example":"It survives in English compounds and legal phrases.","exampleCN":"它在英语复合词与法律短语中留存。"},{"word":"contrarius","structure":"Latin adjective","meaning":"opposite, opposed","meaningCN":"相反的；对立的","example":"The adjective describes things facing each other.","exampleCN":"这个形容词形容彼此相对之物。"},{"word":"contrarie","structure":"Old French adjective","meaning":"opposite","meaningCN":"相反的","example":"French carried the word into English.","exampleCN":"法语把这个词带进英语。"},{"word":"contrary","structure":"English adjective and noun","meaning":"opposite; the reverse","meaningCN":"相反的；反面","example":"The word names what stands against a claim.","exampleCN":"这个词指与某说法相对的东西。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb of manner.","exampleCN":"它构成方式副词。"},{"word":"-wise","structure":"English adverb ending","meaning":"in the stated direction or way","meaningCN":"以所述方向或方式","example":"It forms an older adverb meaning conversely.","exampleCN":"它构成较早的副词，意为反之。"},{"word":"-ian","structure":"English noun ending","meaning":"a person who","meaningCN":"从事……的人","example":"It forms the word for a deliberate dissenter.","exampleCN":"它构成指刻意唱反调者的词。"},{"word":"on","structure":"English preposition","meaning":"supported by, situated at","meaningCN":"依托于；处于","example":"It opens the fixed phrase.","exampleCN":"它引出这条固定短语。"},{"word":"to the contrary","structure":"English phrase","meaning":"opposite to what was said","meaningCN":"与所述相反的","example":"The cousin phrase follows a noun instead.","exampleCN":"近亲短语改为跟在名词之后。"},{"word":"on the contrary","structure":"English adverbial phrase","meaning":"the opposite is true","meaningCN":"恰恰相反","example":"The whole phrase cancels a claim.","exampleCN":"整条短语取消一个说法。"}],"latinEntries":[{"word":"contra","structure":"Latin preposition","meaning":"against","meaningCN":"对着；反对"},{"word":"contrarius","structure":"Latin adjective","meaning":"opposite","meaningCN":"相反的"},{"word":"contrarium","structure":"Latin noun","meaning":"the opposite","meaningCN":"反面；相反之物"},{"word":"contrarietas","structure":"Latin noun","meaning":"opposition","meaningCN":"对立；相反性"}],"derivatives":[{"word":"contrary","pos":"adj./n.","zh":"由拉丁形容词经古法语而来，义为「相反的；反面」"},{"word":"contrarily","pos":"adv.","zh":"加副词词尾构成，义为「相反地」"},{"word":"contrariwise","pos":"adv.","zh":"加表示方式的词尾构成，义为「反之」"},{"word":"contrariness","pos":"n.","zh":"加名词词尾构成，义为「相反性；执拗」"},{"word":"contrarian","pos":"n./adj.","zh":"加表示人的词尾构成，义为「唱反调者」"}]}},{"word":"to some extent","ipa_uk":"/tə sʌm ɪkˈstent/","ipa_us":"/tə sʌm ɪkˈstent/","definition_zh":"在一定程度上；多少有些；部分地","definition_en":"partly; to a limited or uncertain degree","core_image":"审稿人先点头认可结论，又在页边写下「样本偏小」几个字","scene":"审稿人先说结论大体站得住，随后在页边注明样本偏小。To some extent, the conclusion holds for small cities.","sceneCN":"这里指结论只在有限程度上成立（第 1 个义项：在一定程度上）；句意为该结论在一定程度上适用于小城市。图中可辨识物件：审稿单、页边批注、钢笔、样本表。","pos":[{"tag":"adv. phr.","zh":"副词性短语：在一定程度上；多少有些"}],"collocations":[{"phrase":"to some extent, ...","zh":"在一定程度上，……"},{"phrase":"to some extent true","zh":"在一定程度上成立"},{"phrase":"to some extent responsible","zh":"负有部分责任"},{"phrase":"to some extent predictable","zh":"在一定程度上可预测"},{"phrase":"to some extent explain","zh":"部分解释"}],"forms":[{"label":"固定短语","form":"to some extent"},{"label":"近义变体","form":"to a certain extent（在一定程度上）"},{"label":"程度加强","form":"to a large extent（在很大程度上）"},{"label":"疑问形式","form":"to what extent（在多大程度上）"},{"label":"名词核心","form":"extent（程度；范围）"},{"label":"动词同族","form":"extend（延伸；扩展）"}],"derivatives":[{"word":"extent","pos":"n.","zh":"由拉丁分词进入英语，义为「程度；范围；广度」"},{"word":"extend","pos":"v.","zh":"同一词根的动词，义为「延伸；扩展；延长」"},{"word":"extension","pos":"n.","zh":"由该动词加名词词尾构成，义为「延伸；扩展部分」"},{"word":"extensive","pos":"adj.","zh":"由该词根加形容词词尾构成，义为「广泛的；大量的」"},{"word":"extensively","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「广泛地」"}],"senses":[{"no":"01","title":"Partly true","titleCN":"部分成立","definition":"used to say that a statement is true only in part","definitionCN":"用来说明某个说法只有一部分成立","example":"To some extent, the criticism is fair.","exampleCN":"在一定程度上，这项批评是公允的。","why":"The phrase measures how much of a claim survives, not whether it survives at all.","whyCN":"这条短语衡量一个说法保住了多少，而不是它究竟保没保住。"},{"no":"02","title":"Moderating an adjective","titleCN":"修饰形容词的程度","definition":"placed before an adjective or adverb to lower the strength of the description","definitionCN":"放在形容词或副词之前，减弱描述强度","example":"The results are to some extent predictable.","exampleCN":"这些结果在一定程度上可以预测。","why":"A graded property can be true at a lower level, and the phrase supplies that lower level.","whyCN":"可分级属性可以在较低程度上成立，这条短语就提供那个较低的程度。"},{"no":"03","title":"Hedging an academic claim","titleCN":"学术论点的谨慎限定","definition":"used in research writing to limit a conclusion without withdrawing it","definitionCN":"在学术写作中限制结论，但不撤回结论","example":"To some extent, the model explains the observed pattern.","exampleCN":"在一定程度上，这个模型解释了观察到的规律。","why":"Hedging protects a claim from counterexamples while keeping most of its force.","whyCN":"限定让论点在保留大部分力度的同时，免于被反例击破。"},{"no":"04","title":"Sharing blame","titleCN":"分担责任","definition":"used to accept partial responsibility for something that went wrong","definitionCN":"用来说明对出错之事承担部分责任","example":"I am to some extent responsible for the delay.","exampleCN":"对这次延误，我负有部分责任。","why":"Admitting a measured share of blame sounds more credible than denying all of it.","whyCN":"承认有分寸的一份责任，比全盘否认更可信。"},{"no":"05","title":"Limited agreement before an objection","titleCN":"先有限同意再提出异议","definition":"used to concede a point before introducing a counterpoint","definitionCN":"在提出相反意见之前先让一步","example":"To some extent that is true, but the cost remains too high.","exampleCN":"在一定程度上这是对的，但成本仍然太高。","why":"Conceding a little buys room for the objection that follows.","whyCN":"先让出一小步，为后面的反对腾出空间。"},{"no":"06","title":"Applying partly to a whole group","titleCN":"部分地适用于整个群体","definition":"used to say that a tendency reaches every member of a group, but only partially","definitionCN":"用来说明某种倾向遍及群体每个成员，但只是部分地","example":"To some extent, every city faces the same housing problem.","exampleCN":"在一定程度上，每座城市都面对同样的住房问题。","why":"A general statement is softened so that exceptions do not count as refutations.","whyCN":"把全称说法放软，例外就不再构成反驳。"},{"no":"07","title":"Part of a causal contribution","titleCN":"部分原因","definition":"used to say that one factor accounts for only part of a change","definitionCN":"用来说明某个因素只解释了变化的一部分","example":"The rise in output is to some extent due to new machinery.","exampleCN":"产量的上升在一定程度上是新机械带来的。","why":"Multiple causes share a result, and the phrase assigns one of them a limited share.","whyCN":"多个原因共同造成结果，这条短语给其中一个原因记上有限的一份。"},{"no":"08","title":"A closing concession in argument","titleCN":"论证结尾的让步","definition":"used at the end of a point to grant a limited counterpoint and close gracefully","definitionCN":"在一段论证的结尾让出有限的反面，使收尾更从容","example":"And to some extent, the critics were right.","exampleCN":"而且在某种程度上，批评者是对的。","why":"A concession at the end protects the main claim by showing that it was not overstated.","whyCN":"结尾处的让步表明主论点没有说过头，从而保护了它。"}],"etymology":{"intro":{"en":"The phrase joins to, some and extent. Extent came from Old French estente, from Latin extendere, to stretch out, built from ex-, out, and tendere, to stretch. The phrase became common in English in the seventeenth and eighteenth centuries.","cn":"这条短语由介词、表示「一些」的词与表示「程度」的名词组成。该名词经古法语来自拉丁语 extendere「伸展出去」，由表示「向外」的前缀与表示「拉伸」的词根构成。整条短语在十七、十八世纪的英语中通行起来。"},"items":[{"era":"LATIN TENDERE","en":"The verb meant to stretch or strain, and it stands behind tendon, tension and extend.","cn":"这个动词意为拉伸、绷紧，是英语中表示肌腱、张力与延伸几个词的源头。"},{"era":"LATIN EXTENDERE","en":"The compound meant to stretch out or spread, adding a prefix of outward direction.","cn":"这个复合动词意为向外伸展、铺开，加了表示向外方向的前缀。"},{"era":"OLD FRENCH ESTENTE","en":"The French noun named a stretch of land or a degree of something, and English borrowed it as extent.","cn":"这个法语名词指一片土地或某事物的程度，英语借入后成为表示程度的名词。"},{"era":"ENGLISH EXTENT, 14TH CENTURY","en":"English first used the noun for size and length, then for the degree to which a quality holds.","cn":"英语最初用这个名词指大小与长度，后来指某种性质成立的程度。"},{"era":"THE PHRASE, 17TH AND 18TH CENTURIES","en":"The phrase with to became a standard way of measuring a claim; the exact first date is uncertain.","cn":"带这个介词的说法成为衡量说法的标准方式；确切首见年代不确定。"},{"era":"SCALED VARIANTS","en":"Later usage produced to a certain extent, to a large extent and the question form to what extent.","cn":"后来的用法派生出「在一定程度上」「在很大程度上」以及疑问形式「在多大程度上」。"}]},"similar":{"note":{"en":"The first group shares the root of extent; the second group lists other ways of limiting a claim.","cn":"第一组共享「伸展」的词根；第二组是其他限制说法的表达。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"extent","ipa":"/ɪkˈstent/","tag":"same root","definition":"The noun for the degree or range of something.","definitionCN":"指某事程度或范围的名词。"},{"word":"extend","ipa":"/ɪkˈstend/","tag":"same root","definition":"The verb meaning to stretch out or lengthen.","definitionCN":"指伸展或延长的动词。"},{"word":"extension","ipa":"/ɪkˈstenʃn/","tag":"same root","definition":"The act of extending, or an added part.","definitionCN":"指延伸的行为或增加的部分。"},{"word":"extensive","ipa":"/ɪkˈstensɪv/","tag":"same root","definition":"Covering a large area or amount.","definitionCN":"指覆盖面积大或数量多的。"},{"word":"extensively","ipa":"/ɪkˈstensɪvli/","tag":"same root","definition":"In a wide or thorough manner.","definitionCN":"指广泛地、深入地。"}]},{"heading":"NEAR MEANING","entries":[{"word":"to a certain extent","ipa":"/tə ə ˈsɜːtn ɪkˈstent/","tag":"near meaning","definition":"The more formal near twin, common in careful writing.","definitionCN":"更正式的近义说法，多见于谨慎的书面语。"},{"word":"partly","ipa":"/ˈpɑːtli/","tag":"near meaning","definition":"In part, but not wholly.","definitionCN":"指部分地，而非全部。"},{"word":"somewhat","ipa":"/ˈsʌmwɒt/","tag":"near meaning","definition":"A one-word degree modifier placed before adjectives.","definitionCN":"放在形容词前的单词程度副词。"},{"word":"in part","ipa":"/ɪn ˈpɑːt/","tag":"near meaning","definition":"For one part of the whole explanation.","definitionCN":"指在整体解释中占一部分。"},{"word":"up to a point","ipa":"/ʌp tə ə pɔɪnt/","tag":"near meaning","definition":"True only until a limit is reached.","definitionCN":"指只到某个限度为止成立。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the root meaning of stretching out, and the phrase's work of measuring a claim.","cn":"正常联想使用「向外伸展」的词根义，以及这条短语衡量说法的功能。"},"normal":[{"en":"Extent is a stretch, so the phrase measures how far a claim reaches before it stops.","cn":"这个词根是「伸展」，所以短语衡量一个说法伸到多远为止。"},{"en":"It sits before an adjective to lower the strength, as in partly predictable.","cn":"它放在形容词前以减弱强度，例如「部分可预测」。"},{"en":"Academic writers use it as a hedge, keeping the conclusion while admitting limits.","cn":"学术写作者把它当限定语，在承认局限的同时保住结论。"},{"en":"The near twin with certain sounds more formal, and the one with large sounds stronger.","cn":"带「某一」的近义说法更正式，带「很大」的说法程度更强。"},{"en":"The question form asks how far, which is the literal meaning of the noun.","cn":"疑问形式问的是「伸到多远」，正是这个名词的字面义。"}],"abstract":[{"en":"A claim is a stretch of ground: the phrase marks how much of it can be held.","cn":"一个说法就像一片地面，这条短语标出能站住多少。"},{"en":"Partial truth is not weak truth; a measured share can be the most defensible position.","cn":"部分真不等于弱真；有分寸的一份往往是最站得住的立场。"},{"en":"Every general statement needs a dial, and this phrase is the dial turned low.","cn":"每个全称说法都需要一个旋钮，这条短语就是把旋钮调低。"}]},"examples":[{"en":"To some extent, the two theories explain the same data.","cn":"在一定程度上，这两种理论解释的是同一批数据。"},{"en":"The success of the campaign was to some extent accidental.","cn":"这场运动的成功在一定程度上是偶然的。"},{"en":"To some extent, every translation loses the rhythm of the original.","cn":"在一定程度上，每篇译文都会失去原文的节奏。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「吐萨姆埃克斯滕特」——伸手只够到一小段，就是「在一定程度上」：在一定程度上、部分地","word":"to some extent"},"root":"这个名词经古法语来自拉丁语 extendere「伸展出去」，由表示「向外」的前缀与表示「拉伸」的词根构成；整条短语在十七、十八世纪通行，确切首见年代不确定。","sensesIntro":{"en":"Eight senses measure a claim, a property, a responsibility, a cause and a concession, all at a reduced degree.","cn":"八个义项分别衡量说法、属性、责任、原因与让步，程度都打了折扣。"},"semanticMap":{"core":{"en":"CORE IMAGE: a reviewer's pen resting in the margin, a note saying the sample is too small.","cn":"核心意象：停在页边的审稿笔，以及写着「样本偏小」的批注。"},"chain":["A STRETCH","MEASURED REACH","LOWERED STRENGTH","SHARED BLAME","PART OF A CAUSE","CLOSING CONCESSION"],"branches":[{"senses":"01 · 02","en":"THE MEASURED CLAIM: a statement or a property holds only so far.","cn":"被衡量的说法：一个陈述或属性只伸到那么远。"},{"senses":"03 · 06","en":"THE HEDGE AND THE GROUP: limits on academic claims and on general statements.","cn":"限定与群体：对学术论点与全称说法的限制。"},{"senses":"04","en":"THE SHARED BLAME: responsibility is accepted in part.","cn":"分担责任：只接受其中一份责任。"},{"senses":"05 · 07","en":"THE CONCESSION AND THE CAUSE: a partial agreement, and a partial explanation.","cn":"让步与原因：部分同意，以及部分解释。"},{"senses":"08","en":"THE CLOSING NOTE: a limited concession that ends an argument gracefully.","cn":"收尾一笔：用有限的让步从容结束论证。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin verb of stretching, so its core is reach rather than amount.","cn":"这条短语立在一个表示「拉伸」的拉丁动词上，核心是「伸到多远」而非「有多少」。"},"latinIntro":{"en":"Latin supplies the verb of stretching and its prefix; Old French supplied the noun that English borrowed.","cn":"拉丁语提供了表示拉伸的词根及其前缀；古法语提供了英语借入的名词。"},"items":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch, to strain","meaningCN":"拉伸；绷紧","example":"The root also stands behind tendon and tension.","exampleCN":"这个词根也是肌腱与张力二词的源头。"},{"word":"ex-","structure":"Latin prefix","meaning":"out, outward","meaningCN":"向外","example":"It turns stretching into stretching out.","exampleCN":"它把「拉伸」变成「向外伸展」。"},{"word":"extendere","structure":"Latin verb","meaning":"to stretch out, to spread","meaningCN":"伸展；铺开","example":"The verb gave English extend.","exampleCN":"这个动词给出了英语的「延伸」。"},{"word":"extentus","structure":"Latin participle","meaning":"stretched out","meaningCN":"被伸展的","example":"The participle supplied the noun of degree.","exampleCN":"其分词提供了表示程度的名词。"},{"word":"estente","structure":"Old French noun","meaning":"a stretch, a degree","meaningCN":"一段；程度","example":"English borrowed it as extent.","exampleCN":"英语借入后成为表示程度的名词。"},{"word":"extent","structure":"English noun","meaning":"degree, range, size","meaningCN":"程度；范围；大小","example":"The noun names how far something reaches.","exampleCN":"这个名词指某物伸到多远。"},{"word":"-sion","structure":"Latin noun ending through French","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms extension, the act of stretching out.","exampleCN":"它构成表示伸展动作的名词。"},{"word":"-ive","structure":"Latin adjective ending","meaning":"having the quality of","meaningCN":"具有……性质","example":"It forms extensive, covering much ground.","exampleCN":"它构成表示覆盖面广的形容词。"},{"word":"some","structure":"English determiner","meaning":"an unspecified amount","meaningCN":"不确定的数量","example":"It keeps the degree deliberately vague.","exampleCN":"它让程度保持模糊。"},{"word":"to some extent","structure":"English adverbial phrase","meaning":"partly","meaningCN":"在一定程度上","example":"The whole phrase measures a reduced claim.","exampleCN":"整条短语衡量一个被调低的说法。"}],"latinEntries":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch","meaningCN":"拉伸"},{"word":"ex-","structure":"Latin prefix","meaning":"out","meaningCN":"向外"},{"word":"extendere","structure":"Latin verb","meaning":"to stretch out","meaningCN":"伸展"},{"word":"extentus","structure":"Latin participle","meaning":"stretched out","meaningCN":"被伸展的"}],"derivatives":[{"word":"extent","pos":"n.","zh":"由拉丁分词经古法语而来，义为「程度；范围」"},{"word":"extend","pos":"v.","zh":"同一词根的动词，义为「延伸；扩展」"},{"word":"extension","pos":"n.","zh":"加名词词尾构成，义为「延伸；扩展部分」"},{"word":"extensive","pos":"adj.","zh":"加形容词词尾构成，义为「广泛的」"},{"word":"extensively","pos":"adv.","zh":"加副词词尾构成，义为「广泛地」"}]}},{"word":"accessibility","ipa_uk":"/əˌkesəˈbɪləti/","ipa_us":"/ˌæksesəˈbɪləti/","definition_zh":"可达性；无障碍性；易接近；易理解性；可获得性；负担性","definition_en":"the quality of being easy to reach, enter, use, understand or obtain","core_image":"公交站旁新铺的缓坡，轮椅顺着坡推到站台，盲道从路口一直接到车门","scene":"公交站旁新铺了一道缓坡，轮椅能直接推到站台，盲道也从路口接到车门。The city rebuilt the stop to improve accessibility for wheelchair users.","sceneCN":"这里指为行动不便者消除障碍（第 2 个义项：无障碍性）；句意为该市重建车站以改善轮椅使用者的通行条件。图中可辨识物件：缓坡、站台、盲道、轮椅。","pos":[{"tag":"n.","zh":"名词：可达性；无障碍性；易接近；易理解性（不可数）"}],"collocations":[{"phrase":"accessibility for wheelchair users","zh":"轮椅使用者的无障碍通行"},{"phrase":"web accessibility","zh":"网页无障碍"},{"phrase":"accessibility standards","zh":"无障碍标准"},{"phrase":"improve accessibility","zh":"改善可达性"},{"phrase":"accessibility of data","zh":"数据的可获取性"},{"phrase":"accessibility of healthcare","zh":"医疗服务的可负担与可及"}],"forms":[{"label":"单数","form":"accessibility"},{"label":"形容词","form":"accessible（可到达的；可理解的）"},{"label":"副词","form":"accessibly（易懂地；可接近地）"},{"label":"反义名词","form":"inaccessibility（不可达；难以接近）"},{"label":"动词同族","form":"access（访问；进入）"}],"derivatives":[{"word":"access","pos":"n./v.","zh":"同一词根的名词与动词，义为「进入；访问；使用权」"},{"word":"accessible","pos":"adj.","zh":"由该词根加表示「可……的」形容词词尾构成，义为「可到达的；可理解的」"},{"word":"accessibly","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「可接近地；易懂地」"},{"word":"inaccessible","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「难以到达的；难以理解的」"},{"word":"inaccessibility","pos":"n.","zh":"由该否定形容词加名词词尾构成，义为「不可达；难以接近」"}],"senses":[{"no":"01","title":"Ease of reaching a place","titleCN":"到达某地的便利程度","definition":"the quality of a place being easy to reach by road, rail or on foot","definitionCN":"某地可经道路、铁路或步行轻松到达的程度","example":"The survey measured accessibility by travel time from the city centre.","exampleCN":"这项调查以从市中心出发的通行时间来衡量可达性。","why":"The noun turns the act of approaching into a measurable property of a place.","whyCN":"这个名词把「走近」这一动作变成地点身上可测量的属性。"},{"no":"02","title":"Barrier-free access for disabled people","titleCN":"为残障人士消除通行障碍","definition":"the design of buildings, transport and services so that disabled people can use them","definitionCN":"把建筑、交通与服务设计得让残障人士也能使用","example":"Ramps and lifts improved accessibility across the station.","exampleCN":"缓坡与电梯改善了整座车站的无障碍通行。","why":"A place can be physically close and still closed in practice, so the word acquired a design sense.","whyCN":"一个地方可能近在眼前却实际进不去，于是这个词长出了设计义。"},{"no":"03","title":"Digital accessibility","titleCN":"数字无障碍","definition":"the quality of a website or application being usable with screen readers and other aids","definitionCN":"网站或应用可被读屏软件等辅助工具使用的程度","example":"The new portal was audited for accessibility before launch.","exampleCN":"新门户上线前接受了无障碍审查。","why":"Digital products repeat the physical problem: information exists but cannot be reached by every user.","whyCN":"数字产品重复了物理世界的问题：信息存在，却不是每个用户都够得着。"},{"no":"04","title":"Ease of understanding","titleCN":"易于理解","definition":"the quality of language or a document being easy to read and follow","definitionCN":"语言或文件易读易懂的程度","example":"Plain wording raised the accessibility of the guide for general readers.","exampleCN":"通俗的措辞提高了这份指南对普通读者的易读性。","why":"Understanding is another form of reaching, so the same noun covers plain language.","whyCN":"理解是另一种「够得着」，因此同一个名词也管通俗表达。"},{"no":"05","title":"Openness of data and records","titleCN":"数据与记录的开放可获取","definition":"the degree to which data or archives are available to researchers and the public","definitionCN":"数据或档案向研究者与公众开放的程度","example":"Funders now require accessibility of raw data after publication.","exampleCN":"资助方现在要求论文发表后原始数据可获取。","why":"Open science extended the word from buildings to information held in systems.","whyCN":"开放科学把这个词从建筑扩展到系统中保存的信息。"},{"no":"06","title":"Affordability of a service","titleCN":"服务在经济上可负担","definition":"the degree to which a service is within people's financial reach","definitionCN":"某项服务在人们经济能力范围之内的程度","example":"The report links accessibility of care to household income.","exampleCN":"报告把医疗服务的可及性与家庭收入联系起来。","why":"If a service cannot be paid for, it cannot be reached, so cost enters the meaning.","whyCN":"如果一项服务付不起，也就是够不着，于是费用进入词义。"},{"no":"07","title":"A legal right of access","titleCN":"法律上的进入权","definition":"the legal entitlement to enter, use or obtain something","definitionCN":"进入、使用或获取某物的法定权利","example":"The ruling confirmed accessibility to public records as a statutory right.","exampleCN":"这项裁决确认查阅公共记录是法定权利。","why":"Law converts practical reach into an enforceable claim on another party.","whyCN":"法律把实际可达性转成一项可对他人主张的权利。"},{"no":"08","title":"Ease of retrieval in psychology","titleCN":"心理学中的易提取性","definition":"the readiness with which a memory or concept comes to mind","definitionCN":"记忆或概念在脑中被提取出来的容易程度","example":"Repeated exposure increases the accessibility of the concept.","exampleCN":"反复接触会提高该概念在头脑中的可提取性。","why":"Cognitive science borrowed the word for how quickly the mind reaches stored information.","whyCN":"认知科学借这个词说明头脑多快能取到储存的信息。"},{"no":"09","title":"Approachability of a person","titleCN":"人的易于接近","definition":"the quality of a person being easy to talk to or approach","definitionCN":"某人容易交谈、容易接近的程度","example":"Her accessibility to junior staff changed the tone of the office.","exampleCN":"她对年轻员工的平易近人改变了办公室的气氛。","why":"A person, like a building, can be open or closed to approach.","whyCN":"人像建筑一样，可以对人敞开，也可以拒人于外。"}],"etymology":{"intro":{"en":"Accessibility builds on access, from Latin accessus, a coming near, from accedere, to go to, built from ad-, to, and cedere, to go. The endings -ible and -ity are Latin as well. English formed the noun in the nineteenth century.","cn":"这个词建在表示「进入」的词根之上。该词来自拉丁语 accessus「走近」，源头是动词 accedere「走向」，由表示「向」的前缀与表示「行走」的词根构成。两个词尾也出自拉丁语。英语在十九世纪构成这个名词。"},"items":[{"era":"LATIN CEDERE","en":"The verb meant to go or yield, and it also stands behind proceed, precede and concede.","cn":"这个动词意为行走、让出，也是「行进、先于、让步」几个词的源头。"},{"era":"LATIN ACCEDERE","en":"The compound meant to go towards or approach, adding a prefix of direction.","cn":"这个复合动词意为走向、接近，加了表示方向的前缀。"},{"era":"LATIN ACCESSUS","en":"The noun named an approach or an entrance, and it passed into English as access.","cn":"这个名词指接近或入口，进入英语后成为表示「进入」的名词。"},{"era":"THE ENDING -IBLE","en":"The Latin suffix means that can be done, so accessible means that can be reached.","cn":"这个拉丁词尾意为「可以被……的」，因此那个形容词意为可被接近的。"},{"era":"THE ENDING -ITY","en":"The Latin suffix turns an adjective into the name of its quality.","cn":"这个拉丁词尾把形容词变成表示其性质的名称。"},{"era":"ENGLISH NOUN, 19TH CENTURY","en":"English formed the noun in the nineteenth century, first for approachability and later for design and data; the exact first date is uncertain.","cn":"英语在十九世纪构成这个名词，先指可接近性，后扩展到设计与数据；确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the root or the suffix; the second group names neighbouring qualities.","cn":"第一组共享词根或词尾；第二组是相邻的性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"access","ipa":"/ˈækses/","tag":"same root","definition":"The noun or verb for entering or obtaining.","definitionCN":"指进入或获取的名词或动词。"},{"word":"accessible","ipa":"/əkˈsesəbl/","tag":"same root","definition":"The adjective meaning reachable, usable or easy to understand.","definitionCN":"形容词，意为可到达、可使用或易懂的。"},{"word":"accessibly","ipa":"/əkˈsesəbli/","tag":"same root","definition":"In a reachable or easy manner.","definitionCN":"指以可接近或易懂的方式。"},{"word":"accession","ipa":"/əkˈseʃn/","tag":"same root","definition":"The act of coming into possession or office.","definitionCN":"指就任、取得的行为。"},{"word":"accessory","ipa":"/əkˈsesəri/","tag":"same root","definition":"An extra item attached to something larger.","definitionCN":"指附属于较大物件的配件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"availability","ipa":"/əˌveɪləˈbɪləti/","tag":"near meaning","definition":"The state of being obtainable, with less emphasis on physical reach.","definitionCN":"指可获得的状态，较少强调物理可达。"},{"word":"reachability","ipa":"/ˌriːtʃəˈbɪləti/","tag":"near meaning","definition":"A technical term for the possibility of being reached.","definitionCN":"指可被到达的技术术语。"},{"word":"usability","ipa":"/juːˈzəbɪləti/","tag":"near meaning","definition":"How easily a tool or product can be used.","definitionCN":"指工具或产品多容易使用。"},{"word":"openness","ipa":"/ˈəʊpənnəs/","tag":"near meaning","definition":"The quality of being open to all, especially for information.","definitionCN":"指对所有人开放的性质，多用于信息。"},{"word":"affordability","ipa":"/əˌfɔːdəˈbɪləti/","tag":"near meaning","definition":"The quality of being within a person's financial reach.","definitionCN":"指在经济能力范围之内。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the verb of going towards, and the practical tests a place or a page must pass.","cn":"正常联想沿着「走向」这个动词，串起一个地方或一个页面必须通过的实际检验。"},"normal":[{"en":"The root verb means to go, so access is literally a way of going in.","cn":"词根意为行走，所以「进入」字面上就是进去的一条路。"},{"en":"A ramp test asks whether a chair can reach the platform, which is accessibility in its plainest form.","cn":"缓坡的检验就是看轮椅能否到站台，这是最朴素的可达性。"},{"en":"A screen-reader test asks the same question about a web page.","cn":"读屏软件的检验对网页提出同样的问题。"},{"en":"Plain wording is accessibility for readers, because understanding is a way of arriving.","cn":"通俗措辞是给读者的可达性，因为理解也是一种抵达。"},{"en":"Affordability belongs here too: a service out of financial reach is out of reach.","cn":"可负担性也归在这里：付不起的服务就是够不着。"}],"abstract":[{"en":"Accessibility is a question asked from the far side: can I get there, or only look at it?","cn":"可达性是从远处提出的问题：我能过去，还是只能看着？"},{"en":"Every door has two states, open and closed, and the noun measures the distance between them.","cn":"每扇门都有开与关两种状态，这个名词衡量的是两者之间的距离。"},{"en":"A society's accessibility is the sum of the doors it leaves open by design.","cn":"一个社会的可达性，就是它有意留开的那一扇扇门之和。"}]},"examples":[{"en":"Accessibility of the site improved after the new footbridge opened.","cn":"新步行桥开通后，该场地的可达性提高了。"},{"en":"The report rates accessibility for blind users on every page.","cn":"报告逐页评估了盲人用户的无障碍程度。"},{"en":"Accessibility of the archive depends on how the records are catalogued.","cn":"档案的可获取程度取决于记录如何编目。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿克塞斯比勒提」——脚下的路能走到、门能推开，就是「可达性、无障碍」：可达性、无障碍性","word":"accessibility"},"root":"这个词根来自拉丁语 accessus「走近」，源头是 accedere「走向」，由表示「向」的前缀与表示「行走」的动词构成；表示「可被……的」的形容词词尾与把形容词变成性质名词的名词词尾共同构成这个名词。英语在十九世纪构成该名词，确切首见年代不确定。","sensesIntro":{"en":"Nine senses carry one idea, reaching, across places, designs, data, language, money, law, memory and people.","cn":"九个义项把同一个「够得着」的意思，铺到地点、设计、数据、语言、金钱、法律、记忆与人身上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a new ramp at a bus stop, with a wheelchair rolling up to the platform and a tactile path joining it.","cn":"核心意象：公交站旁的新缓坡，轮椅推上站台，盲道一路接到车门。"},"chain":["GOING TOWARDS","REACHING A PLACE","REMOVING BARRIERS","REACHING INFORMATION","REACHING MEANING","REACHING PEOPLE"],"branches":[{"senses":"01","en":"THE PHYSICAL REACH: travel time and distance decide whether a place is accessible.","cn":"物理可达：通行时间与距离决定一个地方是否够得着。"},{"senses":"02 · 03","en":"THE REMOVED BARRIER: ramps, lifts and screen readers open what was closed.","cn":"被移除的障碍：缓坡、电梯与读屏软件把关闭的东西打开。"},{"senses":"04 · 05","en":"THE REACHED INFORMATION: plain language and open data.","cn":"被够到的信息：通俗语言与开放数据。"},{"senses":"06 · 07","en":"THE ECONOMIC AND LEGAL REACH: a price that can be met, and a right that can be claimed.","cn":"经济与法律的可及：付得起的价格，以及可主张的权利。"},{"senses":"08 · 09","en":"THE MENTAL AND SOCIAL REACH: a memory that surfaces easily, a person easy to approach.","cn":"心理与社交的可及：容易浮现的记忆，以及容易接近的人。"}]},"affixes":{"intro":{"en":"The word is Latin from end to end: a verb of going, a prefix of direction, and two suffixes of possibility and quality.","cn":"这个词从头到尾都出自拉丁语：表示行走的动词、表示方向的前缀，以及分别表示可能与性质的两个词尾。"},"latinIntro":{"en":"Latin supplies the verb of going, the prefix, the noun of approach and the two suffixes.","cn":"拉丁语提供了表示行走的动词、方向前缀、表示接近的名词与两个词尾。"},"items":[{"word":"cedere","structure":"Latin verb","meaning":"to go, to yield","meaningCN":"行走；让出","example":"It also stands behind proceed and concede.","exampleCN":"它也是「行进」与「让步」二词的源头。"},{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"向；朝","example":"It gives the going a direction.","exampleCN":"它给「行走」一个方向。"},{"word":"accedere","structure":"Latin verb","meaning":"to go towards","meaningCN":"走向；接近","example":"The verb describes coming near.","exampleCN":"这个动词描述走近。"},{"word":"accessus","structure":"Latin noun","meaning":"an approach, an entrance","meaningCN":"接近；入口","example":"English took it as access.","exampleCN":"英语把它借为表示进入的名词。"},{"word":"-ible","structure":"Latin suffix","meaning":"that can be done","meaningCN":"可以被……的","example":"It marks the possibility of being reached.","exampleCN":"它标记「可被接近」的可能性。"},{"word":"-ity","structure":"Latin suffix","meaning":"the quality of","meaningCN":"……的性质","example":"It turns the adjective into a noun.","exampleCN":"它把形容词变成名词。"},{"word":"accessible","structure":"English adjective","meaning":"reachable; usable","meaningCN":"可到达的；可使用的","example":"The adjective states the possibility.","exampleCN":"这个形容词陈述可能性。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不","example":"It forms inaccessible, out of reach.","exampleCN":"它构成表示「够不着」的形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb of manner.","exampleCN":"它构成方式副词。"},{"word":"accessibility","structure":"English noun","meaning":"the quality of being reachable","meaningCN":"可达性；无障碍性","example":"The whole noun names the measured quality.","exampleCN":"整个名词指这项被衡量的性质。"}],"latinEntries":[{"word":"cedere","structure":"Latin verb","meaning":"to go","meaningCN":"行走"},{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"向"},{"word":"accedere","structure":"Latin verb","meaning":"to approach","meaningCN":"接近"},{"word":"accessus","structure":"Latin noun","meaning":"approach, entrance","meaningCN":"接近；入口"}],"derivatives":[{"word":"access","pos":"n./v.","zh":"同一词根，义为「进入；访问」"},{"word":"accessible","pos":"adj.","zh":"加表示可能的词尾构成，义为「可到达的」"},{"word":"accessibly","pos":"adv.","zh":"加副词词尾构成，义为「可接近地」"},{"word":"inaccessible","pos":"adj.","zh":"加否定前缀构成，义为「难以到达的」"},{"word":"inaccessibility","pos":"n.","zh":"加名词词尾构成，义为「不可达」"}]}},{"word":"adequacy","ipa_uk":"/ˈædɪkwəsi/","ipa_us":"/ˈædɪkwəsi/","definition_zh":"充足性；适当性；够用程度；胜任程度","definition_en":"the quality of being enough or suitable for a particular purpose","core_image":"粮仓里管理员把账本与堆垛逐层对照，确认存量能撑到下一季","scene":"粮仓盘点时，管理员把账本与堆垛逐层对照，算出存量够撑到下一季。Inspectors questioned the adequacy of the grain reserve.","sceneCN":"这里指数量是否够用（第 1 个义项：充足性）；句意为检查人员质疑粮食储备是否充足。图中可辨识物件：粮袋、账本、量尺、仓门。","pos":[{"tag":"n.","zh":"名词：充足性；适当性；够用程度（不可数）"}],"collocations":[{"phrase":"adequacy of evidence","zh":"证据的充分性"},{"phrase":"adequacy of funding","zh":"资金是否充足"},{"phrase":"adequacy of the sample","zh":"样本的充足性"},{"phrase":"adequacy of a response","zh":"反应的适当性"},{"phrase":"adequacy of training","zh":"培训是否够用"},{"phrase":"question the adequacy of","zh":"质疑……是否足够"}],"forms":[{"label":"单数","form":"adequacy"},{"label":"形容词","form":"adequate（足够的；适当的）"},{"label":"副词","form":"adequately（充分地）"},{"label":"反义名词","form":"inadequacy（不足；不胜任）"},{"label":"反义形容词","form":"inadequate（不够的；不适当的）"},{"label":"动词同族","form":"equate（使相等；等同看待）"}],"derivatives":[{"word":"adequate","pos":"adj.","zh":"由拉丁分词进入英语，义为「足够的；适当的」"},{"word":"adequately","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「充分地」"},{"word":"inadequate","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「不足的；不适当的」"},{"word":"inadequacy","pos":"n.","zh":"由该否定形容词加名词词尾构成，义为「不足；不胜任」"},{"word":"equate","pos":"v.","zh":"由同一拉丁词根「相等」构成，义为「使相等；等同」"}],"senses":[{"no":"01","title":"Sufficiency of quantity","titleCN":"数量上的充足","definition":"the quality of there being enough of something for a stated need","definitionCN":"某物的数量足以满足既定需要的性质","example":"The audit examined the adequacy of the grain reserve.","exampleCN":"审计检查了粮食储备是否充足。","why":"The word asks whether a quantity measures up to a standard, not whether it is large.","whyCN":"这个词问的是数量是否达到标准，而不是数量大不大。"},{"no":"02","title":"Strength of evidence","titleCN":"证据的充分","definition":"the quality of evidence being enough to support a conclusion","definitionCN":"证据足以支撑某一结论的性质","example":"Reviewers doubted the adequacy of the evidence for the claim.","exampleCN":"审稿人怀疑支持该说法的证据不够充分。","why":"Research standards need a word for evidence that is enough rather than merely present.","whyCN":"研究规范需要一个词，形容证据不只存在而且够用。"},{"no":"03","title":"Sufficiency of funding","titleCN":"资金的充足","definition":"the quality of money or resources being enough for a task","definitionCN":"资金或资源足以完成某项任务的性质","example":"The board questioned the adequacy of funding for maintenance.","exampleCN":"董事会质疑维护资金是否充足。","why":"Budgets are judged against needs, which makes this a standard word in administration.","whyCN":"预算要对照需求来评判，这个词因此成为行政常用语。"},{"no":"04","title":"Fit of an explanation","titleCN":"解释是否站得住","definition":"the quality of an account or model being enough to explain the facts","definitionCN":"某种说明或模型足以解释事实的性质","example":"Philosophers argue about the adequacy of the model rather than its elegance.","exampleCN":"哲学家争论的是这个模型够不够用，而不是它优不优雅。","why":"An elegant model that leaves facts unexplained is not adequate, so the test is coverage rather than beauty.","whyCN":"一个优雅却解释不了事实的模型仍不算够用，所以检验的是覆盖面而不是美感。"},{"no":"05","title":"Legal adequacy of consideration","titleCN":"法律上对价的充分","definition":"in contract law, the quality of the bargain being sufficient in law, though not necessarily equal in value","definitionCN":"合同法中，交易在法律上足够成立的性质，价值不必相等","example":"The court accepted the adequacy of the consideration.","exampleCN":"法院认可了这项对价的充分性。","why":"Law separates adequacy from fairness: a low price can still be adequate.","whyCN":"法律把「充分」与「公平」分开：价格低仍可能构成充分对价。"},{"no":"06","title":"Adequacy of a response","titleCN":"反应的适当","definition":"the quality of a reply or action being enough for the situation","definitionCN":"回应或行动足以应对局面的性质","example":"Critics questioned the adequacy of the emergency response.","exampleCN":"批评者质疑应急反应是否到位。","why":"A response can be timely and still not enough, so the word measures fit as well as size.","whyCN":"回应可能及时却仍不够，这个词既衡量匹配也衡量分量。"},{"no":"07","title":"Adequacy of representation","titleCN":"代理的充分","definition":"in law and advocacy, the quality of a representative acting fully for a client's interests","definitionCN":"法律与维权中，代理人是否充分代表当事人利益的性质","example":"The appeal challenged the adequacy of legal representation.","exampleCN":"上诉质疑律师代理是否充分。","why":"Representation is judged by whether the client's interests were fully carried, not by effort alone.","whyCN":"代理是否充分看当事人利益有没有被完整带到，而不只看投入。"},{"no":"08","title":"Adequacy of a sample","titleCN":"样本的充分","definition":"the quality of a sample being large or varied enough for valid inference","definitionCN":"样本在数量或多样性上足以支持有效推断的性质","example":"Statisticians tested the adequacy of the sample before analysis.","exampleCN":"统计人员在分析前检验了样本是否足够。","why":"Inference needs a threshold, and this word names that threshold being met.","whyCN":"推断需要一个门槛，这个词指门槛被达到。"},{"no":"09","title":"Adequacy of preparation","titleCN":"准备是否充分","definition":"the quality of training or preparation being enough for a task","definitionCN":"培训或准备足以应付任务的性质","example":"Inspectors assessed the adequacy of training for night shifts.","exampleCN":"检查人员评估了夜班培训是否够用。","why":"Preparation is measured against the shift it must cover, so the word asks whether training meets the demand.","whyCN":"准备要对它所要覆盖的班次来量，因此这个词问的是培训是否达到要求。"}],"etymology":{"intro":{"en":"Adequacy comes from adequate, from Latin adaequatus, the past participle of adaequare, to make equal to, built from ad-, to, and aequare, to make level, from aequus, level or equal. English added the noun ending -acy in the seventeenth century.","cn":"这个词来自表示「足够的」的形容词，源头是拉丁语 adaequatus「使与之相等」，是动词 adaequare 的过去分词，由表示「向」的前缀与表示「使平」的词根构成，后者出自意为「平的、相等的」形容词。英语在十七世纪加上名词词尾构成这个词。"},"items":[{"era":"LATIN AEQUUS","en":"The adjective meant level, even or fair, and it also stands behind equity and equality.","cn":"这个形容词意为平的、均等的、公平的，也是「公平」与「平等」二词的源头。"},{"era":"LATIN AEQUARE","en":"The verb meant to make level or to make equal.","cn":"这个动词意为使平、使相等。"},{"era":"LATIN ADAEQUARE","en":"The compound meant to make something equal to a standard, adding a prefix of direction.","cn":"这个复合动词意为使某物与标准相等，加了表示方向的前缀。"},{"era":"LATIN ADAEQUATUS","en":"The participle described something made equal to what was required.","cn":"这个分词形容被做到与要求相等的某物。"},{"era":"ENGLISH ADEQUATE, 17TH CENTURY","en":"English took the participle as an adjective meaning equal to a need, hence sufficient.","cn":"英语把这个分词用作形容词，意为与需要相称，因而是足够的。"},{"era":"THE NOUN ADEQUACY","en":"The noun for the quality appeared soon after; its exact first date is uncertain.","cn":"表示这种性质的名词随后出现；确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the root or the negative prefix; the second group names other standards of enoughness.","cn":"第一组共享词根或否定前缀；第二组是其他表示「够」的标准。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"adequate","ipa":"/ˈædɪkwət/","tag":"same root","definition":"The adjective meaning enough for the purpose.","definitionCN":"形容词，意为够用的、适当的。"},{"word":"adequately","ipa":"/ˈædɪkwətli/","tag":"same root","definition":"In a manner that is enough.","definitionCN":"指以足够的方式。"},{"word":"inadequate","ipa":"/ɪnˈædɪkwət/","tag":"same root","definition":"Not enough or not suitable.","definitionCN":"指不够或不适当。"},{"word":"inadequacy","ipa":"/ɪnˈædɪkwəsi/","tag":"same root","definition":"The noun for a shortfall or unfitness.","definitionCN":"指不足或不适当的名称。"},{"word":"equate","ipa":"/ɪˈkweɪt/","tag":"same root","definition":"To treat two things as equal, from the same verb of levelling.","definitionCN":"由同一个「使平」动词而来，意为把两物等同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sufficiency","ipa":"/səˈfɪʃnsi/","tag":"near meaning","definition":"The quality of being enough, with less emphasis on suitability.","definitionCN":"指足够，较少强调适当。"},{"word":"suitability","ipa":"/ˌsuːtəˈbɪləti/","tag":"near meaning","definition":"The quality of fitting a purpose.","definitionCN":"指适合某一用途。"},{"word":"fitness","ipa":"/ˈfɪtnəs/","tag":"near meaning","definition":"The quality of being appropriate or in good condition.","definitionCN":"指适当或状态良好。"},{"word":"competence","ipa":"/kəmˈpiːtəns/","tag":"near meaning","definition":"The ability to do a task well enough.","definitionCN":"指足以胜任任务的能力。"},{"word":"enoughness","ipa":"/ɪˈnʌfnəs/","tag":"near meaning","definition":"A rare noun for the state of being enough.","definitionCN":"较少见的说法，指「足够」这一状态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the verb of making equal, because adequacy means measuring up to a standard.","cn":"正常联想沿着「使相等」这个动词，因为充足就是把标准量齐。"},"normal":[{"en":"The Latin verb means to make equal, so adequate things are level with the standard set for them.","cn":"拉丁动词意为使相等，所以够用的东西与为它设定的标准齐平。"},{"en":"Audits ask about the grain reserve: is the amount equal to the need?","cn":"审计问的是粮食储备：数量是否与需求相称？"},{"en":"Contract law separates adequacy from fairness, so a low price can still be adequate.","cn":"合同法把充分与公平分开，所以低价也可能构成充分对价。"},{"en":"Reviewers ask about the sample: enough cases for a valid inference.","cn":"审稿人问样本：案例是否足以支撑有效推断。"},{"en":"The negative form, inadequacy, is the more common word when something falls short.","cn":"当某物不够时，否定形式反而更常用。"}],"abstract":[{"en":"Adequacy is not abundance: it is the exact point where a need is met.","cn":"充足不是充裕：它是需求刚好被满足的那个点。"},{"en":"Every standard draws a line, and this word reports that the line has been reached.","cn":"每个标准都画一条线，这个词报告线已被达到。"},{"en":"Enough is a relation, not a quantity; the same amount is adequate here and short there.","cn":"「够」是一种关系而非数量；同样的分量在这里够用，在那里不够。"}]},"examples":[{"en":"The committee reviewed the adequacy of the safety measures.","cn":"委员会审查了安全措施是否充分。"},{"en":"Adequacy of the sample was the main weakness of the study.","cn":"样本是否充分是这项研究的主要弱点。"},{"en":"Donors asked about the adequacy of staffing in rural clinics.","cn":"捐助方询问农村诊所的人手是否够用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿德夸西」——天平两端刚好齐平，不多不少，就是「充足、适当」：充足性、适当性","word":"adequacy"},"root":"这个词根来自拉丁语 adaequatus，是 adaequare「使与……相等」的过去分词，由表示「向」的前缀与 aequare「使平」构成，后者出自 aequus「平的、相等的」；英语在十七世纪加名词词尾构成这个名词，确切首见年代不确定。","sensesIntro":{"en":"Nine senses measure enoughness against nine standards: a quantity, evidence, money, a model, a contract, a response, a representative, a sample and training.","cn":"九个义项让「够不够」对着九把尺子：数量、证据、资金、模型、合同、反应、代理人、样本与培训。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warehouse ledger held against stacked sacks, the numbers checked line by line.","cn":"核心意象：账簿贴着成堆粮袋，一行行核对数字。"},"chain":["MAKING LEVEL","MEETING A STANDARD","ENOUGH QUANTITY","ENOUGH EVIDENCE","ENOUGH RESOURCES","FIT FOR A ROLE"],"branches":[{"senses":"01","en":"THE MEASURED QUANTITY: the reserve is weighed against the need.","cn":"被量的数量：储备对着需求称一称。"},{"senses":"02 · 08","en":"THE ENOUGH EVIDENCE: a sample and its data must support the inference.","cn":"够用的证据：样本与数据必须撑得住推断。"},{"senses":"03","en":"THE ENOUGH MONEY: funding is judged against the task.","cn":"够用的钱：资金要对着任务来评判。"},{"senses":"04 · 06","en":"THE FIT EXPLANATION AND RESPONSE: a model or an answer must cover the case.","cn":"合适的解释与反应：模型或答复必须罩得住情形。"},{"senses":"05 · 07 · 09","en":"THE LEGAL AND PROFESSIONAL FIT: consideration, representation and training must be sufficient in law and in practice.","cn":"法律与职业上的相称：对价、代理与培训在法律与实务上都必须够。"}]},"affixes":{"intro":{"en":"The word is built on a Latin verb of levelling, so adequacy is a scale rather than a heap.","cn":"这个词建在一个表示「使平」的拉丁动词上，因此充足是一杆秤，而不是一堆东西。"},"latinIntro":{"en":"Latin supplies the adjective of equality, the verb of levelling, its compound and its participle.","cn":"拉丁语提供了表示相等的形容词、表示使平的动词、其复合形式与分词。"},"items":[{"word":"aequus","structure":"Latin adjective","meaning":"level, equal, fair","meaningCN":"平的；相等的；公平的","example":"It also stands behind equity.","exampleCN":"它也是「公平」一词的源头。"},{"word":"aequare","structure":"Latin verb","meaning":"to make level or equal","meaningCN":"使平；使相等","example":"The verb supplies the idea of matching a standard.","exampleCN":"这个动词提供「与标准齐平」的意思。"},{"word":"ad-","structure":"Latin prefix","meaning":"to, towards","meaningCN":"向；朝","example":"It points the levelling at a standard.","exampleCN":"它把「使平」指向某个标准。"},{"word":"adaequare","structure":"Latin verb","meaning":"to make equal to","meaningCN":"使与……相等","example":"The compound is the direct source of the English word.","exampleCN":"这个复合动词是英语词的直接源头。"},{"word":"adaequatus","structure":"Latin participle","meaning":"made equal to","meaningCN":"被做到相等的","example":"English took it as the adjective adequate.","exampleCN":"英语把它用作形容词。"},{"word":"-acy","structure":"Latin noun ending through French","meaning":"the quality or state","meaningCN":"性质或状态","example":"It turns the adjective into a noun of quality.","exampleCN":"它把形容词变成表示性质的名词。"},{"word":"adequate","structure":"English adjective","meaning":"enough, suitable","meaningCN":"足够的；适当的","example":"The adjective states that a standard is met.","exampleCN":"这个形容词说明标准被达到。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不","example":"It forms inadequate, falling short.","exampleCN":"它构成表示「不够」的形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb adequately.","exampleCN":"它构成副词。"},{"word":"adequacy","structure":"English noun","meaning":"the quality of being enough","meaningCN":"充足性","example":"The whole noun names the measured fit.","exampleCN":"整个名词指被衡量的相称。"}],"latinEntries":[{"word":"aequus","structure":"Latin adjective","meaning":"level, equal","meaningCN":"平的；相等的"},{"word":"aequare","structure":"Latin verb","meaning":"to make equal","meaningCN":"使相等"},{"word":"adaequare","structure":"Latin verb","meaning":"to make equal to","meaningCN":"使与……相等"},{"word":"adaequatus","structure":"Latin participle","meaning":"made equal","meaningCN":"被使相等的"}],"derivatives":[{"word":"adequate","pos":"adj.","zh":"由拉丁分词而来，义为「足够的；适当的」"},{"word":"adequately","pos":"adv.","zh":"加副词词尾构成，义为「充分地」"},{"word":"inadequate","pos":"adj.","zh":"加否定前缀构成，义为「不足的」"},{"word":"inadequacy","pos":"n.","zh":"加名词词尾构成，义为「不足；不胜任」"},{"word":"equate","pos":"v.","zh":"由同一词根构成，义为「使相等」"}]}},{"word":"autonomy","ipa_uk":"/ɔːˈtɒnəmi/","ipa_us":"/ɑːˈtɑːnəmi/","definition_zh":"自治；自主；自主权；自主性","definition_en":"the power or right to govern oneself or to act independently","core_image":"手术室里主刀医生按判断改动切口，没有等行政人员签字","scene":"手术室里，主刀医生按自己的判断改动了切口位置，没有等行政人员批准。The hospital defends the autonomy of its surgical teams.","sceneCN":"这里指专业人员在自己的领域内自主决定（第 4 个义项：专业自主权）；句意为医院维护外科团队的自主权。图中可辨识物件：手术灯、器械台、病历夹、签字笔。","pos":[{"tag":"n.","zh":"名词：自治；自主；自主权（不可数，指具体自治体时偶作可数）"}],"collocations":[{"phrase":"regional autonomy","zh":"区域自治"},{"phrase":"personal autonomy","zh":"个人自主"},{"phrase":"professional autonomy","zh":"专业自主权"},{"phrase":"learner autonomy","zh":"学习者自主"},{"phrase":"autonomy of universities","zh":"大学自治"},{"phrase":"grant autonomy to","zh":"给予……自主权"}],"forms":[{"label":"单数","form":"autonomy"},{"label":"可数用法（少见）","form":"autonomies（多个自治体）"},{"label":"形容词","form":"autonomous（自治的；自主的）"},{"label":"副词","form":"autonomously（自主地）"},{"label":"反义名词","form":"heteronomy（他律）"},{"label":"同族名词","form":"autonomist（自治主张者）"}],"derivatives":[{"word":"autonomous","pos":"adj.","zh":"由希腊词根加形容词词尾构成，义为「自治的；自主的」"},{"word":"autonomously","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「自主地」"},{"word":"autonomist","pos":"n.","zh":"由词根加表示人的词尾构成，义为「自治主张者」"},{"word":"autonomy","pos":"n.","zh":"由希腊名词经法语进入英语，义为「自治；自主」"},{"word":"heteronomy","pos":"n.","zh":"由表示「他者」的前缀加同一词根构成，义为「他律」"}],"senses":[{"no":"01","title":"Self-government of a region","titleCN":"地区的自治","definition":"the right of a region or people to govern its own affairs within a larger state","definitionCN":"地区或民族在大国之内管理自身事务的权利","example":"The province gained autonomy over its schools and hospitals.","exampleCN":"该省获得了管理本省学校与医院的自治权。","why":"The Greek word joins self and law, so autonomy is literally the power to give oneself law.","whyCN":"这个希腊词由「自我」与「法律」合成，因此自治字面上就是给自己立法的权力。"},{"no":"02","title":"Personal autonomy","titleCN":"个人自主","definition":"the capacity of a person to make decisions without being controlled by others","definitionCN":"个人不受他人控制而自行决定的能力","example":"Patients value autonomy in decisions about their own care.","exampleCN":"病人珍视在自身照护上的自主决定权。","why":"Political self-rule became a model for the individual ruling himself.","whyCN":"政治上的自治成了个人自我治理的模型。"},{"no":"03","title":"Institutional autonomy","titleCN":"机构自治","definition":"the freedom of an institution such as a university to set its own rules","definitionCN":"大学等机构自行制定规则的自由","example":"The reform protected the autonomy of universities in hiring.","exampleCN":"这项改革保护了大学在招聘上的自治。","why":"An institution with its own law is one that can choose its members and methods.","whyCN":"拥有自身规则的机构，才能选择自己的成员与方法。"},{"no":"04","title":"Professional autonomy","titleCN":"专业自主权","definition":"the freedom of trained professionals to make expert judgments without outside direction","definitionCN":"受过训练的专业人员在不受外部指挥下作出专业判断的自由","example":"The college defended the autonomy of surgeons in the operating room.","exampleCN":"该院维护外科医生在手术室里的自主权。","why":"Expertise is useless if the judgment can be overridden by administrators.","whyCN":"如果专业判断能被行政人员推翻，专业知识就失去作用。"},{"no":"05","title":"Learner autonomy","titleCN":"学习者自主","definition":"the capacity of a student to plan and monitor his or her own learning","definitionCN":"学生自行规划与监控学习的能力","example":"The course builds autonomy by letting students choose their reading.","exampleCN":"这门课通过让学生自选读物来培养自主性。","why":"Education borrowed the political word for the student who sets his own targets.","whyCN":"教育学借来这个政治词，指为自己设定目标的学生。"},{"no":"06","title":"Job autonomy","titleCN":"工作自主","definition":"the degree of freedom an employee has in deciding how to do the work","definitionCN":"雇员在决定如何完成工作上拥有的自由程度","example":"Higher autonomy at work predicted lower staff turnover.","exampleCN":"工作中的自主权越高，员工流失率越低。","why":"Management research measures autonomy as control over method and schedule.","whyCN":"管理学把自主权测量为对方法与进度的控制。"},{"no":"07","title":"Machine autonomy","titleCN":"机器的自主","definition":"the ability of a system to operate and decide without a human operator","definitionCN":"系统无需人操作即可运行与决策的能力","example":"Engineers tested the autonomy of the vehicle in heavy rain.","exampleCN":"工程师在暴雨中测试了这辆车的自主能力。","why":"Self-rule was extended to machines that set their own course of action.","whyCN":"「自治」被扩展到能自行决定行动路线的机器。"},{"no":"08","title":"Moral autonomy","titleCN":"道德自主","definition":"the capacity to act according to a law one gives oneself, rather than external pressure","definitionCN":"按自己给自己立的法则而非外部压力行动的能力","example":"Moral autonomy requires judging for oneself rather than obeying blindly.","exampleCN":"道德自主要求自己判断，而不是盲目服从。","why":"Moral philosophy turned the image of self-legislation into a standard of dignity.","whyCN":"道德哲学把「自我立法」的形象变成尊严的标准。"},{"no":"09","title":"Patient autonomy in medical ethics","titleCN":"医疗伦理中的病人自主","definition":"the principle that a patient's informed choice governs treatment","definitionCN":"病人的知情选择主导治疗方案的原则","example":"Consent forms put patient autonomy before clinical convenience.","exampleCN":"知情同意书把病人自主放在临床便利之前。","why":"Medical ethics needed a principle that could overrule a clinician's recommendation.","whyCN":"医疗伦理需要一个能推翻临床建议的原则。"}],"etymology":{"intro":{"en":"Autonomy came into English from Greek autonomia, the state of having one's own law, built from autos, self, and nomos, law or custom. It reached English through French in the seventeenth century, first as a word about states and later about persons.","cn":"这个词经法语进入英语，源头是希腊语 autonomia「拥有自己的法律的状态」，由表示「自我」的词与表示「法律、习俗」的词构成。它在十七世纪进入英语，最先用于国家，后来才用于个人。"},"items":[{"era":"GREEK AUTOS","en":"The pronoun meant self, and it supplies the first element in autonomy, automatic and autograph.","cn":"这个词意为「自我」，是「自治」「自动」「亲笔」等词的第一个成分。"},{"era":"GREEK NOMOS","en":"The noun meant law, custom or rule, and it also stands behind economy and astronomy.","cn":"这个名词意为法律、习俗、规则，也是「经济」与「天文」等词的成分。"},{"era":"GREEK AUTONOMIA","en":"The noun described a community that lived under its own laws rather than those of a ruler.","cn":"这个名词描述按自己的法律而非统治者法律生活的共同体。"},{"era":"FRENCH AUTONOMIE","en":"French carried the political word into wider European use in the early modern period.","cn":"法语在近代早期把这个政治词带进更广的欧洲使用。"},{"era":"ENGLISH AUTONOMY, 17TH CENTURY","en":"English first applied it to states and churches, and the exact first date is uncertain.","cn":"英语最初把它用于国家与教会，确切首见年代不确定。"},{"era":"MODERN EXTENSIONS","en":"Later centuries applied it to individuals, professions, learners, patients and machines.","cn":"后来的几个世纪把它扩展到个人、专业、学习者、病人与机器。"}]},"similar":{"note":{"en":"The first group shares the Greek elements; the second group names neighbouring kinds of independence.","cn":"第一组共享希腊语成分；第二组是相邻的独立概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"autonomous","ipa":"/ɔːˈtɒnəməs/","tag":"same root","definition":"The adjective for self-governing or self-directing.","definitionCN":"形容词，意为自治的、自主的。"},{"word":"autonomously","ipa":"/ɔːˈtɒnəməsli/","tag":"same root","definition":"In a self-directed manner.","definitionCN":"指以自主方式。"},{"word":"autonomist","ipa":"/ɔːˈtɒnəmɪst/","tag":"same root","definition":"A supporter of autonomy for a region or group.","definitionCN":"指主张地区或群体自治的人。"},{"word":"automatic","ipa":"/ɔːˈtɒmætɪk/","tag":"shared first element","definition":"Self-acting, from the same first element but a different second one.","definitionCN":"指自动的；共享第一个成分，但第二个成分不同。"},{"word":"heteronomy","ipa":"/ˌhetəˈrɒnəmi/","tag":"same root, opposite prefix","definition":"Rule by another, the opposite of self-rule.","definitionCN":"指由他者支配，与自治相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","tag":"near meaning","definition":"Freedom from control by another, often political.","definitionCN":"指不受他人控制，多用于政治。"},{"word":"self-government","ipa":"/ˌself ˈɡʌvənmənt/","tag":"near meaning","definition":"The act of governing oneself, used mostly of territories.","definitionCN":"指自我治理，多用于地区。"},{"word":"sovereignty","ipa":"/ˌsəʊvəˈreɪnti/","tag":"near meaning","definition":"Supreme authority over a territory, stronger than autonomy.","definitionCN":"指对领土的最高权力，比自治更强。"},{"word":"freedom","ipa":"/ˈfriːdəm/","tag":"near meaning","definition":"The general condition of not being constrained.","definitionCN":"指不受约束的一般状态。"},{"word":"self-determination","ipa":"/ˌself dɪˌtɜːmɪˈneɪʃn/","tag":"near meaning","definition":"The right of a people to choose its own status.","definitionCN":"指民族自行决定自身地位的权利。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two Greek parts, self and law, and the domains that borrowed them.","cn":"正常联想使用两个希腊成分「自我」与「法律」，以及借用它们的各个领域。"},"normal":[{"en":"Autonomy is self plus law: the power to give yourself the rule you live by.","cn":"自治就是「自我」加「法律」：给自己立下所循规则的权力。"},{"en":"A province with autonomy writes its own school rules, which is the political sense.","cn":"拥有自治的省份自己写学校规则，这是政治义。"},{"en":"A surgeon with autonomy decides the incision without waiting for an administrator.","cn":"有自主权的外科医生自行决定切口，不必等行政人员。"},{"en":"A learner with autonomy chooses the reading list, and a worker with autonomy chooses the method.","cn":"自主的学习者自选书单，自主的工人自选方法。"},{"en":"A vehicle with autonomy chooses its own route, extending self-rule to machines.","cn":"自主的车辆自选路线，把自治扩展到机器。"}],"abstract":[{"en":"Every autonomy is a border drawn twice: once around the self, once around the law.","cn":"每一种自主都是画了两次的边界：一次围住自我，一次围住法律。"},{"en":"To be autonomous is to be the author of the rule one obeys, and also its prisoner.","cn":"自主意味着既是所循规则的作者，也是它的囚徒。"},{"en":"Institutions ask for autonomy in the same words that peoples once used for independence.","cn":"机构索要自主时用的词，与民族当年索要独立时用的是同一套。"}]},"examples":[{"en":"The treaty granted autonomy to the coastal region.","cn":"条约给予沿海地区自治权。"},{"en":"Clinical staff resisted limits on their autonomy in treatment decisions.","cn":"临床人员抵制对治疗决策自主权的限制。"},{"en":"The software was designed to operate with greater autonomy in remote areas.","cn":"这款软件被设计成能在偏远地区以更高自主性运行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「奥托诺米」——自己给自己定规矩，不用别人管，就是「自治、自主」：自治、自主权","word":"autonomy"},"root":"经法语来自希腊语 autonomia「拥有自己的法律的状态」，由 autos「自我」与 nomos「法律、习俗」构成；十七世纪进入英语，最初用于国家与教会，后扩展到个人、专业、学习者、病人与机器，确切首见年代不确定。","sensesIntro":{"en":"Nine senses apply self-rule to a region, a person, an institution, a profession, a learner, a job, a machine, a moral agent and a patient.","cn":"九个义项把「自我立法」用在地区、个人、机构、专业、学习者、工作、机器、道德主体与病人身上。"},"semanticMap":{"core":{"en":"CORE IMAGE: an operating lamp above a table, and a surgeon changing the incision line without waiting for a signature.","cn":"核心意象：手术台上方的灯，以及不等签字就改动切口的医生。"},"chain":["SELF","OWN LAW","SELF-GOVERNMENT","INSTITUTIONAL RULE","PROFESSIONAL JUDGMENT","SELF-DIRECTING SYSTEM"],"branches":[{"senses":"01","en":"THE POLITICAL SELF-RULE: a region lives under laws it makes.","cn":"政治自治：地区按自己制定的法律生活。"},{"senses":"02 · 08 · 09","en":"THE PERSONAL AND MORAL SELF-RULE: a person decides, judges and consents.","cn":"个人与道德的自治：个人自行决定、判断与同意。"},{"senses":"03 · 05","en":"THE INSTITUTION AND THE LEARNER: a body or a student sets its own course.","cn":"机构与学习者：机构或学生自定方向。"},{"senses":"04 · 06","en":"THE PROFESSIONAL AND THE WORKER: expert judgment and control over method.","cn":"专业与工作者：专业判断，以及对方法的控制。"},{"senses":"07","en":"THE MACHINE: a system that selects its own course of action.","cn":"机器：自行选择行动路线的系统。"}]},"affixes":{"intro":{"en":"The word is Greek in both halves, self and law, with only a noun ending added in English.","cn":"这个词的两半都出自希腊语：自我与法律，英语只加了一个名词词尾。"},"latinIntro":{"en":"There is no native Latin root for this word; the Latin forms listed are later borrowings from Greek.","cn":"这个词没有本土拉丁词根；列出的拉丁形式是后来从希腊语借入的。"},"items":[{"word":"autos","structure":"Greek pronoun","meaning":"self","meaningCN":"自我","example":"It is the first element of autonomy and automatic.","exampleCN":"它是「自治」与「自动」的第一个成分。"},{"word":"nomos","structure":"Greek noun","meaning":"law, custom","meaningCN":"法律；习俗","example":"It is the second element of autonomy.","exampleCN":"它是「自治」的第二个成分。"},{"word":"autonomia","structure":"Greek noun","meaning":"the state of having one's own law","meaningCN":"拥有自己的法律的状态","example":"The noun described self-governing communities.","exampleCN":"这个名词描述自治的共同体。"},{"word":"autonomie","structure":"French noun","meaning":"autonomy","meaningCN":"自治","example":"French carried the word into wider European use.","exampleCN":"法语把这个词带进更广的欧洲使用。"},{"word":"autonomy","structure":"English noun","meaning":"self-government; independence","meaningCN":"自治；自主","example":"English uses it for states, people and machines.","exampleCN":"英语用它指国家、人与机器。"},{"word":"autonomous","structure":"English adjective","meaning":"self-governing","meaningCN":"自治的；自主的","example":"The adjective adds a Latin adjective ending.","exampleCN":"这个形容词加了拉丁形容词词尾。"},{"word":"-ous","structure":"Latin adjective ending","meaning":"having the quality of","meaningCN":"具有……性质","example":"It forms the adjective from the Greek noun stem.","exampleCN":"它由希腊名词词干构成形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb of manner.","exampleCN":"它构成方式副词。"},{"word":"auto-","structure":"English prefix from Greek","meaning":"self, by oneself","meaningCN":"自我；自行","example":"It appears in automatic and autobiography.","exampleCN":"它出现在「自动」与「自传」等词里。"},{"word":"-ist","structure":"Greek noun ending through Latin","meaning":"a supporter of","meaningCN":"主张……的人","example":"It forms the word for an advocate of autonomy.","exampleCN":"它构成指自治主张者的名词。"}],"latinEntries":[{"word":"autonomia","structure":"Medieval Latin from Greek","meaning":"self-government","meaningCN":"自治"},{"word":"autonomus","structure":"Medieval Latin from Greek","meaning":"self-governing","meaningCN":"自治的"}],"derivatives":[{"word":"autonomous","pos":"adj.","zh":"由希腊词干加形容词词尾构成，义为「自治的；自主的」"},{"word":"autonomously","pos":"adv.","zh":"加副词词尾构成，义为「自主地」"},{"word":"autonomist","pos":"n.","zh":"加表示人的词尾构成，义为「自治主张者」"},{"word":"heteronomy","pos":"n.","zh":"加表示「他者」的前缀构成，义为「他律」"},{"word":"autonomy","pos":"n.","zh":"由希腊名词经法语进入英语，义为「自治；自主」"}]}},{"word":"coherence","ipa_uk":"/kəʊˈhɪərəns/","ipa_us":"/koʊˈhɪrəns/","definition_zh":"连贯性；一致性；连贯；相干性","definition_en":"the quality of parts sticking together into a consistent whole, or of waves keeping a fixed phase relation","core_image":"几页散开的稿纸被一根线串在一起，每段都接住上一段留下的问题","scene":"编辑把散开的稿页按顺序串起，每段都接住上一段留下的问题。Readers praised the coherence of the argument.","sceneCN":"这里指论证前后连成一体（第 1 个义项：逻辑一致性）；句意为读者称赞这篇论证的连贯。图中可辨识物件：稿纸、装订线、红笔、段落标记。","pos":[{"tag":"n.","zh":"名词：连贯性；一致性；相干性（不可数）"}],"collocations":[{"phrase":"coherence of the argument","zh":"论证的连贯"},{"phrase":"logical coherence","zh":"逻辑一致性"},{"phrase":"textual coherence","zh":"语篇连贯"},{"phrase":"coherence in policy","zh":"政策的一致性"},{"phrase":"optical coherence","zh":"光学相干性"},{"phrase":"lack of coherence","zh":"缺乏连贯"}],"forms":[{"label":"单数","form":"coherence"},{"label":"形容词","form":"coherent（连贯的；一致的）"},{"label":"副词","form":"coherently（连贯地）"},{"label":"反义名词","form":"incoherence（不连贯；语无伦次）"},{"label":"反义形容词","form":"incoherent（不连贯的）"},{"label":"同根名词","form":"cohesion（黏合；凝聚力）"}],"derivatives":[{"word":"coherent","pos":"adj.","zh":"由同一拉丁词根加形容词词尾构成，义为「连贯的；一致的」"},{"word":"coherently","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「连贯地」"},{"word":"incoherent","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「不连贯的」"},{"word":"incoherence","pos":"n.","zh":"由该否定形容词加名词词尾构成，义为「不连贯」"},{"word":"cohesion","pos":"n.","zh":"由同一词根的另一派生形式构成，义为「黏合；凝聚力」"}],"senses":[{"no":"01","title":"Logical consistency","titleCN":"逻辑一致性","definition":"the quality of an argument whose parts support one another without contradiction","definitionCN":"论证各部分互相支撑、不相矛盾的性质","example":"Reviewers questioned the coherence of the argument in the final chapter.","exampleCN":"审稿人质疑最后一章论证的连贯。","why":"The Latin verb means to stick together, so a coherent argument is one whose parts do not come apart.","whyCN":"拉丁动词意为「黏在一起」，因此连贯的论证就是各部分不会散开。"},{"no":"02","title":"For textual unity","titleCN":"语篇的连贯","definition":"the quality of a text whose sentences and paragraphs hold together as one piece","definitionCN":"文章句子与段落合成一体的性质","example":"Clear signposting improves the coherence of a long report.","exampleCN":"清晰的衔接语能改善长篇报告的连贯。","why":"Writing needs links that make the reader feel one hand behind many sentences.","whyCN":"写作需要连接手段，让读者感到许多句子背后是同一只手。"},{"no":"03","title":"Coherence of a group","titleCN":"群体的凝聚","definition":"the quality of a group acting or thinking as a united body","definitionCN":"群体作为一个整体行动或思考的性质","example":"The coalition lost coherence after the budget vote.","exampleCN":"预算表决之后，这个联盟失去了凝聚力。","why":"A group whose members stick together is described with the same physical image.","whyCN":"成员黏在一起的群体，用的还是同一个物理意象。"},{"no":"04","title":"Consistency of a plan or policy","titleCN":"计划或政策的一致","definition":"the quality of measures fitting together without working against each other","definitionCN":"各项措施彼此配合、不相冲突的性质","example":"The audit found little coherence between transport and housing policy.","exampleCN":"审计发现交通与住房政策之间缺乏一致。","why":"Measures that pull in different directions cannot stick together, so policy coherence is judged by mutual fit.","whyCN":"相互拉扯的措施无法黏在一起，因此政策的一致要看彼此是否合得上。"},{"no":"05","title":"Coherence of waves and light","titleCN":"波与光的相干性","definition":"the fixed phase relation that lets waves interfere in a stable pattern","definitionCN":"使波能形成稳定干涉图样的固定相位关系","example":"Lasers produce light with high coherence over long distances.","exampleCN":"激光在长距离上产生高相干性的光。","why":"Physics kept the original image: waves that stay in step are literally sticking together.","whyCN":"物理学保留原意象：步伐一致的波，字面上就是黏在一起。"},{"no":"06","title":"Discourse coherence in linguistics","titleCN":"语言学中的话语连贯","definition":"the property that makes a stretch of discourse interpretable as a single message","definitionCN":"使一段话语可被理解为单一信息的性质","example":"The study compares coherence across spoken and written registers.","exampleCN":"这项研究比较口语与书面语域中的连贯。","why":"Linguistics separates the surface ties from the deeper sense of one message.","whyCN":"语言学把表层的连接手段与深层的一条信息区分开。"},{"no":"07","title":"Optical coherence","titleCN":"光学相干","definition":"the property of light that allows stable interference fringes to form","definitionCN":"光能形成稳定干涉条纹的性质","example":"The instrument measures coherence between two reflected beams.","exampleCN":"这台仪器测量两束反射光之间的相干性。","why":"Two beams are coherent when their crests and troughs keep a fixed relationship.","whyCN":"两束光的波峰与波谷保持固定关系时，就是相干的。"},{"no":"08","title":"Narrative coherence","titleCN":"叙事的连贯","definition":"the quality of a story whose events and motives fit into one believable line","definitionCN":"故事的事件与动机串成一条可信线索的性质","example":"The memoir achieves narrative coherence by returning to one image.","exampleCN":"这部回忆录靠反复回到同一个意象获得叙事连贯。","why":"A story sticks together when each event can be read as following from the last.","whyCN":"当每个事件都能读作由上一个事件引出时，故事就黏住了。"},{"no":"09","title":"Coherence of a legal system","titleCN":"法律体系的一致","definition":"the quality of rules in a system fitting together without contradiction","definitionCN":"体系中各项规则彼此配合、不相矛盾的性质","example":"Judges appealed to the coherence of the statute as a whole.","exampleCN":"法官援引整部法规的一致性。","why":"Legal theory asks whether rules can be read as one consistent scheme.","whyCN":"法学理论追问各项规则能否被读成一个前后一致的方案。"}],"etymology":{"intro":{"en":"Coherence comes from Latin cohaerere, to stick together, built from co-, together, and haerere, to stick or cling. The Latin noun cohaerentia passed through French into English in the sixteenth century, first for physical joining and later for logic.","cn":"这个词来自拉丁语 cohaerere「黏在一起」，由表示「共同」的前缀与表示「黏附」的词根构成。拉丁名词经法语在十六世纪进入英语，先指物理上的接合，后来才指逻辑上的连贯。"},"items":[{"era":"LATIN HAERERE","en":"The verb meant to stick, cling or be fixed, and it also stands behind adhere and hesitate.","cn":"这个动词意为黏附、贴住、固定，也是「附着」与「犹豫」二词的源头。"},{"era":"LATIN CO-","en":"The prefix meant together or with, and it turns sticking into sticking together.","cn":"这个前缀意为共同、一起，把「黏」变成「黏在一起」。"},{"era":"LATIN COHAERERE","en":"The compound meant to hold together as one mass, used of bodies and later of ideas.","cn":"这个复合动词意为合成一体地连着，先用于物体，后用于观念。"},{"era":"LATIN COHAERENTIA","en":"The noun named the state of holding together.","cn":"这个名词指「连成一体」的状态。"},{"era":"FRENCH AND ENGLISH, 16TH CENTURY","en":"The noun entered English through French in the sixteenth century, first for physical connection.","cn":"这个名词经法语在十六世纪进入英语，最初指物理连接。"},{"era":"THE LOGICAL TURN","en":"Philosophy extended it to arguments and texts, where parts must hold together in meaning.","cn":"哲学把它扩展到论证与文本，要求各部分在意义上连成一体。"}]},"similar":{"note":{"en":"The first group shares the Latin root or its negative; the second group names similar unities.","cn":"第一组共享拉丁词根或其否定形式；第二组是类似的统一性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"coherent","ipa":"/kəʊˈhɪərənt/","tag":"same root","definition":"The adjective for sticking together logically.","definitionCN":"形容词，意为连贯的、一致的。"},{"word":"coherently","ipa":"/kəʊˈhɪərəntli/","tag":"same root","definition":"In a connected and consistent way.","definitionCN":"指以连贯一致的方式。"},{"word":"incoherent","ipa":"/ˌɪnkəʊˈhɪərənt/","tag":"same root","definition":"Not holding together; confused in expression.","definitionCN":"指不连贯、表述混乱的。"},{"word":"incoherence","ipa":"/ˌɪnkəʊˈhɪərəns/","tag":"same root","definition":"The noun for a failure to hold together.","definitionCN":"指无法连成一体的状态。"},{"word":"cohesion","ipa":"/kəʊˈhiːʒn/","tag":"related root","definition":"The act of sticking together, especially of groups or text surfaces.","definitionCN":"指黏合，多用于群体或文本表层。"}]},{"heading":"NEAR MEANING","entries":[{"word":"consistency","ipa":"/kənˈsɪstənsi/","tag":"near meaning","definition":"The quality of not contradicting itself over time.","definitionCN":"指前后不自相矛盾的性质。"},{"word":"unity","ipa":"/juːˈnɪti/","tag":"near meaning","definition":"The state of being one whole.","definitionCN":"指成为一体的状态。"},{"word":"continuity","ipa":"/ˌkɒntɪˈnjuːəti/","tag":"near meaning","definition":"Unbroken connection from one part to the next.","definitionCN":"指各部分之间不断裂的连接。"},{"word":"logic","ipa":"/ˈlɒdʒɪk/","tag":"near meaning","definition":"The structure of valid reasoning itself.","definitionCN":"指有效推理的结构本身。"},{"word":"cohesion","ipa":"/kəʊˈhiːʒn/","tag":"near meaning","definition":"Surface linking between sentences, distinct from deeper coherence.","definitionCN":"指句子表层的连接，与更深层的连贯有别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations begin with the literal image of sticking together, then follow it into writing, groups, policy and light.","cn":"正常联想从「黏在一起」的字面意象出发，再走到文章、群体、政策与光。"},"normal":[{"en":"The root verb means to stick, so coherent parts do not fall apart under pressure.","cn":"词根意为黏附，所以连贯的各部分受力也不会散开。"},{"en":"Signposting words are the visible glue of a long report.","cn":"衔接词是长篇报告上看得见的胶水。"},{"en":"A coalition that sticks together after a lost vote has coherence in the group sense.","cn":"表决失利后仍黏在一起的联盟，具备群体意义上的凝聚。"},{"en":"Lasers are the clearest physical case: their waves stay in step, so they are coherent.","cn":"激光是最清楚的物理例子：波保持同步，所以相干。"},{"en":"Legal theory asks whether separate rules can be read as one scheme.","cn":"法学理论追问分开的规则能否被读成一个方案。"}],"abstract":[{"en":"Coherence is what makes many sentences feel like one voice in the room.","cn":"连贯让许多句子听起来像房间里同一个人的声音。"},{"en":"Two ideas can both be true and still lack coherence, because truth is not gluing.","cn":"两个想法可以都真却仍不连贯，因为真并不等于黏合。"},{"en":"Every whole is held together by something invisible, and this word names that hold.","cn":"每个整体都靠某种看不见的东西连住，这个词给那份「连」命名。"}]},"examples":[{"en":"The editor rewrote two paragraphs to restore coherence.","cn":"编辑改写了两段，以恢复连贯。"},{"en":"Coherence between the two policies was missing from the start.","cn":"这两项政策从一开始就缺乏一致。"},{"en":"The laboratory measures coherence in a beam of light.","cn":"实验室测量一束光的相干性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「扣希尔伦斯」——许多段被同一根线扣在一起，就是「连贯、一致」：连贯性、一致性","word":"coherence"},"root":"这个词来自拉丁语 cohaerere「黏在一起」，由表示「共同」的前缀与 haerere「黏附」构成；拉丁名词经法语在十六世纪进入英语，先指物理连接，后指逻辑与语篇的连贯。","sensesIntro":{"en":"Nine senses hold the same image of sticking together, applied to argument, text, group, policy, light, discourse, optics, story and law.","cn":"九个义项共用一个「黏在一起」的意象，分别用在论证、文本、群体、政策、光、话语、光学、故事与法律上。"},"semanticMap":{"core":{"en":"CORE IMAGE: loose sheets threaded by one cord, each paragraph picking up the question the last left open.","cn":"核心意象：散页被一根线串起，每段接住上一段留下的问题。"},"chain":["STICKING","STICKING TOGETHER","JOINED ARGUMENT","JOINED TEXT","JOINED POLICY","WAVES IN STEP"],"branches":[{"senses":"01 · 09","en":"THE JOINED ARGUMENT AND THE JOINED LAW: claims and rules must not contradict each other.","cn":"连起的论证与连起的法律：主张与规则不得彼此矛盾。"},{"senses":"02 · 06","en":"THE JOINED TEXT AND DISCOURSE: sentences and utterances read as one message.","cn":"连起的文本与话语：句子与话语被读成一条信息。"},{"senses":"03 · 04","en":"THE JOINED GROUP AND POLICY: members and measures hold as one body.","cn":"连起的群体与政策：成员与措施合成一体。"},{"senses":"05 · 07","en":"THE WAVES IN STEP: a fixed phase relation makes stable interference possible.","cn":"同步的波：固定相位关系使稳定干涉成为可能。"},{"senses":"08","en":"THE JOINED STORY: events and motives form one believable line.","cn":"连起的故事：事件与动机构成一条可信线索。"}]},"affixes":{"intro":{"en":"The word is a Latin verb of sticking with a prefix of togetherness, and English added a noun ending.","cn":"这个词是表示「黏附」的拉丁动词加上表示「共同」的前缀，英语再加名词词尾。"},"latinIntro":{"en":"Latin supplies the verb of sticking, the prefix of togetherness, the compound verb and its noun.","cn":"拉丁语提供了表示黏附的动词、表示共同的前缀、复合动词及其名词。"},"items":[{"word":"haerere","structure":"Latin verb","meaning":"to stick, to cling","meaningCN":"黏附；贴住","example":"It also stands behind adhere and hesitate.","exampleCN":"它也是「附着」与「犹豫」二词的源头。"},{"word":"co-","structure":"Latin prefix","meaning":"together, with","meaningCN":"共同；一起","example":"It turns sticking into sticking together.","exampleCN":"它把「黏」变成「黏在一起」。"},{"word":"cohaerere","structure":"Latin verb","meaning":"to hold together","meaningCN":"连成一体","example":"The verb describes parts that do not separate.","exampleCN":"这个动词描述不会分开的各部分。"},{"word":"cohaerentia","structure":"Latin noun","meaning":"a holding together","meaningCN":"连成一体的状态","example":"The noun named the state before English borrowed it.","exampleCN":"这个名词在英语借入前已指该状态。"},{"word":"coherence","structure":"English noun","meaning":"the quality of holding together","meaningCN":"连贯性；一致性","example":"English extended it from bodies to arguments.","exampleCN":"英语把它从物体扩展到论证。"},{"word":"coherent","structure":"English adjective","meaning":"holding together","meaningCN":"连贯的；一致的","example":"The adjective adds a Latin adjective ending.","exampleCN":"这个形容词加了拉丁形容词词尾。"},{"word":"-ent","structure":"Latin adjective ending","meaning":"being in a state","meaningCN":"处于某种状态","example":"It marks the participle-like adjective.","exampleCN":"它标记类似分词的形容词。"},{"word":"-ence","structure":"Latin noun ending through French","meaning":"the quality or state","meaningCN":"性质或状态","example":"It forms the abstract noun.","exampleCN":"它构成抽象名词。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不","example":"It forms incoherent, falling apart.","exampleCN":"它构成表示「散开」的形容词。"},{"word":"cohesion","structure":"English noun","meaning":"sticking together","meaningCN":"黏合；凝聚力","example":"The sibling noun stresses the bond itself.","exampleCN":"同族名词更强调黏合本身。"}],"latinEntries":[{"word":"haerere","structure":"Latin verb","meaning":"to stick","meaningCN":"黏附"},{"word":"co-","structure":"Latin prefix","meaning":"together","meaningCN":"共同"},{"word":"cohaerere","structure":"Latin verb","meaning":"to hold together","meaningCN":"连成一体"},{"word":"cohaerentia","structure":"Latin noun","meaning":"a holding together","meaningCN":"连成一体"}],"derivatives":[{"word":"coherent","pos":"adj.","zh":"加形容词词尾构成，义为「连贯的」"},{"word":"coherently","pos":"adv.","zh":"加副词词尾构成，义为「连贯地」"},{"word":"incoherent","pos":"adj.","zh":"加否定前缀构成，义为「不连贯的」"},{"word":"incoherence","pos":"n.","zh":"加名词词尾构成，义为「不连贯」"},{"word":"cohesion","pos":"n.","zh":"由同一词根的另一派生构成，义为「黏合；凝聚力」"}]}},{"word":"coincidence","ipa_uk":"/kəʊˈɪnsɪdəns/","ipa_us":"/koʊˈɪnsɪdəns/","definition_zh":"巧合；同时发生；一致；重合","definition_en":"the chance occurrence of two events at the same time, or the exact agreement of two things","core_image":"两个陌生人在同一节车厢里掏出同一本绝版书，书页都停在同一个折角","scene":"地铁上两个陌生人掏出同一本旧书，翻开都停在同一页。By coincidence, they were reading the same rare edition.","sceneCN":"这里指两件不相干的事偶然同时发生（第 1 个义项：巧合）；句意为碰巧他们读着同一版稀见书。图中可辨识物件：车厢扶手、旧书、折角、票卡。","pos":[{"tag":"n.","zh":"名词：巧合；同时发生；一致；重合（可数）"}],"collocations":[{"phrase":"by coincidence","zh":"碰巧"},{"phrase":"pure coincidence","zh":"纯属巧合"},{"phrase":"a strange coincidence","zh":"奇怪的巧合"},{"phrase":"coincidence of interests","zh":"利益的一致"},{"phrase":"coincidence in time","zh":"时间上的同时发生"},{"phrase":"no coincidence","zh":"并非偶然"}],"forms":[{"label":"单数","form":"coincidence"},{"label":"复数","form":"coincidences（多起巧合）"},{"label":"形容词","form":"coincident（同时发生的；一致的）"},{"label":"形容词","form":"coincidental（偶然巧合的）"},{"label":"副词","form":"coincidentally（碰巧地）"},{"label":"动词同族","form":"coincide（同时发生；一致）"}],"derivatives":[{"word":"coincide","pos":"v.","zh":"同一词根的动词，义为「同时发生；位置重合；意见一致」"},{"word":"coincident","pos":"adj.","zh":"由该动词加形容词词尾构成，义为「同时发生的；一致的」"},{"word":"coincidental","pos":"adj.","zh":"由该词根加另一形容词词尾构成，义为「偶然巧合的」"},{"word":"coincidentally","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「碰巧地」"},{"word":"incidence","pos":"n.","zh":"由同一词根的另一前缀形式构成，义为「发生率；影响范围」"}],"senses":[{"no":"01","title":"Chance concurrence of events","titleCN":"两事偶然同时发生","definition":"the chance happening of two or more events at the same time, with no causal link","definitionCN":"两件或多件事在同一时间偶然发生，彼此没有因果联系","example":"By coincidence, both teams arrived on the same train.","exampleCN":"碰巧两队都坐了同一班火车到达。","why":"The Latin verb means to fall upon together, so two unrelated events land on one point of time.","whyCN":"拉丁动词意为「一起落到某处」，两件无关之事因此落在同一个时间点上。"},{"no":"02","title":"A remarkable or unlikely match","titleCN":"离奇而难得的巧合","definition":"a match of events that is striking because it is so unlikely","definitionCN":"因极不可能出现而引人注目的相符","example":"It was a remarkable coincidence that the two letters reached him on the same day.","exampleCN":"两封信同一天到他手里，这是个离奇的巧合。","why":"The word gains force when probability is low, which is why speakers call it strange or pure.","whyCN":"概率越低，这个词越有力量，所以人们会说「奇怪」或「纯属」。"},{"no":"03","title":"The adverbial by coincidence","titleCN":"副词性说法「碰巧」","definition":"used to introduce an event that happened without plan","definitionCN":"用来引出一件并非计划内发生的事","example":"By coincidence, she was in the building when the alarm rang.","exampleCN":"碰巧警报响时她就在楼里。","why":"The prepositional phrase turns the noun into a way of saying that no plan was involved.","whyCN":"这个介词短语把名词变成一种说明「并无计划」的方式。"},{"no":"04","title":"Exact agreement between two things","titleCN":"两物的完全一致","definition":"the state of two things matching exactly, as of interests or views","definitionCN":"两物完全相符的状态，如利益或看法一致","example":"The deal rested on a coincidence of interests between the two firms.","exampleCN":"这笔交易建立在两家企业利益一致之上。","why":"When two shapes land on each other, their outlines agree; the word borrows that image for interests.","whyCN":"两个形状彼此落在对方之上时轮廓吻合，这个词把这个意象借给利益。"},{"no":"05","title":"Geometric or physical coincidence","titleCN":"几何或物理上的重合","definition":"the state of two points, lines or objects occupying the same position","definitionCN":"两个点、线或物体占据同一位置的状态","example":"The surveyor checked the coincidence of the two boundary lines.","exampleCN":"测量员核对了两条边界线是否重合。","why":"Geometry uses the word literally: two things fall on one place.","whyCN":"几何学用的是字面义：两件东西落在同一个位置。"},{"no":"06","title":"Simultaneity in time","titleCN":"时间上的同时","definition":"the occurrence of two events at the same moment","definitionCN":"两件事在同一时刻发生","example":"The coincidence in time of the two earthquakes puzzled researchers.","exampleCN":"两次地震在时间上同时发生，让研究者困惑。","why":"Time is the first axis on which independent events can fall together.","whyCN":"时间是互不相关的事件能够落在一起的第一根轴。"},{"no":"07","title":"A chance match found in data","titleCN":"数据中偶然相符","definition":"a matching of records or values that arises by chance rather than by design","definitionCN":"记录或数值的相符出于偶然而非设计","example":"The software flagged a coincidence between two unrelated accounts.","exampleCN":"软件标出了两个互不相关账户之间的偶然相符。","why":"Large datasets produce many matches, and the word reminds the analyst that match is not cause.","whyCN":"大数据会产生大量相符，这个词提醒分析者相符不等于因果。"},{"no":"08","title":"Coincidence rather than causation","titleCN":"相符而非因果","definition":"used in research logic to name a match that cannot be explained causally","definitionCN":"在研究逻辑中指无法用因果解释的相符","example":"The panel warned against reading a coincidence as evidence of effect.","exampleCN":"专家组警告不要把一次巧合读成有效应的证据。","why":"A match without a mechanism is still a match, so research logic names the word to withhold causal weight.","whyCN":"没有机制的相符仍是相符，因此研究逻辑用这个词来扣住因果分量。"},{"no":"09","title":"The exclamation what a coincidence","titleCN":"感叹语「真巧」","definition":"a conversational exclamation on discovering an unexpected match","definitionCN":"发现意外相符时的口语感叹","example":"What a coincidence, we chose the same title!","exampleCN":"真巧，我们选的题目一样！","why":"The same noun serves delight as well as analysis, depending on whether anyone needs an explanation.","whyCN":"同一个名词既能表达惊喜，也能用于分析，区别在于是否有人需要解释。"}],"etymology":{"intro":{"en":"Coincidence comes from Latin coincidere, to fall upon together, built from co-, together, and incidere, to fall into, from in-, into, and cadere, to fall. The noun entered English through French in the seventeenth century.","cn":"这个词来自拉丁语 coincidere「一起落到某处」，由表示「共同」的前缀与表示「落入」的动词构成，后者又由表示「向内」的前缀与表示「落下」的词根构成。名词经法语在十七世纪进入英语。"},"items":[{"era":"LATIN CADERE","en":"The verb meant to fall, and it also stands behind accident, incident and decay.","cn":"这个动词意为落下，也是「事故」「事件」与「衰败」等词的源头。"},{"era":"LATIN IN-","en":"The prefix meant into or upon, and it gives the falling a direction.","cn":"这个前缀意为向内、落在其上，给「落下」一个方向。"},{"era":"LATIN INCIDERE","en":"The compound meant to fall into or fall upon, often used of events befalling someone.","cn":"这个复合动词意为落入、落到，常用于降临到某人身上的事件。"},{"era":"LATIN COINCIDERE","en":"With the prefix of togetherness it meant to fall upon the same point at once.","cn":"加上表示共同的前缀后，意为同时落到同一点上。"},{"era":"LATIN COINCIDENTIA","en":"The noun named the falling together of two things, in space or in time.","cn":"这个名词指两物在空间或时间上落到一起。"},{"era":"ENGLISH NOUN, 17TH CENTURY","en":"English borrowed the noun through French, first for events in time and later for matches of every kind; the exact first date is uncertain.","cn":"英语经法语借入这个名词，先指时间上同时发生，后指各种相符；确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group shares the root or the suffix; the second group names neighbouring ideas of chance and match.","cn":"第一组共享词根或词尾；第二组是相邻的偶然与相符概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"coincide","ipa":"/ˌkəʊɪnˈsaɪd/","tag":"same root","definition":"The verb for occurring together or agreeing exactly.","definitionCN":"动词，指同时发生或完全一致。"},{"word":"coincident","ipa":"/kəʊˈɪnsɪdənt/","tag":"same root","definition":"The adjective for things that fall together.","definitionCN":"形容词，指同时发生或重合的。"},{"word":"coincidental","ipa":"/kəʊˌɪnsɪˈdentl/","tag":"same root","definition":"The adjective stressing that a match was by chance.","definitionCN":"形容词，强调相符出于偶然。"},{"word":"coincidentally","ipa":"/kəʊˌɪnsɪˈdentli/","tag":"same root","definition":"The adverb meaning by chance.","definitionCN":"副词，意为碰巧。"},{"word":"incidence","ipa":"/ˈɪnsɪdəns/","tag":"related root","definition":"The rate at which something occurs, from the same verb of falling upon.","definitionCN":"指某事的出现率，出自同一个「落到」动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chance","ipa":"/tʃɑːns/","tag":"near meaning","definition":"The general force that produces unexpected matches.","definitionCN":"指产生意外相符的一般力量。"},{"word":"accident","ipa":"/ˈæksɪdənt/","tag":"near meaning","definition":"An event that happens without plan, often with harm.","definitionCN":"指无计划发生的事，常带损害。"},{"word":"concurrence","ipa":"/kənˈkʌrəns/","tag":"near meaning","definition":"The happening of events at the same time.","definitionCN":"指事件同时发生。"},{"word":"simultaneity","ipa":"/ˌsɪmltəˈneɪəti/","tag":"near meaning","definition":"The quality of occurring at the same moment.","definitionCN":"指同一时刻发生的性质。"},{"word":"correlation","ipa":"/ˌkɒrəˈleɪʃn/","tag":"near meaning","definition":"A statistical relation between variables, not a causal claim.","definitionCN":"指变量之间的统计关系，并不主张因果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the literal image of two things falling on one spot, then follow it through time, geometry and data.","cn":"正常联想使用「两物落到同一点」的字面意象，再走到时间、几何与数据。"},"normal":[{"en":"The Latin verb means to fall, so a coincidence is two events landing on the same spot of time.","cn":"拉丁动词意为落下，所以巧合就是两件事落在同一个时间点上。"},{"en":"By coincidence is the everyday phrase for something that no one arranged.","cn":"「碰巧」是日常说法，指没人安排却发生了。"},{"en":"Two boundary lines that lie on each other are coincident in the geometric sense.","cn":"两条重合的边界线，是几何意义上的重合。"},{"en":"A coincidence of interests means two parties want the same thing, which is agreement, not chance.","cn":"「利益一致」指两方想要同一样东西，这是相符而非偶然。"},{"en":"In research, calling a match a coincidence is a warning against reading it as cause.","cn":"研究中把相符称为巧合，是在警告不要把它当成因果。"}],"abstract":[{"en":"Chance is what remains when every plan has been subtracted, and the word measures that remainder.","cn":"把一切计划减掉之后剩下的就是偶然，这个词衡量那份剩余。"},{"en":"A coincidence is a bridge between two stories that never met.","cn":"巧合是两条从未相交的故事线之间的一座桥。"},{"en":"The rarer the match, the louder the word sounds in the ear.","cn":"相符越是罕见，这个词在耳朵里响得越亮。"}]},"examples":[{"en":"By coincidence, the two researchers submitted the same proposal.","cn":"碰巧，两位研究者提交了同一份申请。"},{"en":"The similarity between the two paintings is a coincidence, not a copy.","cn":"两幅画的相似是巧合，而非临摹。"},{"en":"The audit found a coincidence between the dates of the two payments.","cn":"审计发现两笔付款的日期恰好相同。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「扣因西登斯」——两件事恰好落在同一个点上，就是「巧合」：巧合、同时发生","word":"coincidence"},"root":"来自拉丁语 coincidere「一起落到某处」，由 co-「共同」与 incidere「落入」构成，后者又由 in-「向内」与 cadere「落下」构成；名词经法语在十七世纪进入英语，确切首见年代不确定。","sensesIntro":{"en":"Nine senses follow one image of falling together, through chance, remarkable matches, geometry, time, data and everyday speech.","cn":"九个义项沿着「一起落下」这一个意象，穿过偶然、离奇相符、几何、时间、数据与日常口语。"},"semanticMap":{"core":{"en":"CORE IMAGE: two strangers on one carriage pulling out the same rare book, both pages folded at the same corner.","cn":"核心意象：同一节车厢里两个陌生人掏出同一本旧书，书页都在同一个折角。"},"chain":["FALLING","FALLING TOGETHER","SAME MOMENT","SAME POINT","SAME INTEREST","SAME RECORD"],"branches":[{"senses":"01 · 03","en":"THE CHANCE MEETING: two unplanned events share a moment, often introduced by by coincidence.","cn":"偶然相遇：两件无计划的事共用一个时刻，常用「碰巧」引出。"},{"senses":"02","en":"THE REMARKABLE MATCH: the word grows louder as the probability falls.","cn":"离奇的相符：概率越低，这个词越响。"},{"senses":"04 · 05","en":"THE EXACT AGREEMENT: interests and outlines land on each other.","cn":"完全的一致：利益与轮廓彼此落在对方之上。"},{"senses":"06 · 07","en":"THE SHARED TIME AND DATA: simultaneity, and matches found in records.","cn":"共有的时间与数据：同时发生，以及记录中的相符。"},{"senses":"08 · 09","en":"THE WARNING AND THE EXCLAMATION: a match is not a cause, though it may be a delight.","cn":"警告与感叹：相符不是因果，却可能令人惊喜。"}]},"affixes":{"intro":{"en":"The word is built on a Latin verb of falling, with a prefix that makes the fall shared.","cn":"这个词建在表示「落下」的拉丁动词上，并加了一个使「落」变成「共落」的前缀。"},"latinIntro":{"en":"Latin supplies the verb of falling, its prefixes, the compound verb and the noun of falling together.","cn":"拉丁语提供了表示落下的动词、其前缀、复合动词与表示「共落」的名词。"},"items":[{"word":"cadere","structure":"Latin verb","meaning":"to fall","meaningCN":"落下","example":"It also stands behind accident and incident.","exampleCN":"它也是「事故」与「事件」的源头。"},{"word":"in-","structure":"Latin prefix","meaning":"into, upon","meaningCN":"向内；落在其上","example":"It gives the fall a direction.","exampleCN":"它给「落下」一个方向。"},{"word":"incidere","structure":"Latin verb","meaning":"to fall into or upon","meaningCN":"落入；落到","example":"The verb often describes events that befall people.","exampleCN":"这个动词常描述降临于人身上的事。"},{"word":"co-","structure":"Latin prefix","meaning":"together","meaningCN":"共同","example":"It makes two falls land as one.","exampleCN":"它让两次「落」变成一次共落。"},{"word":"coincidere","structure":"Latin verb","meaning":"to fall upon together","meaningCN":"一起落到某处","example":"The verb is the direct source of the English word.","exampleCN":"这个动词是英语词的直接源头。"},{"word":"coincidentia","structure":"Latin noun","meaning":"a falling together","meaningCN":"共落；重合","example":"The noun named the state in space or time.","exampleCN":"这个名词指空间或时间上的共落。"},{"word":"coincide","structure":"English verb","meaning":"to occur together","meaningCN":"同时发生；重合","example":"The verb keeps the physical image.","exampleCN":"这个动词保留物理意象。"},{"word":"-ence","structure":"Latin noun ending through French","meaning":"the quality or state","meaningCN":"性质或状态","example":"It forms the abstract noun.","exampleCN":"它构成抽象名词。"},{"word":"-al","structure":"Latin adjective ending","meaning":"relating to","meaningCN":"与……有关","example":"It forms coincidental, marked as by chance.","exampleCN":"它构成表示「偶然巧合」的形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the everyday adverb.","exampleCN":"它构成日常副词。"}],"latinEntries":[{"word":"cadere","structure":"Latin verb","meaning":"to fall","meaningCN":"落下"},{"word":"incidere","structure":"Latin verb","meaning":"to fall into","meaningCN":"落入"},{"word":"coincidere","structure":"Latin verb","meaning":"to fall together","meaningCN":"一起落下"},{"word":"coincidentia","structure":"Latin noun","meaning":"coincidence","meaningCN":"共落；巧合"}],"derivatives":[{"word":"coincide","pos":"v.","zh":"同一词根的动词，义为「同时发生；重合」"},{"word":"coincident","pos":"adj.","zh":"加形容词词尾构成，义为「同时发生的」"},{"word":"coincidental","pos":"adj.","zh":"加另一形容词词尾构成，义为「偶然巧合的」"},{"word":"coincidentally","pos":"adv.","zh":"加副词词尾构成，义为「碰巧地」"},{"word":"incidence","pos":"n.","zh":"由另一前缀形式构成，义为「发生率」"}]}},{"word":"convergence","ipa_uk":"/kənˈvɜːdʒəns/","ipa_us":"/kənˈvɜːrdʒəns/","definition_zh":"汇聚；趋同；收敛；会聚","definition_en":"the process of moving towards the same point, or of becoming more alike","core_image":"两条山脊上的小路越走越近，最后在山口汇成一条","scene":"两条山路从不同方向爬上山脊，越靠近山顶越窄，最后在山口合成一条。The two trails show a clear convergence at the ridge.","sceneCN":"这里指两条路线向同一点收拢（第 1 个义项：汇聚）；句意为两条小径在山脊明显汇聚。图中可辨识物件：山脊、两条小路、路口标桩、路牌。","pos":[{"tag":"n.","zh":"名词：汇聚；趋同；收敛；会聚（不可数，指具体汇合处时可数）"}],"collocations":[{"phrase":"convergence of interests","zh":"利益趋同"},{"phrase":"technological convergence","zh":"技术融合"},{"phrase":"convergence of the series","zh":"级数的收敛"},{"phrase":"economic convergence","zh":"经济趋同"},{"phrase":"point of convergence","zh":"汇聚点"},{"phrase":"convergent evolution","zh":"趋同演化"}],"forms":[{"label":"单数","form":"convergence"},{"label":"复数（具体汇合处）","form":"convergences"},{"label":"动词","form":"converge（汇聚；趋同；收敛）"},{"label":"形容词","form":"convergent（汇聚的；趋同的）"},{"label":"副词","form":"convergently（趋同地）"},{"label":"反义名词","form":"divergence（分叉；分歧）"}],"derivatives":[{"word":"converge","pos":"v.","zh":"同一词根的动词，义为「汇聚；趋同；收敛」"},{"word":"convergent","pos":"adj.","zh":"由该动词加形容词词尾构成，义为「汇聚的；趋同的」"},{"word":"convergently","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「以趋同方式」"},{"word":"divergence","pos":"n.","zh":"由表示「分开」的前缀加同一词根构成，义为「分叉；分歧」"},{"word":"divergent","pos":"adj.","zh":"由该词根加「分开」前缀与形容词词尾构成，义为「分叉的；有分歧的」"}],"senses":[{"no":"01","title":"Lines moving towards one point","titleCN":"线条向同一点收拢","definition":"the coming together of lines, paths or streams towards a single point","definitionCN":"线条、路径或水流向单一一点靠拢","example":"The two trails show a clear convergence at the ridge.","exampleCN":"两条小径在山脊明显汇聚。","why":"The Latin verb means to bend together, so two lines bend until they meet.","whyCN":"拉丁动词意为「一起弯」，两条线因此弯到相遇。"},{"no":"02","title":"People or interests coming together","titleCN":"人或利益走到一起","definition":"the process by which separate groups or interests move towards a shared position","definitionCN":"分开的群体或利益向共同立场靠拢的过程","example":"The convergence of the two campaigns surprised observers.","exampleCN":"两场运动的趋同让观察者意外。","why":"Social convergence borrows the geometry: separate paths end at one point of agreement.","whyCN":"社会领域的趋同借了几何：分开的路径最后落在同一个共识点。"},{"no":"03","title":"Technological and media convergence","titleCN":"技术与媒介融合","definition":"the merging of previously separate technologies, industries or media into one platform","definitionCN":"原先分开的技术、产业或媒介合并到同一平台","example":"Technological convergence put a camera, a phone and a library in one device.","exampleCN":"技术融合把相机、电话与书库放进同一台设备。","why":"When separate streams share one channel, the image of water meeting is exact.","whyCN":"当分开的溪流共用一条水道，水流相会的意象正好贴切。"},{"no":"04","title":"Evolutionary convergence","titleCN":"趋同演化","definition":"the independent development of similar traits in unrelated species","definitionCN":"不相关物种独立演化出相似特征","example":"Convergence explains why unrelated animals both developed wings.","exampleCN":"趋同演化解释了不相关的动物为何都长出翅膀。","why":"Unrelated lineages facing the same problem take the same shape, which is convergence without shared ancestry.","whyCN":"不相关的谱系面对同一难题会长出同一形状，这就是没有共同祖先的趋同。"},{"no":"05","title":"Economic convergence","titleCN":"经济趋同","definition":"the narrowing of income or growth gaps between regions or countries","definitionCN":"地区或国家之间收入或增长差距缩小","example":"The bloc reported economic convergence over the past decade.","exampleCN":"该联盟报告过去十年出现经济趋同。","why":"Economies that grow at similar rates draw level, as two paths arriving at one height.","whyCN":"增长速度相近的经济体会拉平，就像两条路径到达同一高度。"},{"no":"06","title":"Mathematical convergence","titleCN":"数学收敛","definition":"the property of a sequence or series approaching a fixed limit","definitionCN":"数列或级数趋近某个固定极限的性质","example":"The proof establishes the convergence of the series.","exampleCN":"这个证明确立了该级数的收敛。","why":"Mathematics turned the everyday image of approach into a precise limit.","whyCN":"数学把「靠近」的日常意象变成了精确的极限。"},{"no":"07","title":"Convergence of opinions","titleCN":"意见趋同","definition":"the process by which views move closer after discussion","definitionCN":"讨论之后看法逐渐靠近的过程","example":"Repeated deliberation produced a convergence of expert opinion.","exampleCN":"反复讨论使专家意见趋于一致。","why":"Agreement is treated as a meeting point that independent views reach from different sides.","whyCN":"共识被看作独立意见从不同方向到达的汇合点。"},{"no":"08","title":"Convergence in meteorology","titleCN":"气象学中的辐合","definition":"the meeting of air flows that forces air upward and can produce weather","definitionCN":"气流的汇合，把空气抬升并可能产生天气现象","example":"Forecasters watched the convergence of the two air masses.","exampleCN":"预报员关注两股气团的辐合。","why":"Air that meets cannot go down, so it rises, cools and forms cloud, which is why the word matters in forecasting.","whyCN":"相遇的空气无法下沉，只能抬升、冷却并成云，这个词因此在预报里很重要。"},{"no":"09","title":"Convergence of the eyes","titleCN":"双眼会聚","definition":"the inward turning of the eyes to focus on a near object","definitionCN":"双眼向内转动以聚焦近处物体","example":"Reading at close range requires convergence of the eyes.","exampleCN":"近距离阅读需要双眼会聚。","why":"Both eyes must point at one near point, which is the same geometry applied to vision.","whyCN":"双眼必须对准同一个近点，这是同一套几何用在视觉上。"}],"etymology":{"intro":{"en":"Convergence comes from Latin convergere, to bend together, built from con-, together, and vergere, to bend or turn. The noun passed through French into English in the eighteenth century, first for lines and later for ideas and economies.","cn":"这个词来自拉丁语 convergere「一起弯曲」，由表示「共同」的前缀与表示「弯曲、转向」的词根构成。名词经法语在十八世纪进入英语，先用于线，后用于观念与经济。"},"items":[{"era":"LATIN VERGERE","en":"The verb meant to bend, turn or incline, and it also stands behind diverge and verge.","cn":"这个动词意为弯曲、转向、倾斜，也是「分叉」与「边缘」等词的源头。"},{"era":"LATIN CON-","en":"The prefix meant together, and it makes two inclinations meet.","cn":"这个前缀意为共同，使两个倾斜方向相遇。"},{"era":"LATIN CONVERGERE","en":"The compound meant to incline towards one point or to come together.","cn":"这个复合动词意为朝一点倾斜或合到一起。"},{"era":"LATIN CONVERGENTIA","en":"The noun named the state of tending towards one point.","cn":"这个名词指朝一点靠拢的状态。"},{"era":"FRENCH AND ENGLISH, 18TH CENTURY","en":"French carried the word into English, first in geometry and optics.","cn":"法语把这个词带进英语，最初用于几何与光学。"},{"era":"THE MODERN WIDENING","en":"Later usage extended it to opinions, economies, media and biology.","cn":"后来的用法把它扩展到意见、经济、媒介与生物学。"}]},"similar":{"note":{"en":"The first group shares the root or its opposite; the second group names other kinds of coming together.","cn":"第一组共享词根或其反义形式；第二组是其他「合到一起」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"converge","ipa":"/kənˈvɜːdʒ/","tag":"same root","definition":"The verb for moving towards one point.","definitionCN":"动词，指向一点靠拢。"},{"word":"convergent","ipa":"/kənˈvɜːdʒənt/","tag":"same root","definition":"The adjective describing things that meet.","definitionCN":"形容词，形容汇合之物。"},{"word":"convergently","ipa":"/kənˈvɜːdʒəntli/","tag":"same root","definition":"In a manner that moves towards a point.","definitionCN":"指以靠拢的方式。"},{"word":"divergence","ipa":"/daɪˈvɜːdʒəns/","tag":"opposite root","definition":"The noun for moving apart, the mirror image.","definitionCN":"指分开的名词，是镜像概念。"},{"word":"divergent","ipa":"/daɪˈvɜːdʒənt/","tag":"opposite root","definition":"The adjective for paths that spread apart.","definitionCN":"形容路径分开的形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"merging","ipa":"/ˈmɜːdʒɪŋ/","tag":"near meaning","definition":"The act of joining into one body.","definitionCN":"指合并为一的过程。"},{"word":"unification","ipa":"/ˌjuːnɪfɪˈkeɪʃn/","tag":"near meaning","definition":"The act of making separate parts into one.","definitionCN":"指把分开的部分合成一个。"},{"word":"alignment","ipa":"/əˈlaɪnmənt/","tag":"near meaning","definition":"Bringing things into a shared line or position.","definitionCN":"指把事物排到同一条线上。"},{"word":"approximation","ipa":"/əˌprɒksɪˈmeɪʃn/","tag":"near meaning","definition":"Movement towards a value without reaching it exactly.","definitionCN":"指向某值接近而未必达到。"},{"word":"narrowing","ipa":"/ˈnærəʊɪŋ/","tag":"near meaning","definition":"A gap becoming smaller over time.","definitionCN":"指差距随时间缩小。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the image of two lines bending towards each other, then apply it to ideas, markets and numbers.","cn":"正常联想使用两条线向彼此弯曲的意象，再把它用到观念、市场与数字上。"},"normal":[{"en":"The root verb means to bend, so two paths bend until they meet at the ridge.","cn":"词根意为弯曲，所以两条路径弯到在山脊相遇。"},{"en":"Technological convergence puts a camera and a library in the same device.","cn":"技术融合把相机和书库放进同一台设备。"},{"en":"Convergent evolution explains why unrelated animals both grew wings.","cn":"趋同演化解释不相关的动物为何都长出翅膀。"},{"en":"A convergent series in mathematics approaches a limit without necessarily reaching it.","cn":"数学中的收敛级数趋近极限，但未必到达。"},{"en":"Forecasters speak of the convergence of air masses, where rising air makes weather.","cn":"预报员说气团辐合，那里上升空气制造天气。"}],"abstract":[{"en":"Two paths that never touch still share a horizon, and the word names that horizon.","cn":"两条永不相交的路径仍共有一个地平线，这个词给那条地平线命名。"},{"en":"Agreement is not sameness: converging views keep their starting points.","cn":"趋同不等于同一：靠拢的看法仍各自保留出发点。"},{"en":"Every meeting point is also a place where differences become invisible.","cn":"每个汇合点也是差异变得看不见的地方。"}]},"examples":[{"en":"The convergence of the two rivers created a natural harbour.","cn":"两条河的汇合形成了一处天然港。"},{"en":"Economic convergence between the regions took twenty years.","cn":"两地区之间的经济趋同花了二十年。"},{"en":"The paper examines convergence in the fossil record.","cn":"这篇论文考察化石记录中的趋同现象。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康弗真斯」——两条路越走越近，最后收到一个点上，就是「汇聚、趋同」：汇聚、趋同、收敛","word":"convergence"},"root":"来自拉丁语 convergere「一起弯曲」，由 con-「共同」与 vergere「弯曲、转向」构成；名词经法语在十八世纪进入英语，先用于几何与光学，后扩展到意见、经济、媒介与生物。","sensesIntro":{"en":"Nine senses let separate lines, groups, technologies, species, economies, series, opinions, air flows and eyes move towards one point.","cn":"九个义项让分开的线、群体、技术、物种、经济体、级数、意见、气流与双眼向同一个点靠拢。"},"semanticMap":{"core":{"en":"CORE IMAGE: two trails climbing one ridge from opposite sides, narrowing until they meet at the pass.","cn":"核心意象：两条小径从两侧爬上山脊，越走越窄，最后在山口汇合。"},"chain":["BENDING","BENDING TOGETHER","ONE POINT","ONE MARKET","ONE LIMIT","ONE RESULT"],"branches":[{"senses":"01 · 08 · 09","en":"THE PHYSICAL MEETING: paths, air flows and eyes turn towards one point.","cn":"物理汇合：路径、气流与双眼都转向同一点。"},{"senses":"02 · 07","en":"THE SHARED POSITION: groups and opinions move towards agreement.","cn":"共享立场：群体与意见向共识靠拢。"},{"senses":"03","en":"THE SHARED PLATFORM: separate technologies merge into one device.","cn":"共享平台：分开的技术并入同一台设备。"},{"senses":"04","en":"THE SHARED TRAIT: unrelated species evolve similar forms.","cn":"共享特征：不相关物种演化出相似形态。"},{"senses":"05 · 06","en":"THE SHARED LEVEL AND LIMIT: economies draw level, series approach a limit.","cn":"共享水平与极限：经济体拉平，级数趋近极限。"}]},"affixes":{"intro":{"en":"The word is a Latin verb of bending with a prefix of togetherness, so its core is two slopes meeting.","cn":"这个词是表示弯曲的拉丁动词加上表示共同的前缀，核心就是两道斜坡相遇。"},"latinIntro":{"en":"Latin supplies the verb of bending, the prefix, the compound verb and the noun of tendency.","cn":"拉丁语提供了表示弯曲的动词、前缀、复合动词与表示趋向的名词。"},"items":[{"word":"vergere","structure":"Latin verb","meaning":"to bend, to turn","meaningCN":"弯曲；转向","example":"It also stands behind diverge.","exampleCN":"它也是「分叉」一词的源头。"},{"word":"con-","structure":"Latin prefix","meaning":"together","meaningCN":"共同","example":"It makes two bends meet.","exampleCN":"它让两道弯曲相遇。"},{"word":"convergere","structure":"Latin verb","meaning":"to bend together","meaningCN":"一起弯曲；汇聚","example":"The verb is the direct source of the English word.","exampleCN":"这个动词是英语词的直接源头。"},{"word":"convergentia","structure":"Latin noun","meaning":"a tending towards one point","meaningCN":"朝一点靠拢","example":"The noun named the tendency.","exampleCN":"这个名词指这种趋向。"},{"word":"converge","structure":"English verb","meaning":"to come together","meaningCN":"汇聚；趋同","example":"The verb keeps the image of bending lines.","exampleCN":"这个动词保留弯线的意象。"},{"word":"convergent","structure":"English adjective","meaning":"meeting at a point","meaningCN":"汇聚的；趋同的","example":"The adjective adds a Latin ending.","exampleCN":"这个形容词加了拉丁词尾。"},{"word":"-ence","structure":"Latin noun ending through French","meaning":"the quality or state","meaningCN":"性质或状态","example":"It forms the abstract noun.","exampleCN":"它构成抽象名词。"},{"word":"-ent","structure":"Latin adjective ending","meaning":"being in a state","meaningCN":"处于某状态","example":"It marks the participle-like adjective.","exampleCN":"它标记类似分词的形容词。"},{"word":"di-","structure":"Latin prefix","meaning":"apart","meaningCN":"分开","example":"It forms the mirror word divergence.","exampleCN":"它构成镜像词「分叉」。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb.","exampleCN":"它构成副词。"}],"latinEntries":[{"word":"vergere","structure":"Latin verb","meaning":"to bend","meaningCN":"弯曲"},{"word":"con-","structure":"Latin prefix","meaning":"together","meaningCN":"共同"},{"word":"convergere","structure":"Latin verb","meaning":"to bend together","meaningCN":"一起弯曲"},{"word":"convergentia","structure":"Latin noun","meaning":"convergence","meaningCN":"汇聚；趋同"}],"derivatives":[{"word":"converge","pos":"v.","zh":"同一词根的动词，义为「汇聚；趋同」"},{"word":"convergent","pos":"adj.","zh":"加形容词词尾构成，义为「汇聚的」"},{"word":"convergently","pos":"adv.","zh":"加副词词尾构成，义为「以趋同方式」"},{"word":"divergence","pos":"n.","zh":"加表示分开的前缀构成，义为「分叉」"},{"word":"divergent","pos":"adj.","zh":"加表示分开的前缀与形容词词尾构成，义为「分叉的」"}]}},{"word":"credibility","ipa_uk":"/ˌkredəˈbɪləti/","ipa_us":"/ˌkredəˈbɪləti/","definition_zh":"可信度；可信性；信誉","definition_en":"the quality of being believed or trusted","core_image":"记者把三份文件摊在桌上，镜头对准盖章页，编辑仍逐条核对来源","scene":"记者把三份文件摊在桌上，镜头对准盖章页，编辑仍逐条核对来源。The paper's credibility suffered after the retraction.","sceneCN":"这里指媒体被信任的程度（第 2 个义项：信誉）；句意为撤稿之后这家报纸的信誉受损。图中可辨识物件：文件、印章、镜头、核对清单。","pos":[{"tag":"n.","zh":"名词：可信度；可信性；信誉（不可数）"}],"collocations":[{"phrase":"credibility of the evidence","zh":"证据的可信度"},{"phrase":"lose credibility","zh":"失去信誉"},{"phrase":"restore credibility","zh":"恢复信誉"},{"phrase":"credibility gap","zh":"信任差距"},{"phrase":"scientific credibility","zh":"科学可信度"},{"phrase":"witness credibility","zh":"证人的可信性"}],"forms":[{"label":"单数","form":"credibility"},{"label":"形容词","form":"credible（可信的）"},{"label":"副词","form":"credibly（可信地）"},{"label":"反义名词","form":"incredibility（难以置信）"},{"label":"反义形容词","form":"incredible（难以置信的）"},{"label":"动词同族","form":"credit（相信；记入贷方）"}],"derivatives":[{"word":"credible","pos":"adj.","zh":"由拉丁词根加表示「可……的」词尾构成，义为「可信的」"},{"word":"credibly","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「可信地」"},{"word":"incredible","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「难以置信的」"},{"word":"incredulity","pos":"n.","zh":"由表示「不」的前缀加表示「相信」的词根构成，义为「不肯相信」"},{"word":"credit","pos":"n./v.","zh":"同一词根的名词与动词，义为「信任；信贷；把……归功于」"}],"senses":[{"no":"01","title":"Believability of a claim","titleCN":"说法的可信","definition":"the quality of a statement being likely to be true","definitionCN":"某个说法很可能为真的性质","example":"The credibility of the claim depends on the source of the figures.","exampleCN":"这个说法的可信度取决于数字的来源。","why":"Credibility is not truth itself but the likelihood that a claim is true.","whyCN":"可信度不是真本身，而是一个说法为真的可能性。"},{"no":"02","title":"Trust in a person or institution","titleCN":"人或机构的信誉","definition":"the quality of a person or body being trusted to act honestly","definitionCN":"个人或机构被信任会诚实行事的性质","example":"The newspaper's credibility fell after the retraction.","exampleCN":"撤稿之后这家报纸的信誉下降。","why":"A reputation is built slowly and lost quickly, which is why the word often follows lose and restore.","whyCN":"信誉积得慢、失得快，所以这个词常与「失去」「恢复」连用。"},{"no":"03","title":"Strength of research evidence","titleCN":"研究证据的可信","definition":"the quality of evidence being strong enough to be believed by experts","definitionCN":"证据强到足以让专家相信的性质","example":"Peer review is meant to test the credibility of the findings.","exampleCN":"同行评审意在检验研究结果的可信度。","why":"Claims that no expert can check are taken on trust alone, so the word marks the difference between belief and verification.","whyCN":"无人能核验的说法只能靠信任，这个词因此标记出「相信」与「验证」之间的差别。"},{"no":"04","title":"The credibility gap","titleCN":"信任差距","definition":"a gap between what an authority says and what people are willing to believe","definitionCN":"权威所说与公众愿意相信之间的差距","example":"The credibility gap widened after the third denial.","exampleCN":"第三次否认之后，信任差距进一步扩大。","why":"When official statements and visible facts diverge, trust is measured as a gap.","whyCN":"当官方说法与可见事实分道扬镳，信任就被量成一道缺口。"},{"no":"05","title":"Media credibility","titleCN":"媒体的公信力","definition":"the trust readers place in a news organisation's reporting","definitionCN":"读者对新闻机构报道的信任","example":"Surveys track media credibility across different outlets.","exampleCN":"调查追踪不同媒体机构的公信力。","why":"A newsroom sells belief as much as information, so its standing is measured by this word.","whyCN":"新闻机构不只卖信息，也卖相信，因此它的地位用这个词来衡量。"},{"no":"06","title":"Witness credibility in law","titleCN":"法律上证人的可信性","definition":"the quality of a witness being believed, judged by consistency and demeanour","definitionCN":"证人是否被相信的性质，靠陈述一致性与举止判断","example":"The judge assessed the credibility of the witness.","exampleCN":"法官评估了这名证人的可信性。","why":"Courts cannot test whether a witness is truthful directly, so they weigh consistency, motive and manner instead.","whyCN":"法庭无法直接检验证人是否诚实，只能改看陈述一致性、动机与举止。"},{"no":"07","title":"Credibility of a threat","titleCN":"威胁的可信性","definition":"the quality of a threat being believed enough to deter action","definitionCN":"威胁被相信到足以阻止行动的性质","example":"Deterrence rests on the credibility of the threat.","exampleCN":"威慑建立在威胁的可信度上。","why":"A threat that no one believes changes no one's plan, so credibility is the working part of deterrence.","whyCN":"无人相信的威胁改变不了任何人的计划，所以可信性才是威慑真正起作用的部分。"},{"no":"08","title":"Financial credibility","titleCN":"财务上的信用","definition":"the standing of a borrower that makes lenders willing to lend","definitionCN":"借款人让放贷方愿意出借的地位","example":"Banks reviewed the credibility of the borrower before the loan.","exampleCN":"银行在放款前审查了借款人的信用。","why":"Lending is a bet on future honesty, and the word names the borrower's side of that bet.","whyCN":"放贷是在赌对方未来守约，这个词指借款人在这个赌局里的那一半。"},{"no":"09","title":"Credibility as rhetorical ethos","titleCN":"修辞中的可信品格","definition":"the impression of trustworthiness a speaker creates in an argument","definitionCN":"演讲者在论证中造成的可信印象","example":"The speech gained credibility from the speaker's record of service.","exampleCN":"这场演讲因演讲者长期的公共服务经历而增可信度。","why":"Ancient rhetoric called the speaker's apparent character ethos, and this word is its modern name.","whyCN":"古代修辞学把演讲者显露的品格称作「品格诉诸」，这个词就是它的现代名称。"}],"etymology":{"intro":{"en":"Credibility comes from Latin credibilis, worthy of belief, from credere, to believe or trust. The noun credibilitas is Late Latin. English received the word through French in the sixteenth century.","cn":"这个词来自拉丁语 credibilis「值得相信的」，源头是动词 credere「相信、托付」。名词形式是晚期拉丁语。英语经法语在十六世纪引入。"},"items":[{"era":"LATIN CREDERE","en":"The verb meant to believe, trust or entrust, and it also stands behind credit and creed.","cn":"这个动词意为相信、信任、托付，也是「信贷」与「信条」等词的源头。"},{"era":"LATIN CREDIBILIS","en":"The adjective meant worthy of belief, formed with the suffix of possibility.","cn":"这个形容词意为值得相信的，由表示可能的词尾构成。"},{"era":"LATIN CREDIBILITAS","en":"The Late Latin noun named the quality of being believable.","cn":"晚期拉丁语名词指「可被相信」的性质。"},{"era":"FRENCH AND ENGLISH, 16TH CENTURY","en":"French carried the noun into English, first for the believability of reports.","cn":"法语把这个名词带进英语，最初指报道的可信性。"},{"era":"MODERN EXTENSIONS","en":"Later usage applied it to institutions, evidence, threats and borrowers.","cn":"后来的用法把它用于机构、证据、威胁与借款人。"},{"era":"THE TRUST SENSE","en":"The shift from a claim being believable to a person being trusted is recorded only approximately.","cn":"从「说法可信」转向「人被信任」这一变化，只有大致的年代记录。"}]},"similar":{"note":{"en":"The first group shares the root or its negative; the second group names similar grounds for belief.","cn":"第一组共享词根或其否定形式；第二组是类似的相信依据。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"credible","ipa":"/ˈkredəbl/","tag":"same root","definition":"The adjective meaning able to be believed.","definitionCN":"形容词，意为可信的。"},{"word":"credibly","ipa":"/ˈkredəbli/","tag":"same root","definition":"In a believable manner.","definitionCN":"指以可信的方式。"},{"word":"incredible","ipa":"/ɪnˈkredəbl/","tag":"same root","definition":"Not believable, or informal for astonishing.","definitionCN":"指难以置信的，口语中也指惊人的。"},{"word":"incredulity","ipa":"/ˌɪnkrəˈdjuːləti/","tag":"same root","definition":"Unwillingness to believe.","definitionCN":"指不肯相信。"},{"word":"credit","ipa":"/ˈkredɪt/","tag":"same root","definition":"Trust extended to a borrower, and recognition given to a person.","definitionCN":"指给予借款人的信用，也指给予某人的肯定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"believability","ipa":"/bɪˌliːvəˈbɪləti/","tag":"near meaning","definition":"The quality of being easy to believe.","definitionCN":"指容易被相信的性质。"},{"word":"trustworthiness","ipa":"/ˈtrʌstwɜːðinəs/","tag":"near meaning","definition":"The quality of deserving trust.","definitionCN":"指值得信任的性质。"},{"word":"reliability","ipa":"/rɪˌlaɪəˈbɪləti/","tag":"near meaning","definition":"The quality of performing consistently and dependably.","definitionCN":"指稳定可靠的性质。"},{"word":"plausibility","ipa":"/ˌplɔːzəˈbɪləti/","tag":"near meaning","definition":"The quality of seeming reasonable rather than proven.","definitionCN":"指看似合理而非已被证明。"},{"word":"standing","ipa":"/ˈstændɪŋ/","tag":"near meaning","definition":"A person's or body's reputation in a field.","definitionCN":"指个人或机构在某一领域的声望。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the verb to believe, and the places where belief is tested.","cn":"正常联想沿着「相信」这个动词，以及信任受检验的各个场合。"},"normal":[{"en":"The root verb means to believe, so credibility is the door through which belief enters.","cn":"词根意为相信，所以可信度是「相信」进入的那道门。"},{"en":"A newspaper loses credibility after a retraction, which shows trust is slower to build than to lose.","cn":"报纸撤稿后信誉受损，说明信任积得慢、失得快。"},{"en":"Peer review is an organised test of the credibility of findings.","cn":"同行评审是对研究结果可信度的制度化检验。"},{"en":"Deterrence rests on the credibility of a threat, because an unbelievable threat deters no one.","cn":"威慑建立在威胁的可信性上，因为无人相信的威胁吓不住人。"},{"en":"Judges weigh witness credibility by consistency of account.","cn":"法官靠陈述是否一致来衡量证人的可信性。"}],"abstract":[{"en":"Credibility is a loan: others lend you their belief and watch whether you repay it.","cn":"可信度是一笔贷款：别人把信任借给你，再看你还不还。"},{"en":"Truth and trust are different currencies, and this word exchanges one for the other.","cn":"真与信任是两种货币，这个词在两者之间兑换。"},{"en":"An authority is only as strong as the gap between its words and what people see.","cn":"权威的强弱，取决于它的话与人们所见之间的那道缺口。"}]},"examples":[{"en":"The credibility of the survey was undermined by a small sample.","cn":"这项调查的可信度因样本太小而受损。"},{"en":"The minister never recovered the credibility lost in the scandal.","cn":"部长始终未能挽回丑闻中失去的信誉。"},{"en":"Cross-examination tested the credibility of each witness.","cn":"交叉询问检验了每位证人的可信性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「克瑞德比勒提」——别人愿意把「信」借给你，就是有「可信度」：可信度、信誉","word":"credibility"},"root":"来自拉丁语 credibilis「值得相信的」，源头 credere「相信、托付」；名词形式为晚期拉丁语 credibilitas。英语经法语在十六世纪引入，确切首见年代不确定。","sensesIntro":{"en":"Nine senses test belief in a claim, an institution, evidence, a gap, the media, a witness, a threat, a borrower and a speaker.","cn":"九个义项分别检验对说法、机构、证据、缺口、媒体、证人、威胁、借款人与演讲者的相信。"},"semanticMap":{"core":{"en":"CORE IMAGE: three documents on a desk, a camera on the sealed page, and an editor still checking the source line by line.","cn":"核心意象：桌上三份文件、对准盖章页的镜头，以及仍在逐条核对来源的编辑。"},"chain":["TO BELIEVE","WORTHY OF BELIEF","BELIEVED CLAIM","TRUSTED PERSON","TRUSTED INSTITUTION","BELIEVED THREAT"],"branches":[{"senses":"01","en":"THE CLAIM THAT HOLDS: a statement seems likely to be true.","cn":"站得住的说法：某个陈述很可能为真。"},{"senses":"02 · 05 · 09","en":"THE TRUSTED VOICE: a person, a newsroom or a speaker earns belief.","cn":"被信任的声音：个人、新闻机构或演讲者赢得相信。"},{"senses":"03","en":"THE TESTED EVIDENCE: peer review asks whether findings deserve belief.","cn":"受检验的证据：同行评审追问研究结果是否值得相信。"},{"senses":"04","en":"THE GAP: words and visible facts drift apart, and trust is measured as a distance.","cn":"缺口：言辞与可见事实分开，信任被量成距离。"},{"senses":"06 · 07 · 08","en":"THE LEGAL, MILITARY AND FINANCIAL FORMS: a witness, a threat and a borrower must all be believed.","cn":"法律、军事与财务形态：证人、威胁与借款人都必须被相信。"}]},"affixes":{"intro":{"en":"The word is built on the Latin verb to believe plus a suffix of possibility, so its core is worthiness of belief.","cn":"这个词建在表示「相信」的拉丁动词上，再加上表示可能的词尾，核心是「值得被相信」。"},"latinIntro":{"en":"Latin supplies the verb of believing, the adjective of worthiness and the Late Latin noun.","cn":"拉丁语提供了表示相信的动词、表示值得的形容词与晚期拉丁语名词。"},"items":[{"word":"credere","structure":"Latin verb","meaning":"to believe, to trust","meaningCN":"相信；信任","example":"It also stands behind credit and creed.","exampleCN":"它也是「信贷」与「信条」的源头。"},{"word":"-ibilis","structure":"Latin suffix","meaning":"that can be","meaningCN":"可以被……的","example":"It makes the adjective worthy of belief.","exampleCN":"它构成表示「值得相信」的形容词。"},{"word":"credibilis","structure":"Latin adjective","meaning":"believable","meaningCN":"可信的","example":"The adjective is the direct source.","exampleCN":"这个形容词是直接源头。"},{"word":"credibilitas","structure":"Late Latin noun","meaning":"believability","meaningCN":"可信性","example":"The noun supplied the English word.","exampleCN":"这个名词提供了英语词。"},{"word":"credibility","structure":"English noun","meaning":"the quality of being believed","meaningCN":"可信度；信誉","example":"English widened it from claims to people.","exampleCN":"英语把它从说法扩展到人。"},{"word":"credible","structure":"English adjective","meaning":"believable","meaningCN":"可信的","example":"The adjective drops the noun ending.","exampleCN":"这个形容词去掉了名词词尾。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不","example":"It forms incredible, beyond belief.","exampleCN":"它构成表示「难以相信」的形容词。"},{"word":"-ity","structure":"Latin noun ending","meaning":"the quality of","meaningCN":"……的性质","example":"It turns the adjective into a noun.","exampleCN":"它把形容词变成名词。"},{"word":"credit","structure":"English noun and verb","meaning":"trust; to believe or attribute","meaningCN":"信用；相信；归功","example":"The same verb of believing underlies it.","exampleCN":"同一个「相信」动词是它的底子。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb credibly.","exampleCN":"它构成副词。"}],"latinEntries":[{"word":"credere","structure":"Latin verb","meaning":"to believe, trust","meaningCN":"相信；信任"},{"word":"-ibilis","structure":"Latin suffix","meaning":"that can be","meaningCN":"可以被……的"},{"word":"credibilis","structure":"Latin adjective","meaning":"believable","meaningCN":"可信的"},{"word":"credibilitas","structure":"Late Latin noun","meaning":"believability","meaningCN":"可信性"}],"derivatives":[{"word":"credible","pos":"adj.","zh":"加表示可能的词尾构成，义为「可信的」"},{"word":"credibly","pos":"adv.","zh":"加副词词尾构成，义为「可信地」"},{"word":"incredible","pos":"adj.","zh":"加否定前缀构成，义为「难以置信的」"},{"word":"incredulity","pos":"n.","zh":"加表示「不」的前缀与名词词尾构成，义为「不肯相信」"},{"word":"credit","pos":"n./v.","zh":"同一词根，义为「信用；相信」"}]}},{"word":"culmination","ipa_uk":"/ˌkʌlmɪˈneɪʃn/","ipa_us":"/ˌkʌlmɪˈneɪʃn/","definition_zh":"顶点；最高潮；最终成果；达到顶峰的阶段","definition_en":"the highest or climactic point that a process reaches, or the act of reaching it","core_image":"登山队在最后一段雪坡上排成一列，把旗子插上峰顶","scene":"登山队在最后一段雪坡上排成一列，把旗子插上峰顶。The summit was the culmination of ten years of planning.","sceneCN":"这里指长期努力达到的最高点（第 1 个义项：顶点、最高潮）；句意为登顶是十年筹划的顶点。图中可辨识物件：雪坡、冰镐、旗子、峰顶。","pos":[{"tag":"n.","zh":"名词：顶点；最高潮；最终成果（可数，常用单数）"}],"collocations":[{"phrase":"the culmination of years of work","zh":"多年工作的顶点"},{"phrase":"reach a culmination","zh":"达到顶点"},{"phrase":"culmination of a career","zh":"职业生涯的顶峰"},{"phrase":"culmination of the ceremony","zh":"典礼的高潮"},{"phrase":"culmination of the season","zh":"赛季的收官高潮"},{"phrase":"a fitting culmination","zh":"一个恰当的收尾"}],"forms":[{"label":"单数","form":"culmination"},{"label":"复数","form":"culminations（多个顶点）"},{"label":"动词","form":"culminate（达到顶点；以……告终）"},{"label":"形容词","form":"culminating（达到顶点的）"},{"label":"搭配介词","form":"culminate in / culminate with（以……告终）"}],"derivatives":[{"word":"culminate","pos":"v.","zh":"同一词根的动词，义为「达到顶点；以……告终」"},{"word":"culminating","pos":"adj.","zh":"由该动词加现在分词词尾构成，义为「达到顶点的」"},{"word":"culminant","pos":"adj.","zh":"由该词根加形容词词尾构成，义为「处于最高点的」"},{"word":"culmination","pos":"n.","zh":"由该词根加名词词尾构成，义为「顶点；最高潮」"},{"word":"culmen","pos":"n.","zh":"同一拉丁词根的直接借用，义为「山顶；最高点」"}],"senses":[{"no":"01","title":"The highest point of a long effort","titleCN":"长期努力的最高点","definition":"the point at which a long process reaches its highest level","definitionCN":"一个长期过程达到最高水平的时刻","example":"The summit was the culmination of ten years of planning.","exampleCN":"登顶是十年筹划的顶点。","why":"The Latin noun for a mountain top gave the word its shape: a process climbs and ends at a peak.","whyCN":"拉丁语中表示山顶的名词给了它形状：一个过程向上爬，最后停在峰顶。"},{"no":"02","title":"The final result of a process","titleCN":"过程的最终成果","definition":"the finished outcome in which earlier stages are gathered up","definitionCN":"把先前各阶段收拢在一起的最终结果","example":"The treaty was the culmination of months of quiet talks.","exampleCN":"这项条约是数月低调谈判的最终成果。","why":"A peak gathers everything below it, so the last stage stands for the whole effort.","whyCN":"峰顶把下方的一切都收拢起来，因此最后一阶段代表全部努力。"},{"no":"03","title":"The peak of a career","titleCN":"职业生涯的顶峰","definition":"the most successful or honoured moment of a working life","definitionCN":"职业生活中最成功或最受尊崇的时刻","example":"The award marked the culmination of her career.","exampleCN":"这个奖项标志着她职业生涯的顶峰。","why":"A working life rises and then levels off, and the word marks the moment it stands highest.","whyCN":"职业生涯会上升然后走平，这个词标记它站在最高处的那一刻。"},{"no":"04","title":"The climax of a ceremony","titleCN":"典礼的高潮","definition":"the most solemn or exciting moment of a formal event","definitionCN":"正式活动中最庄严或最激动人心的时刻","example":"The lighting of the flame was the culmination of the ceremony.","exampleCN":"点燃圣火是典礼的高潮。","why":"A ceremony is built as a slope, and the word names the step everyone waits for.","whyCN":"典礼像一段斜坡，这个词点出所有人都在等的那一步。"},{"no":"05","title":"The peak of a trend, including a bad one","titleCN":"趋势的顶点（含负面）","definition":"the point at which a development reaches its extreme before turning","definitionCN":"某种发展在转向之前达到极端的时刻","example":"The crisis was the culmination of months of tension.","exampleCN":"这场危机是数月紧张局势的顶点。","why":"A peak can be a summit or a breaking point; the word covers both.","whyCN":"顶点可以是登顶，也可以是崩断点，这个词两者都管。"},{"no":"06","title":"Astronomical culmination","titleCN":"天文上的中天","definition":"the moment a celestial body reaches its highest point above the horizon","definitionCN":"天体到达地平线以上最高点的时刻","example":"The star's culmination occurs shortly after midnight.","exampleCN":"这颗星的最高点出现在午夜过后不久。","why":"Astronomy kept the literal meaning: the body is literally at the top of its arc.","whyCN":"天文学保留了字面义：天体确实处在其弧线的最高处。"},{"no":"07","title":"The climax of a story or artwork","titleCN":"故事或艺术作品的顶点","definition":"the most intense point of a narrative or composition","definitionCN":"叙事或作品中最强烈的时刻","example":"The final movement is the culmination of the whole symphony.","exampleCN":"最后一个乐章是整部交响曲的顶点。","why":"A composition gathers its themes into one last passage, and that passage is the peak the word names.","whyCN":"作品把各个主题收进最后一段，那一段就是这个词所指的高点。"},{"no":"08","title":"The finale of a season or competition","titleCN":"赛季或赛事的收官高潮","definition":"the last and highest event that closes a series of contests","definitionCN":"结束一系列赛事的最后一场高潮","example":"The final match was the culmination of a long season.","exampleCN":"决赛是整个漫长赛季的收官高潮。","why":"A series needs an ending that outranks every earlier round, and the word supplies that ranking.","whyCN":"一连串赛事需要一个压过此前各轮的分量收尾，这个词提供这种排序。"}],"etymology":{"intro":{"en":"Culmination comes from Late Latin culminatio, from culminare, to reach the top, from culmen, a summit or roof. English took the noun in the seventeenth century, first for astronomy and then for human affairs.","cn":"这个词来自晚期拉丁语 culminatio，源头是动词 culminare「到达顶端」，后者出自名词 culmen「山顶、屋顶」。英语在十七世纪借入这个名词，先用于天文，后用于人事。"},"items":[{"era":"LATIN CULMEN","en":"The noun meant a summit, a roof or the top of anything.","cn":"这个名词意为山顶、屋顶或任何东西的顶端。"},{"era":"LATIN CULMINARE","en":"The verb meant to raise to the top or to reach the summit.","cn":"这个动词意为抬到顶端或到达峰顶。"},{"era":"LATE LATIN CULMINATIO","en":"The noun named the act of reaching the highest point.","cn":"这个名词指到达最高点的行为。"},{"era":"ENGLISH, 17TH CENTURY","en":"English used the word first in astronomy, for a star's highest point.","cn":"英语最初在天文中使用这个词，指一颗星的最高点。"},{"era":"THE HUMAN EXTENSION","en":"Later usage applied it to careers, ceremonies and finished works.","cn":"后来的用法把它用于职业、典礼与完成的作品。"},{"era":"THE NEGATIVE CLIMAX","en":"Modern usage also calls a crisis the culmination of a trend; the date of that extension is uncertain.","cn":"现代用法也把危机称为某种趋势的顶点；这一扩展的年代不确定。"}]},"similar":{"note":{"en":"The first group shares the root or the top-of-arc image; the second group names neighbouring high points.","cn":"第一组共享词根或「弧线最高点」的意象；第二组是相邻的高点概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"culminate","ipa":"/ˈkʌlmɪneɪt/","tag":"same root","definition":"The verb meaning to reach the highest point or end in something.","definitionCN":"动词，意为达到顶点或以某结果告终。"},{"word":"culminating","ipa":"/ˈkʌlmɪneɪtɪŋ/","tag":"same root","definition":"The participle used as an adjective for a peak stage.","definitionCN":"分词作形容词，指达到顶点的。"},{"word":"culminant","ipa":"/ˈkʌlmɪnənt/","tag":"same root","definition":"An adjective for something at its highest point.","definitionCN":"形容词，指处于最高点的。"},{"word":"culmen","ipa":"/ˈkʌlmen/","tag":"same root","definition":"A borrowed Latin noun for a summit.","definitionCN":"借自拉丁语的名词，指山顶。"},{"word":"column","ipa":"/ˈkɒləm/","tag":"related form","definition":"A pillar, from a related word for a tall upright mass.","definitionCN":"指柱子，出自一个表示高耸竖直物的相关词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"climax","ipa":"/ˈklaɪmæks/","tag":"near meaning","definition":"The most intense moment of a narrative or event, stressing intensity rather than height.","definitionCN":"指叙事或事件最强烈的时刻，强调强度而非高度。"},{"word":"peak","ipa":"/piːk/","tag":"near meaning","definition":"The highest level or value reached, often in graphs.","definitionCN":"指达到的最高水平或数值，常用于曲线。"},{"word":"summit","ipa":"/ˈsʌmɪt/","tag":"near meaning","definition":"The top of a mountain, and by extension a meeting of leaders.","definitionCN":"指山峰顶端，引申为领导人会议。"},{"word":"zenith","ipa":"/ˈzenɪθ/","tag":"near meaning","definition":"The point directly above an observer, used figuratively for a high point.","definitionCN":"指观测者正上方的点，喻指高峰。"},{"word":"completion","ipa":"/kəmˈpliːʃn/","tag":"near meaning","definition":"The act of finishing rather than the highest point.","definitionCN":"指完成的行为，而非最高点。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the literal image of a mountain top, then follow the word into careers, ceremonies and stories.","cn":"正常联想使用山顶的字面意象，再把这个词走到职业、典礼与故事里。"},"normal":[{"en":"The Latin noun meant the top of a mountain, so culmination is the moment a long climb ends.","cn":"拉丁名词意为山顶，所以这个词就是漫长攀登结束的那一刻。"},{"en":"The treaty ending months of talks is the finished result, not merely the last event.","cn":"结束数月谈判的条约是最终成果，而不只是最后一场活动。"},{"en":"An award can mark the culmination of a career, the highest point of a working life.","cn":"奖项可以标志职业生涯的顶点，即职业生涯的最高处。"},{"en":"Astronomy uses the word literally for a star at the top of its arc.","cn":"天文学用它的字面义，指处在弧线最高处的星。"},{"en":"A crisis can be the culmination of tension, because a peak may also be a breaking point.","cn":"危机可以是紧张局势的顶点，因为顶点也可能是崩断点。"}],"abstract":[{"en":"A peak is the smallest possible place from which everything below can be seen.","cn":"峰顶是最小的位置，却能从那里看见下方的一切。"},{"en":"Not every culmination is happy: some are simply the last point before a fall.","cn":"并非每个顶点都令人欣喜：有些只是坠落前的最后一点。"},{"en":"The word gathers time into a single height, which is why we remember summits and forget slopes.","cn":"这个词把时间收进一个高度，所以我们记住峰顶，忘了斜坡。"}]},"examples":[{"en":"The exhibition was the culmination of five years of research.","cn":"这场展览是五年研究的顶点。"},{"en":"His retirement speech was the culmination of a long career.","cn":"他的退休演说是一段漫长职业生涯的顶点。"},{"en":"The festival's culmination came with the final procession.","cn":"节庆的顶点出现在最后的游行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「卡尔米内申」——一路往上爬，最后站到最高的那一点，就是「顶点、高潮」：顶点、最高潮","word":"culmination"},"root":"来自晚期拉丁语 culminatio，源头动词 culminare「到达顶端」，后者出自 culmen「山顶、屋顶」；英语在十七世纪借入，先用于天文，后用于人事。","sensesIntro":{"en":"Eight senses keep one shape, a process rising to its top: an effort, a result, a career, a ceremony, a trend, a star, a work and a season.","cn":"八个义项保持同一个形状，即过程升到顶端：努力、成果、职业、典礼、趋势、星体、作品与赛季。"},"semanticMap":{"core":{"en":"CORE IMAGE: a climbing team roped on the last snow slope, a flag planted on the summit.","cn":"核心意象：最后一段雪坡上结组而行的登山队，以及插上峰顶的旗。"},"chain":["MOUNTAIN TOP","REACHING THE TOP","HIGHEST POINT","FINAL RESULT","PUBLIC CLIMAX","LAST BEFORE THE FALL"],"branches":[{"senses":"01 · 03","en":"THE HIGHEST POINT: a long effort or a working life reaches its peak.","cn":"最高点：长期努力或职业生涯达到顶峰。"},{"senses":"02 · 08","en":"THE FINAL RESULT: the treaty and the final match gather the stages below them.","cn":"最终成果：条约与决赛把下面的各阶段收拢起来。"},{"senses":"04 · 07","en":"THE PUBLIC CLIMAX: a ceremony and a work of art reach their most intense moment.","cn":"公开的高潮：典礼与艺术作品达到最强烈的时刻。"},{"senses":"05","en":"THE PEAK OF A TREND: tension can culminate in a crisis.","cn":"趋势的顶点：紧张局势可以以危机告终。"},{"senses":"06","en":"THE LITERAL ARC: a star stands at the top of its path across the sky.","cn":"字面的弧线：星体处在它横过天空的路径最高处。"}]},"affixes":{"intro":{"en":"The word is built on a Latin noun for a summit, so its parts describe a top and the act of reaching it.","cn":"这个词建在表示山顶的拉丁名词上，各部件描述一个顶端与到达它的动作。"},"latinIntro":{"en":"Latin supplies the noun for a summit, the verb of reaching it and the Late Latin noun of the act.","cn":"拉丁语提供了表示山顶的名词、表示到达的动词，以及晚期拉丁语中表示该行为的名词。"},"items":[{"word":"culmen","structure":"Latin noun","meaning":"summit, roof, top","meaningCN":"山顶；屋顶；顶端","example":"The noun gives the word its height.","exampleCN":"这个名词给这个词高度。"},{"word":"culminare","structure":"Latin verb","meaning":"to reach the top","meaningCN":"到达顶端","example":"The verb describes the climb's last step.","exampleCN":"这个动词描述攀登的最后一步。"},{"word":"culminatio","structure":"Late Latin noun","meaning":"a reaching of the top","meaningCN":"到达顶端","example":"The noun supplied the English word.","exampleCN":"这个名词提供了英语词。"},{"word":"culminate","structure":"English verb","meaning":"to reach the highest point","meaningCN":"达到顶点","example":"English formed the verb from the same stem.","exampleCN":"英语由同一词干构成动词。"},{"word":"-ate","structure":"Latin verb ending","meaning":"to make or act","meaningCN":"做；使","example":"It marks the English verb.","exampleCN":"它标记英语动词。"},{"word":"-ing","structure":"English participle ending","meaning":"in the process of","meaningCN":"正在……","example":"It forms the adjective for a peak stage.","exampleCN":"它构成表示顶点阶段的形容词。"},{"word":"-ation","structure":"Latin noun ending","meaning":"the act or result","meaningCN":"动作或结果","example":"It forms the noun of the act.","exampleCN":"它构成表示行为的名称。"},{"word":"culmination","structure":"English noun","meaning":"the highest point reached","meaningCN":"顶点；最高潮","example":"The noun now covers careers and stories.","exampleCN":"这个名词如今也管职业与故事。"},{"word":"-ant","structure":"Latin adjective ending","meaning":"being in a state","meaningCN":"处于某状态","example":"It forms a rare adjective for the highest.","exampleCN":"它构成表示最高点的少见形容词。"},{"word":"in","structure":"English preposition","meaning":"reaching a result","meaningCN":"达到某结果","example":"The verb culminate is followed by in.","exampleCN":"动词之后常接介词表示结果。"}],"latinEntries":[{"word":"culmen","structure":"Latin noun","meaning":"summit, top","meaningCN":"山顶；顶端"},{"word":"culminare","structure":"Latin verb","meaning":"to reach the top","meaningCN":"到达顶端"},{"word":"culminatio","structure":"Late Latin noun","meaning":"a reaching of the top","meaningCN":"到达顶端"}],"derivatives":[{"word":"culminate","pos":"v.","zh":"由同一词干构成，义为「达到顶点」"},{"word":"culminating","pos":"adj.","zh":"加现在分词词尾构成，义为「达到顶点的」"},{"word":"culminant","pos":"adj.","zh":"加形容词词尾构成，义为「处于最高点的」"},{"word":"culmen","pos":"n.","zh":"直接借自拉丁语，义为「山顶」"},{"word":"culmination","pos":"n.","zh":"加名词词尾构成，义为「顶点」"}]}},{"word":"discrepancy","ipa_uk":"/dɪˈskrepənsi/","ipa_us":"/dɪˈskrepənsi/","definition_zh":"差异；不一致；出入；账目差额","definition_en":"a difference between two things that ought to match","core_image":"两本账簿摊在同一张桌上，同一笔支出在两边写着不同的数字","scene":"两本账簿摊在同一张桌上，同一笔支出在两边写着不同的数字。Auditors found a discrepancy between the two ledgers.","sceneCN":"这里指本应一致的两份记录出现差异（第 1 个义项：差异、不一致）；句意为审计人员发现两本账簿之间有出入。图中可辨识物件：账簿、两支笔、计算器、放大镜。","pos":[{"tag":"n.","zh":"名词：差异；不一致；出入（可数）"}],"collocations":[{"phrase":"a discrepancy between the two accounts","zh":"两份账目之间的差异"},{"phrase":"discrepancy in the data","zh":"数据中的出入"},{"phrase":"explain the discrepancy","zh":"解释这一差异"},{"phrase":"large discrepancy","zh":"巨大差异"},{"phrase":"discrepancy between theory and practice","zh":"理论与实践之间的不一致"},{"phrase":"audit discrepancy","zh":"审计差异"}],"forms":[{"label":"单数","form":"discrepancy"},{"label":"复数","form":"discrepancies（多处不一致）"},{"label":"形容词","form":"discrepant（不一致的）"},{"label":"副词","form":"discrepantly（不一致地）"},{"label":"动词同族","form":"discrepate（不一致，少用）"}],"derivatives":[{"word":"discrepant","pos":"adj.","zh":"由该词根加形容词词尾构成，义为「不一致的；相异的」"},{"word":"discrepantly","pos":"adv.","zh":"由该形容词加副词词尾构成，义为「以不一致的方式」"},{"word":"discrepancy","pos":"n.","zh":"由拉丁名词经法语进入英语，义为「差异；出入」"},{"word":"discrepancies","pos":"n.","zh":"该名词的复数，义为「多处不一致」"}],"senses":[{"no":"01","title":"A difference between things that should match","titleCN":"本应相符之物出现差异","definition":"a difference between two facts, figures or accounts that are expected to agree","definitionCN":"本应一致的两项事实、数字或记录之间出现的差别","example":"Auditors found a discrepancy between the two ledgers.","exampleCN":"审计人员发现两本账簿之间有出入。","why":"The Latin verb meant to sound discordantly, so a discrepancy is two records refusing to sound alike.","whyCN":"拉丁动词意为「响声不谐」，因此差异就是两份记录的声音对不上。"},{"no":"02","title":"An accounting difference","titleCN":"账目差额","definition":"a difference in a bookkeeping entry that prevents the books from balancing","definitionCN":"使账目不平的一处记账差别","example":"A discrepancy of two hundred units delayed the audit.","exampleCN":"一笔两百单位的差额拖慢了审计。","why":"A ledger is a set of figures that must agree, and any figure that does not add up is flagged by this word.","whyCN":"账簿是一组必须对上的数字，任何加不平的数字都用这个词标出。"},{"no":"03","title":"A measurement difference","titleCN":"测量差异","definition":"a difference between two measurements of the same quantity","definitionCN":"同一数量两次测量之间出现的差别","example":"The discrepancy between the two instruments pointed to a loose sensor.","exampleCN":"两台仪器之间的测量差异指向一个松动的传感器。","why":"Two instruments aimed at one quantity should read alike, so their disagreement is itself evidence.","whyCN":"两台仪器测同一个量本应读数相同，因此它们的不一致本身就是证据。"},{"no":"04","title":"A gap between theory and data","titleCN":"理论与数据的差距","definition":"a difference between what a model predicts and what is observed","definitionCN":"模型预测与观测结果之间的差别","example":"The discrepancy between prediction and observation forced a revision.","exampleCN":"预测与观测之间的差距迫使研究修改。","why":"Science advances when a model's promise and nature's answer fail to agree.","whyCN":"当模型的承诺与自然的回答对不上时，科学才向前走。"},{"no":"05","title":"A gap between promise and practice","titleCN":"承诺与做法的差距","definition":"a difference between what is announced and what is actually done","definitionCN":"宣布的内容与实际所做之事之间的差别","example":"The discrepancy between the policy and its enforcement was obvious.","exampleCN":"政策与其执行之间的不一致一目了然。","why":"Words and deeds are two records of the same intention, and the word reports that they do not match.","whyCN":"言辞与行动是同一个意图的两份记录，这个词报告两者对不上。"},{"no":"06","title":"An audit or statistical discrepancy","titleCN":"审计或统计差异","definition":"a mismatch uncovered by checking records against one another or against counts","definitionCN":"把记录互相核对或与清点结果核对时发现的不符","example":"The census reported a discrepancy in two districts.","exampleCN":"人口普查报告了两个辖区的一处出入。","why":"Counting twice is the oldest audit, and any gap between the two counts needs a name.","whyCN":"数两遍是最古老的审计，两次清点之间的缺口需要一个名称。"},{"no":"07","title":"A difference between accounts of an event","titleCN":"同一事件的不同说法","definition":"a difference between two people's versions of the same event","definitionCN":"两人对同一事件的叙述之间出现的差别","example":"The discrepancy between the two witnesses puzzled the court.","exampleCN":"两名证人陈述之间的差异让法庭困惑。","why":"Two observers of one event should tell one story, and their divergence is what courts must resolve.","whyCN":"同一件事的两名观察者本应讲出一个版本，他们的分歧正是法庭要解决的。"},{"no":"08","title":"A discrepancy in replication","titleCN":"重复实验中的不一致","definition":"a failure of a second experiment to reproduce the first result","definitionCN":"第二次实验未能再现第一次结果","example":"The discrepancy between the two trials raised doubts about the finding.","exampleCN":"两次试验之间的不一致使人们对结论产生怀疑。","why":"Replication is a second record of the same effect, and a mismatch weakens the first claim.","whyCN":"重复实验是同一效应的第二份记录，对不上就削弱了第一个结论。"}],"etymology":{"intro":{"en":"Discrepancy comes from Latin discrepantia, discordance, from discrepare, to sound discordantly, built from dis-, apart, and crepare, to rattle or creak. English took the noun in the seventeenth century.","cn":"这个词来自拉丁语 discrepantia「不和谐」，源头是动词 discrepare「响声不和」，由表示「分开」的前缀与表示「嘎嘎作响」的词根构成。英语在十七世纪借入这个名词。"},"items":[{"era":"LATIN CREPARE","en":"The verb meant to rattle, creak or make a noise, and it also stands behind decrepit.","cn":"这个动词意为嘎嘎作响、吱嘎出声，也是「破旧」一词的源头。"},{"era":"LATIN DIS-","en":"The prefix meant apart or in different directions.","cn":"这个前缀意为分开、朝不同方向。"},{"era":"LATIN DISCREPARE","en":"The compound meant to sound out of tune with one another.","cn":"这个复合动词意为彼此的声音不合调。"},{"era":"LATIN DISCREPANTIA","en":"The noun named the state of not agreeing, first of sounds and then of facts.","cn":"这个名词指不一致的状态，先用于声音，后用于事实。"},{"era":"FRENCH AND ENGLISH, 17TH CENTURY","en":"French carried the noun into English, where it named mismatches in records and accounts.","cn":"法语把这个名词带进英语，用于指记录与账目中的不符。"},{"era":"MODERN EXTENSIONS","en":"Later usage extended it to measurements, statistics, testimony and replication.","cn":"后来的用法把它扩展到测量、统计、证词与重复实验。"}]},"similar":{"note":{"en":"The first group shares the root or the noun ending; the second group names other kinds of difference.","cn":"第一组共享词根或名词词尾；第二组是其他表示差异的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"discrepant","ipa":"/dɪˈskrepənt/","tag":"same root","definition":"The adjective for things that do not agree.","definitionCN":"形容词，指不一致的。"},{"word":"discrepantly","ipa":"/dɪˈskrepəntli/","tag":"same root","definition":"In a manner that does not agree.","definitionCN":"指以不一致的方式。"},{"word":"discrepancies","ipa":"/dɪˈskrepənsiz/","tag":"same root","definition":"The plural, used for several mismatches.","definitionCN":"复数形式，指多处不一致。"},{"word":"discrepate","ipa":"/ˈdɪskrəpeɪt/","tag":"same root","definition":"A rare verb meaning to differ or disagree.","definitionCN":"少见动词，意为不一致。"},{"word":"decrepit","ipa":"/dɪˈkrepɪt/","tag":"related root","definition":"Worn out, from the same verb of creaking.","definitionCN":"指破旧的，出自同一个「吱嘎作响」动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"difference","ipa":"/ˈdɪfrəns/","tag":"near meaning","definition":"The general word for two things not being the same.","definitionCN":"指两物不相同的一般说法。"},{"word":"inconsistency","ipa":"/ˌɪnkənˈsɪstənsi/","tag":"near meaning","definition":"A failure to stay the same from one case to the next.","definitionCN":"指前后未能保持一致。"},{"word":"disparity","ipa":"/dɪˈspærəti/","tag":"near meaning","definition":"A difference in level or condition, often unfair.","definitionCN":"指水平或状况上的差距，常带不公平意味。"},{"word":"variation","ipa":"/ˌveəriˈeɪʃn/","tag":"near meaning","definition":"A change or difference within a range.","definitionCN":"指范围内出现的变化或差异。"},{"word":"gap","ipa":"/ɡæp/","tag":"near meaning","definition":"An empty space or a shortfall between two points.","definitionCN":"指空缺或两点之间的落差。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations follow the Latin image of sounds that will not agree, then apply it to books, instruments and testimony.","cn":"正常联想沿着拉丁语中「声音合不到一起」的意象，再把它用到账簿、仪器与证词上。"},"normal":[{"en":"The root verb means to creak, so a discrepancy is two records creaking out of tune.","cn":"词根意为嘎嘎作响，所以差异就是两份记录的响声不合调。"},{"en":"Auditors look for a discrepancy between the ledger and the count.","cn":"审计人员找的是账簿与清点结果之间的出入。"},{"en":"Two instruments measuring the same thing should agree, and their discrepancy points to a fault.","cn":"两台仪器测同一件事本应一致，它们的差异指向某个故障。"},{"en":"A model that predicts one value while observation gives another has a discrepancy to explain.","cn":"模型预测一个值、观测给出另一个值，就有差异需要解释。"},{"en":"Two witnesses telling different stories create a discrepancy for the court.","cn":"两名证人讲出不同版本，就给法庭造成一处不一致。"}],"abstract":[{"en":"A discrepancy is a place where two truths refuse to sit on the same line.","cn":"差异是两个真相不肯坐进同一条线的地方。"},{"en":"Records are promises to agree, and the word reports a broken promise.","cn":"记录是「应当一致」的承诺，这个词报告承诺被违背。"},{"en":"What cannot be made to agree can still be made to explain, which is where research begins.","cn":"无法被凑成一致的东西仍可被解释，研究就从这里开始。"}]},"examples":[{"en":"The discrepancy between the invoice and the order delayed payment.","cn":"发票与订单之间的出入拖慢了付款。"},{"en":"A discrepancy in the two measurements suggested a faulty gauge.","cn":"两次测量间的差异表明仪表有故障。"},{"en":"The committee asked the agency to explain the discrepancy in its figures.","cn":"委员会要求该机构解释数字上的出入。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迪斯克瑞彭西」——两本账对不上，嘎嘎响不到一个调上，就是「差异、不一致」：差异、出入","word":"discrepancy"},"root":"来自拉丁语 discrepantia「不和谐」，源头 discrepare「响声不和」，由 dis-「分开」与 crepare「嘎嘎作响」构成；英语在十七世纪借入，后扩展到测量、统计、证词与重复实验。","sensesIntro":{"en":"Eight senses trace a mismatch through records, accounts, instruments, models, promises, audits, testimony and replication.","cn":"八个义项把「对不上」追到记录、账目、仪器、模型、承诺、审计、证词与重复实验。"},"semanticMap":{"core":{"en":"CORE IMAGE: two ledgers open on one desk, the same expense written in two different figures.","cn":"核心意象：同一张桌上两本摊开的账簿，同一笔支出写着两个不同数字。"},"chain":["OUT OF TUNE","TWO RECORDS","MISMATCH FOUND","BOOKS DO NOT BALANCE","THEORY AND DATA","REPEAT FAILS"],"branches":[{"senses":"01 · 07","en":"THE TWO VERSIONS: records and testimony fail to agree on one event.","cn":"两个版本：记录与证词在同一件事上对不上。"},{"senses":"02 · 06","en":"THE BOOKS AND THE COUNT: an audit finds figures that will not balance.","cn":"账簿与清点：审计发现数字无法轧平。"},{"senses":"03","en":"THE INSTRUMENTS DISAGREE: two measurements of one quantity differ.","cn":"仪器不一致：同一数量的两次测量出现差别。"},{"senses":"04 · 08","en":"THE PREDICTION AND THE REPEAT: a model misses the data, and a second trial misses the first.","cn":"预测与重复：模型对不上数据，第二次试验对不上第一次。"},{"senses":"05","en":"THE PROMISE AND THE PRACTICE: what is announced is not what is done.","cn":"承诺与做法：宣布的内容并非实际所做。"}]},"affixes":{"intro":{"en":"The word is built on a Latin verb of harsh sound, so its core image is two things out of tune.","cn":"这个词建在表示「刺耳声响」的拉丁动词上，核心意象是两样东西不合调。"},"latinIntro":{"en":"Latin supplies the verb of creaking, the prefix of separation, the compound verb and the noun of discord.","cn":"拉丁语提供了表示吱嘎作响的动词、表示分开的前缀、复合动词与表示不谐的名词。"},"items":[{"word":"crepare","structure":"Latin verb","meaning":"to rattle, to creak","meaningCN":"嘎嘎作响；吱嘎","example":"The root supplies the noise image.","exampleCN":"这个词根提供声响意象。"},{"word":"dis-","structure":"Latin prefix","meaning":"apart, in different directions","meaningCN":"分开；朝不同方向","example":"It makes two sounds go apart.","exampleCN":"它让两个声音分开。"},{"word":"discrepare","structure":"Latin verb","meaning":"to sound out of tune","meaningCN":"声音不合调","example":"The verb is the source of the English noun.","exampleCN":"这个动词是英语名词的源头。"},{"word":"discrepantia","structure":"Latin noun","meaning":"discordance","meaningCN":"不和谐；不一致","example":"The noun named the state of disagreement.","exampleCN":"这个名词指不一致的状态。"},{"word":"discrepancy","structure":"English noun","meaning":"a mismatch","meaningCN":"差异；出入","example":"English applied it to accounts and data.","exampleCN":"英语把它用于账目与数据。"},{"word":"discrepant","structure":"English adjective","meaning":"not agreeing","meaningCN":"不一致的","example":"The adjective adds a Latin ending.","exampleCN":"这个形容词加了拉丁词尾。"},{"word":"-ant","structure":"Latin adjective ending","meaning":"being in a state","meaningCN":"处于某状态","example":"It marks the participle-like adjective.","exampleCN":"它标记类似分词的形容词。"},{"word":"-ancy","structure":"Latin noun ending through French","meaning":"the quality or state","meaningCN":"性质或状态","example":"It forms the abstract noun.","exampleCN":"它构成抽象名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in the stated manner","meaningCN":"以所述方式","example":"It forms the adverb.","exampleCN":"它构成副词。"},{"word":"decrepit","structure":"English adjective","meaning":"worn out","meaningCN":"破旧的","example":"A related word from the same verb of creaking.","exampleCN":"出自同一个「吱嘎」动词的相关词。"}],"latinEntries":[{"word":"crepare","structure":"Latin verb","meaning":"to creak","meaningCN":"嘎嘎作响"},{"word":"dis-","structure":"Latin prefix","meaning":"apart","meaningCN":"分开"},{"word":"discrepare","structure":"Latin verb","meaning":"to sound discordantly","meaningCN":"声音不合调"},{"word":"discrepantia","structure":"Latin noun","meaning":"discordance","meaningCN":"不和谐；不一致"}],"derivatives":[{"word":"discrepant","pos":"adj.","zh":"加形容词词尾构成，义为「不一致的」"},{"word":"discrepantly","pos":"adv.","zh":"加副词词尾构成，义为「以不一致方式」"},{"word":"discrepancy","pos":"n.","zh":"由拉丁名词经法语进入英语，义为「差异」"},{"word":"discrepancies","pos":"n.","zh":"该名词的复数，义为「多处不一致」"}]}}]);
